window.CUSTOM_SCHEMAS = {"100": [{"formule": "ℝ = ensemble des nombres réels", "imgPath": "assets/schemas/100-0-droite-reelle.svg", "titre": "La droite réelle", "caption": "ℝ contient à la fois les rationnels (3/2, calculé exactement) et les irrationnels (√2 ≈ 1,41421356..., calculé par extraction de racine) sur une même droite continue."}, {"formule": "Propriétés : ordre total, densité, complétude", "imgPath": "assets/schemas/100-1-densite.svg", "titre": "Densité de ℝ", "caption": "Entre deux réels quelconques, même très proches comme 1 et 1,1, il en existe toujours un autre (ici 1,05) : c'est la densité de ℝ."}], "101": [{"formule": "z = x + iy", "imgPath": "assets/schemas/101-0-argand.svg", "titre": "Un nombre complexe dans le plan", "caption": "z = 3 + 2i est représenté par le point (3, 2) : 3 sur l'axe réel, 2 sur l'axe imaginaire."}, {"formule": "i² = -1", "imgPath": "assets/schemas/101-1-i-carre.svg", "titre": "i comme rotation de 90°", "caption": "Multiplier par i fait tourner un vecteur de 90°. Appliquer deux fois cette rotation (i²) ramène 1 sur -1 : c'est la définition géométrique de i² = -1."}, {"formule": "|z| = √(x² + y²)", "imgPath": "assets/schemas/101-2-module.svg", "titre": "Le module, par Pythagore", "caption": "Pour z = 3 + 2i, le module |z| = √(3²+2²) = √13 ≈ 3.606, calculé directement par le théorème de Pythagore sur le triangle rectangle formé par x, y et z."}, {"formule": "e^{iθ} = cos θ + i sin θ", "imgPath": "assets/schemas/101-3-euler.svg", "titre": "Formule d'Euler sur le cercle unité", "caption": "Pour θ = 50°, e^(iθ) = cos(50°) + i sin(50°) ≈ 0.643 + 0.766i, le point correspondant sur le cercle de rayon 1."}], "102": [{"formule": "P(x) = a_n x^n + ... + a_0", "imgPath": "assets/schemas/102-0-poly-general.svg", "titre": "Un polynôme concret", "caption": "P(x) = 2x² − 3x − 2 est un exemple concret de polynôme de degré 2, avec a₂=2, a₁=−3, a₀=−2."}, {"formule": "P'(x) = Σ k a_k x^{k-1}", "imgPath": "assets/schemas/102-1-derivee.svg", "titre": "La dérivée, terme à terme", "caption": "La dérivée de P(x) = 2x² − 3x − 2 est P'(x) = 4x − 3, calculée en dérivant chaque terme (règle x^k → k·x^(k-1))."}, {"formule": "Racines : P(x)=0", "imgPath": "assets/schemas/102-2-racines.svg", "titre": "Les racines, calculées", "caption": "Les racines de 2x² − 3x − 2 = 0 se calculent par le discriminant Δ = 9+16 = 25 : x = (3±5)/4, soit x = 2 et x = −0,5, les points où la courbe coupe l'axe."}], "103": [{"formule": "A ∈ M_{n×n}(ℝ)", "imgPath": "assets/schemas/103-0-matrice.svg", "titre": "Une matrice 3×3 concrète", "caption": "Exemple de matrice A ∈ M₃(ℝ), avec ses 3 lignes et 3 colonnes de coefficients réels."}, {"formule": "det(A)", "imgPath": "assets/schemas/103-1-det.svg", "titre": "det(A) = -5, calculé", "caption": "Pour A = [[3,2],[4,1]], det(A) = 3×1 − 2×4 = -5."}, {"formule": "A^{-1} si det(A) ≠ 0", "imgPath": "assets/schemas/103-2-inverse.svg", "titre": "L'inverse, calculé", "caption": "Puisque det(A) = -5 ≠ 0, A est inversible : A⁻¹ = (1/-5)×[[1,-2],[-4,3]], calculée ici numériquement."}], "104": [{"formule": "E espace vectoriel sur K", "imgPath": "assets/schemas/104-0-somme.svg", "titre": "La somme de deux vecteurs", "caption": "u=(3,1) et v=(1,3) ont pour somme u+v=(4,4), calculée coordonnée par coordonnée et construite par la règle du parallélogramme : E est stable par addition."}, {"formule": "Base : (e1,...,en)", "imgPath": "assets/schemas/104-1-base.svg", "titre": "Décomposition dans une base", "caption": "Tout vecteur w=(2 ; 1,4) se décompose de façon unique sur la base (e1,e2) : w = 2·e1 + 1,4·e2."}, {"formule": "Dimension : dim(E)", "imgPath": "assets/schemas/104-2-dimension.svg", "titre": "La dimension, en nombre de vecteurs de base", "caption": "La dimension compte le nombre de vecteurs dans une base : 1 pour une droite, 2 pour un plan, 3 pour l'espace usuel."}], "105": [{"formule": "det(A)", "imgPath": "assets/schemas/105-0-aire.svg", "titre": "Le déterminant comme aire = 7.0", "caption": "Pour u=(3 ; 0,5) et v=(1 ; 2,5), l'aire du parallélogramme (= |det|) vaut |3×2,5 − 0,5×1| = 7.0."}, {"formule": "det(AB) = det(A) det(B)", "imgPath": "assets/schemas/105-1-multiplicativite.svg", "titre": "Vérification numérique", "caption": "Avec deux matrices A et B concrètes, det(A)=6, det(B)=3, et on vérifie det(A)×det(B) = 18 = det(AB) = 18."}, {"formule": "A inversible ⇔ det(A) ≠ 0", "imgPath": "assets/schemas/105-2-degenere.svg", "titre": "Vecteurs colinéaires : aire nulle", "caption": "Ici v = (2/3)·u : les deux vecteurs sont colinéaires, le \"parallélogramme\" est aplati, son aire (le déterminant) est nulle — la matrice n'est pas inversible."}], "106": [{"formule": "f(u+v)=f(u)+f(v)", "imgPath": "assets/schemas/106-0-additivite.svg", "titre": "Une application linéaire, calculée", "caption": "Avec f(x,y)=(x+0,3y ; 0,6x+y), on calcule f(u)=(2.3, 2.2) et f(v)=(1.6, 2.6) ; leur somme égale f(u+v)=(3.9, 4.8)."}, {"formule": "f(λu)=λf(u)", "imgPath": "assets/schemas/106-1-homogeneite.svg", "titre": "Homogénéité, vérifiée", "caption": "f(2u) = (4.6, 4.4) est bien le double de f(u) = (2.3, 2.2) : la mise à l'échelle par λ=2 commute avec f."}, {"formule": "Mat(f) dépend de la base", "imgPath": "assets/schemas/106-2-matrice-base.svg", "titre": "La matrice de f dans la base canonique", "caption": "Dans la base canonique, f se représente par la matrice [[1 ; 0,3],[0,6 ; 1]] ; changer de base changerait ces coefficients sans changer f elle-même."}], "107": [{"formule": "A v = λ v", "imgPath": "assets/schemas/107-0-vecteur-propre.svg", "titre": "Un vecteur propre, vérifié", "caption": "Pour A=[[3,1],[0,2]] et v=(1,0), on calcule Av=(3,0)=3v : v est un vecteur propre associé à la valeur propre λ=3."}, {"formule": "det(A - λI) = 0", "imgPath": "assets/schemas/107-1-polycar.svg", "titre": "Le polynôme caractéristique", "caption": "Pour A=[[3,1],[0,2]], det(A−λI)=(3−λ)(2−λ) s'annule en λ=2 et λ=3 : ce sont exactement les deux valeurs propres de A."}], "108": [{"formule": "A = PDP^{-1}", "imgPath": "assets/schemas/108-0-pdp.svg", "titre": "P et D, calculées pour A=[[3,1],[0,2]]", "caption": "P (colonnes = vecteurs propres (1,0) et (1,1)) et D (valeurs propres 3 et 2 sur la diagonale) vérifient A = PDP⁻¹."}, {"formule": "D diag(λ1,...,λn)", "imgPath": "assets/schemas/108-1-diagonale.svg", "titre": "La matrice diagonale D", "caption": "D ne contient que les valeurs propres sur sa diagonale (ici 3 et 2), tous les autres coefficients sont nuls."}], "109": [{"formule": "Q(x)=xᵀAx", "imgPath": "assets/schemas/109-0-ellipse.svg", "titre": "Une forme quadratique définie positive", "caption": "Q(x,y)=x²/4+y² est une forme quadratique définie positive : sa ligne de niveau Q=1 dessine une ellipse."}, {"formule": "Signature de Sylvester", "imgPath": "assets/schemas/109-1-signature.svg", "titre": "La signature (2,0) de cette forme", "caption": "La forme Q(x,y)=x²/4+y² a 2 valeurs propres positives et 0 négative : sa signature de Sylvester est (2,0), ce qui garantit qu'elle est définie positive."}], "110": [{"formule": "G ensemble + opération", "imgPath": "assets/schemas/110-0-table-Z4.svg", "titre": "La table de ℤ/4ℤ, calculée", "caption": "Table de l'addition modulo 4 sur G={0,1,2,3}, entièrement calculée : chaque case (a,b) contient (a+b) mod 4."}, {"formule": "Identité, inverse", "imgPath": "assets/schemas/110-1-identite-inverse.svg", "titre": "0 est l'identité ; cases surlignées = paires inverses", "caption": "0 est l'élément neutre (colonne/ligne 0 inchangée) ; les cases surlignées montrent les paires (a,b) telles que a+b≡0 (mod 4), donc b est l'inverse de a : inverse(1)=3, inverse(2)=2, inverse(3)=1."}, {"formule": "Associativité", "imgPath": "assets/schemas/110-2-associativite.svg", "titre": "Vérification numérique de l'associativité", "caption": "Avec a=1,b=2,c=3 dans ℤ/4ℤ : (a+b)+c calcule à 2, a+(b+c) calcule aussi à 2 — les deux groupements donnent le même résultat."}], "111": [{"formule": "(A,+,×)", "imgPath": "assets/schemas/111-0-anneau-Z6.svg", "titre": "ℤ/6ℤ : addition (gauche) et multiplication (droite)", "caption": "ℤ/6ℤ est un anneau : il possède deux opérations calculées ici, l'addition modulo 6 (à gauche) et la multiplication modulo 6 (à droite)."}, {"formule": "Distributivité", "imgPath": "assets/schemas/111-1-distributivite.svg", "titre": "Vérification numérique", "caption": "Avec a=2, b=3, c=4 dans ℤ/6ℤ : a×(b+c) = 2 et a×b+a×c = 2 — la distributivité est vérifiée numériquement."}], "112": [{"formule": "K corps", "imgPath": "assets/schemas/112-0-inverses-Z5.svg", "titre": "Tous les éléments non nuls de ℤ/5ℤ sont inversibles", "caption": "Dans ℤ/5ℤ, chaque élément non nul (1,2,3,4) possède un inverse multiplicatif calculé ici : c'est ce qui en fait un corps."}, {"formule": "ℚ, ℝ, ℂ", "imgPath": "assets/schemas/112-1-inclusions.svg", "titre": "ℚ ⊂ ℝ ⊂ ℂ, avec un exemple dans chacun", "caption": "1/2 est rationnel (ℚ), √2 est réel non rationnel (ℝ), i (avec i²=−1) n'est pas réel mais complexe (ℂ) : chaque corps contient strictement le précédent."}], "113": [{"formule": "a ≡ b (mod n)", "imgPath": "assets/schemas/113-0-horloge.svg", "titre": "14 et 2 sont congrus modulo 12", "caption": "14 mod 12 = 2 et 2 mod 12 = 2 : les deux nombres tombent au même point du cadran (calculé), donc 14 ≡ 2 (mod 12)."}, {"formule": "ℤ/nℤ", "imgPath": "assets/schemas/113-1-Z7.svg", "titre": "Les 7 classes de ℤ/7ℤ, placées sur un cercle", "caption": "ℤ/7ℤ = {0,1,2,3,4,5,6} : les 7 restes possibles modulo 7, placés régulièrement sur un cercle généré ici pour n=7."}], "114": [{"formule": "RSA : c ≡ m^e (mod n)", "imgPath": "assets/schemas/114-0-rsa.svg", "titre": "Un exemple RSA réel, entièrement calculé", "caption": "Avec p=3, q=11 (n=33), e=3, d=7 : le message m=5 est chiffré en c=5³ mod 33=26, puis déchiffré en m=c⁷ mod 33=5=5 : tout est recalculé, pas illustratif."}, {"formule": "Diffie-Hellman", "imgPath": "assets/schemas/114-1-dh.svg", "titre": "Diffie-Hellman, calculé de bout en bout", "caption": "Avec g=5, p=23 : Alice (a=6) envoie A=8, Bob (b=15) envoie B=19 ; chacun calcule la même clé commune = 2, sans jamais échanger a ou b."}], "200": [{"formule": "Droite (plan) : ax + by + c = 0", "imgPath": "assets/schemas/200-0-droite.svg", "titre": "La droite 2x+3y−6=0, tracée", "caption": "Pour a=2, b=3, c=−6, l'équation 2x+3y−6=0 donne la droite tracée ici, passant par (3,0) et (0,2), les deux points calculés en annulant x puis y."}, {"formule": "Plan (espace) : ax + by + cz + d = 0", "imgPath": "assets/schemas/200-1-plan.svg", "titre": "Un plan de l'espace, représenté en perspective", "caption": "Un plan de l'espace (ax+by+cz+d=0) est représenté ici en perspective, avec son vecteur normal (a,b,c), perpendiculaire au plan par définition."}, {"formule": "Distance point–droite : |ax0 + by0 + c| / √(a² + b²)", "imgPath": "assets/schemas/200-2-distance.svg", "titre": "Distance calculée d'un point à une droite", "caption": "Pour M(4,4) et la droite 2x+3y−6=0, la distance vaut |2×4+3×4−6|/√13 = 3.883, calculée directement par la formule."}], "201": [{"formule": "→AB = (xB - xA, yB - yA)", "imgPath": "assets/schemas/201-0-vecteur-AB.svg", "titre": "Le vecteur AB, calculé", "caption": "Pour A(1,1) et B(4,3), AB = (4−1, 3−1) = (3,2), les coordonnées du vecteur calculées par simple soustraction."}, {"formule": "Norme : ||u|| = √(x² + y²)", "imgPath": "assets/schemas/201-1-norme.svg", "titre": "La norme, calculée par Pythagore", "caption": "Pour u=(3,2), ||u|| = √(3²+2²) = √13 ≈ 3.606."}, {"formule": "u·v = x1x2 + y1y2", "imgPath": "assets/schemas/201-2-produit.svg", "titre": "Le produit scalaire, calculé", "caption": "Pour u=(3,1) et v=(1,2), u·v = 3×1 + 1×2 = 5."}], "202": [{"formule": "Distance : d(A,B) = √((xB-xA)² + (yB-yA)²)", "imgPath": "assets/schemas/202-0-distance.svg", "titre": "La distance AB, calculée", "caption": "Pour A(1,1) et B(5,4), d(A,B) = √((5−1)²+(4−1)²) = √25 = 5.0."}, {"formule": "Milieu : M = ((xA+xB)/2, (yA+yB)/2)", "imgPath": "assets/schemas/202-1-milieu.svg", "titre": "Le milieu, calculé", "caption": "M = ((1+5)/2, (1+4)/2) = (3 ; 2,5), le point exactement équidistant de A et B."}], "203": [{"formule": "u·v = ||u|| ||v|| cos θ", "imgPath": "assets/schemas/203-0-angle.svg", "titre": "L'angle entre u et v, calculé", "caption": "Pour u=(3,1), v=(1,2) : cos θ = (u·v)/(‖u‖‖v‖) = 5/(3.16×2.24) ≈ 0.707, soit θ ≈ 45.0°."}, {"formule": "u·v = x1x2 + y1y2 (plan)", "imgPath": "assets/schemas/203-1-formule.svg", "titre": "Le produit scalaire, décomposé", "caption": "u·v se calcule terme à terme : 3×1 + 1×2 = 5, sans passer par les normes ni l'angle."}, {"formule": "Orthogonalité : u·v = 0", "imgPath": "assets/schemas/203-2-orthogonal.svg", "titre": "Deux vecteurs orthogonaux, vérifiés", "caption": "u=(2,1) et v=(−1,2) donnent u·v = 2×(−1)+1×2 = 0 = 0 : ils sont orthogonaux, ce qui se voit bien à l'angle droit qu'ils forment."}], "204": [{"formule": "(x - a)² + (y - b)² = r²", "imgPath": "assets/schemas/204-0-cercle.svg", "titre": "Un cercle concret, tracé", "caption": "(x−2)² + (y−1)² = 4 est le cercle de centre (2,1) et de rayon 2, tracé point par point à partir de l'équation paramétrique."}, {"formule": "Longueur : 2πr", "imgPath": "assets/schemas/204-1-circonference.svg", "titre": "Circonférence = 12.566", "caption": "Pour r=2, la circonférence 2πr = 2×π×2 ≈ 12.566."}, {"formule": "Aire : πr²", "imgPath": "assets/schemas/204-2-aire.svg", "titre": "Aire = 12.566", "caption": "Pour r=2, l'aire πr² = π×2² ≈ 12.566."}], "205": [{"formule": "cos θ = u·v / (||u|| ||v||)", "imgPath": "assets/schemas/205-0-angle-cos.svg", "titre": "L'angle θ, calculé par le produit scalaire", "caption": "cos θ = (u·v)/(‖u‖‖v‖) = 2.0/4.25 ≈ 0.471, d'où θ ≈ 61.9°."}, {"formule": "Somme des angles d’un triangle : 180°", "imgPath": "assets/schemas/205-1-somme-triangle.svg", "titre": "Les trois angles, calculés et sommés", "caption": "Pour ce triangle, les trois angles valent environ 63°, 44° et 73°, dont la somme calculée fait 180° ≈ 180°."}], "206": [{"formule": "Pythagore : a² + b² = c² (triangle rectangle)", "imgPath": "assets/schemas/206-0-pythagore.svg", "titre": "3-4-5, vérifié", "caption": "Pour un triangle rectangle de côtés a=3, b=4 : c=√(3²+4²)=√25=5.0. On vérifie 3²+4²=25=5²."}, {"formule": "Aire : (base × hauteur)/2", "imgPath": "assets/schemas/206-1-aire.svg", "titre": "Aire = 7.5, calculée", "caption": "Pour base=5 et hauteur=3, l'aire = (5×3)/2 = 7.5."}, {"formule": "Formule de Héron : A = √(p(p-a)(p-b)(p-c))", "imgPath": "assets/schemas/206-2-heron.svg", "titre": "Héron, appliquée à un triangle 5-6-7", "caption": "Pour a=5,b=6,c=7 : p=(5+6+7)/2=9.0, puis A=√(9.0×4.0×3.0×2.0)≈14.697, sans connaître la hauteur."}], "207": [{"formule": "sin² x + cos² x = 1", "imgPath": "assets/schemas/207-0-pythagore-trig.svg", "titre": "Vérifié sur le cercle unité", "caption": "Pour θ=35°, cos²θ+sin²θ = 0.819²+0.574² = 1.0 = 1, car le point est toujours sur le cercle de rayon 1."}, {"formule": "tan x = sin x / cos x", "imgPath": "assets/schemas/207-1-tangente.svg", "titre": "La tangente, lue sur le cercle", "caption": "Pour θ=35°, tan θ = sin θ/cos θ = 0.574/0.819 ≈ 0.7 : c'est la hauteur du point où le rayon prolongé coupe la droite x=1."}, {"formule": "cos(a+b) = cos a cos b - sin a sin b", "imgPath": "assets/schemas/207-2-addition.svg", "titre": "Formule d'addition, vérifiée numériquement", "caption": "Avec a=20°, b=40° : cos(60°)=0.5 et cos20°cos40°−sin20°sin40°=0.5 — les deux calculs coïncident."}], "208": [{"formule": "Aire rectangle : L × l", "imgPath": "assets/schemas/208-0-rectangle.svg", "titre": "Rectangle 4×2,5, aire=10.0", "caption": "Pour L=4 et l=2,5, l'aire = L×l = 10.0."}, {"formule": "Aire parallélogramme : base × hauteur", "imgPath": "assets/schemas/208-1-parallelogramme.svg", "titre": "Aire=8", "caption": "Pour base=4 et hauteur=2, l'aire = 4×2 = 8, quel que soit le décalage du sommet."}], "209": [{"formule": "z = x + iy", "imgPath": "assets/schemas/209-0-point.svg", "titre": "Un point du plan complexe", "caption": "z = 3+2i correspond au point (3,2) du plan."}, {"formule": "Rotation : z' = e^{iθ} z", "imgPath": "assets/schemas/209-1-rotation.svg", "titre": "z tourné de 90°, calculé", "caption": "z=3+2i multiplié par e^(i·90°)=i donne z'=i(3+2i)=−2+3i=(-2.0, 3.0), une rotation de 90° autour de l'origine."}, {"formule": "Translation : z' = z + a", "imgPath": "assets/schemas/209-2-translation.svg", "titre": "z translaté de a=-1+i", "caption": "z=3+2i translaté par a=−1+i donne z'=z+a=(3−1)+(2+1)i=2+3i."}], "210": [{"formule": "Somme des angles intérieurs : (n-2) × 180°", "imgPath": "assets/schemas/210-0-hexagone.svg", "titre": "Hexagone, somme calculée", "caption": "Pour un hexagone (n=6), la somme des angles intérieurs vaut (6−2)×180° = 720°."}, {"formule": "Aire polygone régulier : (n × côté²) / (4 tan(π/n))", "imgPath": "assets/schemas/210-1-aire-hexagone.svg", "titre": "Aire=10.392", "caption": "Pour un hexagone régulier de côté 2 : aire = 6×2²/(4×tan(30°)) ≈ 10.392."}], "211": [{"formule": "Translation : z' = z + a", "imgPath": "assets/schemas/211-0-translation.svg", "titre": "Translation, calculée", "caption": "z=1+i translaté par a=2+0,5i donne z'=3+1.5i."}, {"formule": "Rotation : z' = e^{iθ} z", "imgPath": "assets/schemas/211-1-rotation.svg", "titre": "Rotation de 60°, calculée", "caption": "z=1+i tourné de 60° donne z'=e^(i·60°)z ≈ -0.37+1.37i."}, {"formule": "Homothétie : z' = k z", "imgPath": "assets/schemas/211-2-homothetie.svg", "titre": "Homothétie de rapport 2, calculée", "caption": "z=1+i multiplié par k=2 donne z'=2+2i, deux fois plus loin de l'origine, dans la même direction."}], "212": [{"formule": "Centre : intersection des médiatrices", "imgPath": "assets/schemas/212-0-centre.svg", "titre": "Le centre, calculé par les médiatrices", "caption": "Pour ce triangle, le centre du cercle circonscrit est calculé à l'intersection des trois médiatrices : O≈(2.0 ; 1.0)."}, {"formule": "Rayon dans un triangle : R = a / (2 sin A)", "imgPath": "assets/schemas/212-1-rayon.svg", "titre": "R=2.236", "caption": "Le rayon R=a/(2 sin A) calculé retombe exactement sur la distance centre-sommet mesurée ci-dessus (R≈2.236)."}], "213": [{"formule": "Symétrie axiale : réflexion par rapport à une droite", "imgPath": "assets/schemas/213-0-axiale.svg", "titre": "Réflexion par rapport à y=x, calculée", "caption": "P(3,5 ; 1) se réfléchit par rapport à la droite y=x en échangeant ses coordonnées : P'(1 ; 3,5)."}, {"formule": "Symétrie centrale : réflexion par rapport à un point", "imgPath": "assets/schemas/213-1-centrale.svg", "titre": "Réflexion par rapport à O(2,2), calculée", "caption": "P(3,5 ; 1) se réfléchit par rapport à O(2,2) en P' = 2O − P = (0.5 ; 3) : O est le milieu de [PP']."}], "214": [{"formule": "z' = k z (centre à l’origine)", "imgPath": "assets/schemas/214-0-homothetie.svg", "titre": "Homothétie de rapport 2, appliquée à un triangle", "caption": "Chaque sommet du petit triangle est multiplié par k=2 : le grand triangle est l'image, deux fois plus loin de l'origine."}, {"formule": "Aire multipliée par k²", "imgPath": "assets/schemas/214-1-aire-k2.svg", "titre": "Aire × 4", "caption": "Une homothétie de rapport k=2 multiplie toutes les longueurs par 2, donc les aires par k²=4."}], "215": [{"formule": "Transformation linéaire du plan préservant le parallélisme", "imgPath": "assets/schemas/215-0-affinite.svg", "titre": "Cisaillement : le carré devient un parallélogramme", "caption": "L'affinité (x,y)→(x+0,5y ; y) transforme le carré gris en parallélogramme coloré : les côtés restent parallèles deux à deux."}, {"formule": "Représentation par matrices 2×2 + translation", "imgPath": "assets/schemas/215-1-matrice.svg", "titre": "La matrice de cette affinité", "caption": "L'affinité ci-dessus se code par la matrice [[1 ; 0,5],[0 ; 1]] (plus une translation nulle ici)."}], "216": [{"formule": "Droite paramétrique : A + t u", "imgPath": "assets/schemas/216-0-droite-param.svg", "titre": "Points calculés pour t=-0,5..1,5", "caption": "Avec A(1,1) et u=(2,1), la droite A+tu passe par des points calculés pour chaque t (par exemple t=1 donne le point (3,2))."}, {"formule": "Plan paramétrique : A + s u + t v", "imgPath": "assets/schemas/216-1-plan-param.svg", "titre": "Un plan engendré par deux vecteurs, en perspective", "caption": "Le plan A+su+tv est balayé par deux directions indépendantes u et v depuis le point A, représenté ici en perspective."}], "217": [{"formule": "Plan : ax + by + cz + d = 0", "imgPath": "assets/schemas/217-0-plan3d.svg", "titre": "Un plan de l'espace, en perspective", "caption": "Le plan ax+by+cz+d=0 est représenté en perspective avec son vecteur normal n=(a,b,c), perpendiculaire à tout vecteur du plan."}, {"formule": "Droite : A + t u (u ≠ 0)", "imgPath": "assets/schemas/217-1-droite3d.svg", "titre": "Une droite de l'espace, en perspective", "caption": "La droite A+tu part du point A et suit la direction u ; en 3D comme en 2D, chaque valeur de t donne un point de la droite."}], "218": [{"formule": "(x-a)² + (y-b)² + (z-c)² = r²", "imgPath": "assets/schemas/218-0-sphere.svg", "titre": "Une sphère, en perspective (équateur en pointillés)", "caption": "La sphère de centre (a,b,c) et de rayon r est représentée ici en perspective, l'ellipse en pointillés figurant son \"équateur\" vu de biais."}, {"formule": "Volume : (4/3) π r³", "imgPath": "assets/schemas/218-1-volume.svg", "titre": "Volume=113.1", "caption": "Pour r=3, le volume (4/3)πr³ = (4/3)×π×27 ≈ 113.1."}, {"formule": "Aire : 4π r²", "imgPath": "assets/schemas/218-2-aire.svg", "titre": "Aire=113.1", "caption": "Pour r=3, l'aire 4πr² = 4×π×9 ≈ 113.1."}], "219": [{"formule": "Volume : V = π r² h", "imgPath": "assets/schemas/219-0-volume.svg", "titre": "r=2, h=4, V=50.27", "caption": "Pour r=2 et h=4, le volume V=πr²h = π×4×4 ≈ 50.27."}, {"formule": "Aire latérale : 2π r h", "imgPath": "assets/schemas/219-1-aire-laterale.svg", "titre": "Aire=50.27", "caption": "Pour r=2 et h=4, l'aire latérale 2πrh = 2×π×2×4 ≈ 50.27 — c'est le rectangle obtenu en \"déroulant\" la surface du cylindre."}], "220": [{"formule": "Volume : V = (1/3) π r² h", "imgPath": "assets/schemas/220-0-volume.svg", "titre": "r=3,h=4,V=37.7", "caption": "Pour r=3 et h=4, le volume V=(1/3)πr²h = (1/3)×π×9×4 ≈ 37.7."}, {"formule": "Aire latérale : π r l (l : génératrice)", "imgPath": "assets/schemas/220-1-aire-laterale.svg", "titre": "l=5.0, Aire=47.12", "caption": "La génératrice l=√(r²+h²)=√(9+16)=5.0 ; l'aire latérale πrl = π×3×5 ≈ 47.12."}], "300": [{"formule": "Ω : ensemble des issues", "imgPath": "assets/schemas/300-0-univers.svg", "titre": "L'univers Ω d'un lancer de dé", "caption": "Pour le lancer d'un dé à 6 faces, Ω = {1,2,3,4,5,6} regroupe les 6 issues possibles."}, {"formule": "Événement : A ⊂ Ω", "imgPath": "assets/schemas/300-1-evenement.svg", "titre": "Un événement A, sous-ensemble de Ω", "caption": "A = \"obtenir un nombre pair\" = {2,4,6} est un sous-ensemble de Ω = {1,...,6} : c'est un événement."}], "301": [{"formule": "P(A) = |A| / |Ω| (cas équiprobable)", "imgPath": "assets/schemas/301-0-calcul.svg", "titre": "P(A) calculée pour le dé pair", "caption": "Pour A={2,4,6} et Ω={1,...,6} équiprobable, P(A) = 3/6 = 0,5."}, {"formule": "0 ≤ P(A) ≤ 1", "imgPath": "assets/schemas/301-1-intervalle.svg", "titre": "P(A) toujours entre 0 et 1", "caption": "Toute probabilité, comme P(A)=0,5 ici, est nécessairement comprise entre 0 (impossible) et 1 (certain)."}, {"formule": "P(Ω) = 1", "imgPath": "assets/schemas/301-2-total.svg", "titre": "P(Ω)=1, toujours", "caption": "La probabilité de l'univers tout entier vaut toujours 1 : l'expérience a nécessairement une issue dans Ω."}], "302": [{"formule": "X : Ω → ℝ", "imgPath": "assets/schemas/302-0-mapping.svg", "titre": "X = nombre de \"Pile\" sur 2 lancers", "caption": "X associe à chaque issue de Ω={FF,FP,PF,PP} le nombre de \"Pile\" obtenus : X(FF)=0, X(FP)=X(PF)=1, X(PP)=2."}, {"formule": "Loi de X : P(X = x_i)", "imgPath": "assets/schemas/302-1-loi.svg", "titre": "La loi de X, calculée", "caption": "P(X=0)=1/4, P(X=1)=2/4, P(X=2)=1/4, calculées en comptant les issues de Ω qui donnent chaque valeur."}], "303": [{"formule": "P(A|B) = P(A ∩ B) / P(B)", "imgPath": "assets/schemas/303-0-conditionnelle.svg", "titre": "P(A|B)=0.5", "caption": "Dans un jeu de 52 cartes : P(A∩B)=0.115 (6 figures rouges), P(B)=0.231 (12 figures) ⟹ P(A|B) = 0.115/0.231 = 0.5."}, {"formule": "P(A ∩ B) = P(A|B) P(B)", "imgPath": "assets/schemas/303-1-produit.svg", "titre": "Vérification numérique", "caption": "P(A|B)×P(B) = 0.5×0.231 ≈ 0.115, ce qui retombe bien sur P(A∩B)=0.115."}], "304": [{"formule": "E(X) = Σ x_i P(X = x_i) (discret)", "imgPath": "assets/schemas/304-0-esperance-discrete.svg", "titre": "E(X)=1.0", "caption": "E(X) = 0×0,25 + 1×0,5 + 2×0,25 = 1.0 pour la loi de X (nombre de Piles sur 2 lancers)."}, {"formule": "E(X) = ∫ x f_X(x) dx (continu)", "imgPath": "assets/schemas/304-1-esperance-continue.svg", "titre": "E(X) au centre de la densité", "caption": "Pour une loi continue symétrique comme cette gaussienne centrée réduite, E(X)=∫xf(x)dx=0, exactement au sommet de la courbe."}], "305": [{"formule": "Var(X) = E(X²) - [E(X)]²", "imgPath": "assets/schemas/305-0-variance.svg", "titre": "Var(X)=0.5", "caption": "Var(X) = Σ(x−E(X))²P(X=x) = 0.5, calculée terme à terme pour la loi de X ci-dessus."}, {"formule": "σ(X) = √Var(X)", "imgPath": "assets/schemas/305-1-ecart-type.svg", "titre": "σ(X)=0.707", "caption": "σ(X) = √0.5 ≈ 0.707, l'écart-type mesurant la dispersion typique de X autour de sa moyenne."}], "306": [{"formule": "P(A|B) = P(B|A) P(A) / P(B)", "imgPath": "assets/schemas/306-0-bayes-arbre.svg", "titre": "Arbre calculé (test médical)", "caption": "Avec 1% de malades, un test positif à 95% chez les malades et 5% de faux positifs : P(malade|test+) = 0,95×0,01/P(test+) ≈ 0.161 (moins de 16% !)."}, {"formule": "P(B) = Σ P(B|A_i) P(A_i)", "imgPath": "assets/schemas/306-1-totale.svg", "titre": "Probabilité totale, calculée", "caption": "P(test+) = P(+|Malade)P(Malade) + P(+|Sain)P(Sain) = 0.0095 + 0.0495 = 0.059."}], "307": [{"formule": "Loi de Bernoulli : P(X=1)=p, P(X=0)=1-p", "imgPath": "assets/schemas/307-0-bernoulli.svg", "titre": "Bernoulli p=0,3", "caption": "Pour p=0,3 : P(X=0)=0,7 (échec), P(X=1)=0,3 (succès) — un seul essai."}, {"formule": "Loi binomiale : P(X=k)=C(n,k)p^k(1-p)^{n-k}", "imgPath": "assets/schemas/307-1-binomiale.svg", "titre": "Binomiale n=10,p=0,3, calculée", "caption": "Distribution complète de P(X=k) pour n=10 essais et p=0,3, calculée terme à terme avec la formule du binôme."}, {"formule": "Loi géométrique : P(X=k)=(1-p)^{k-1}p", "imgPath": "assets/schemas/307-2-geometrique.svg", "titre": "Géométrique p=0,3, calculée", "caption": "P(X=k) = (0,7)^(k-1)×0,3 pour k=1..10 : la probabilité d'attendre k essais avant le premier succès, décroissante."}], "308": [{"formule": "A et B indépendants ⇔ P(A ∩ B) = P(A)P(B)", "imgPath": "assets/schemas/308-0-independance.svg", "titre": "Table de contingence, vérifiée", "caption": "Pour deux dés lancés séparément, P(A∩B)=0,25=P(A)×P(B)=0,5×0,5 : les événements sont indépendants, la table se \"factorise\"."}, {"formule": "X et Y indépendantes ⇔ P(X=x, Y=y) = P(X=x)P(Y=y)", "imgPath": "assets/schemas/308-1-independance-va.svg", "titre": "Loi jointe factorisée", "caption": "Chaque case de la loi jointe vaut ici P(X=x)×P(Y=y)=0,5×0,5=0,25 : X et Y sont indépendantes."}], "309": [{"formule": "X = (X1,...,Xn)", "imgPath": "assets/schemas/309-0-vecteur.svg", "titre": "Un vecteur aléatoire (X,Y) et ses valeurs possibles", "caption": "Le couple (X,Y) prend des valeurs comme (1,1), (1,2)... chacune une réalisation possible du vecteur aléatoire."}, {"formule": "Loi jointe : P(X1=x1,...,Xn=xn)", "imgPath": "assets/schemas/309-1-somme-des.svg", "titre": "Table des sommes de deux dés", "caption": "Table complète des 36 sommes possibles de deux dés (X1+X2) : chaque case a la même probabilité 1/36, ce qui donne la loi jointe."}], "310": [{"formule": "Cov(X,Y) = E(XY) - E(X)E(Y)", "imgPath": "assets/schemas/310-0-covariance.svg", "titre": "Cov(X,Y)=1.2", "caption": "Pour ces 5 points (X,Y), Cov(X,Y) = 1.2 > 0 : quand X augmente, Y a tendance à augmenter aussi."}, {"formule": "Corr(X,Y) = Cov(X,Y) / (σ(X)σ(Y))", "imgPath": "assets/schemas/310-1-correlation.svg", "titre": "Corr=0.775", "caption": "En normalisant la covariance par les écarts-types, Corr(X,Y) = 1.2/(1.414×1.095) ≈ 0.775, une valeur toujours entre -1 et 1."}], "311": [{"formule": "N(m,σ²)", "imgPath": "assets/schemas/311-0-normale.svg", "titre": "N(2 ; 1,5²), tracée", "caption": "La loi N(m=2, σ²=1,5²) est centrée en 2 avec un écart-type de 1,5, contrôlant la largeur de la cloche."}, {"formule": "Densité : (1/(σ√(2π))) exp(-(x-m)²/(2σ²))", "imgPath": "assets/schemas/311-1-densite.svg", "titre": "La densité, calculée en son sommet", "caption": "Au sommet x=m=2, la densité vaut 1/(1,5×√(2π)) ≈ 0.266, calculée directement par la formule."}], "400": [{"formule": "Longueur : m", "imgPath": "assets/schemas/400-0-longueur.svg", "titre": "Le mètre", "caption": "La longueur se mesure en mètres (m), unité de base du Système International."}, {"formule": "Temps : s", "imgPath": "assets/schemas/400-1-temps.svg", "titre": "La seconde", "caption": "Le temps se mesure en secondes (s), définie aujourd'hui à partir des oscillations de l'atome de césium."}, {"formule": "Masse : kg", "imgPath": "assets/schemas/400-2-masse.svg", "titre": "Le kilogramme", "caption": "La masse se mesure en kilogrammes (kg)."}, {"formule": "Intensité : A", "imgPath": "assets/schemas/400-3-intensite.svg", "titre": "L'ampère", "caption": "L'intensité du courant électrique se mesure en ampères (A)."}], "401": [{"formule": "v = dx/dt", "imgPath": "assets/schemas/401-0-vitesse.svg", "titre": "Vitesse constante, dérivée de x(t)", "caption": "Pour x(t)=4t (MRU), v=dx/dt=4 m/s est constante : la pente de x(t) ne change pas."}, {"formule": "a = dv/dt", "imgPath": "assets/schemas/401-1-acceleration.svg", "titre": "Accélération constante, dérivée de v(t)", "caption": "Pour v(t)=2t+1 (MRUA), a=dv/dt=2 m/s² est constante : c'est la pente de v(t)."}, {"formule": "MRU : x(t) = x0 + vt", "imgPath": "assets/schemas/401-2-mru.svg", "titre": "Mouvement rectiligne uniforme, tracé", "caption": "Pour x0=1 m et v=4 m/s, x(t)=1+4t est une droite : la position croît proportionnellement au temps."}, {"formule": "MRUA : x(t) = x0 + v0 t + (1/2) a t²", "imgPath": "assets/schemas/401-3-mrua.svg", "titre": "Mouvement uniformément accéléré, tracé", "caption": "Pour x0=1, v0=2 m/s, a=1,5 m/s², x(t)=1+2t+0,75t² est une parabole : la position accélère."}], "402": [{"formule": "F = m a", "imgPath": "assets/schemas/402-0-fma.svg", "titre": "F=7.5 N, calculée", "caption": "Pour une masse m=3 kg et une accélération a=2.5 m/s², F=ma=7.5 N."}, {"formule": "Principe fondamental de la dynamique", "imgPath": "assets/schemas/402-1-pfd.svg", "titre": "Le principe, énoncé", "caption": "Le principe fondamental de la dynamique relie la somme des forces appliquées à un objet à son accélération, via sa masse."}, {"formule": "ΣF = m a", "imgPath": "assets/schemas/402-2-somme-forces.svg", "titre": "La résultante des forces, calculée", "caption": "F1=(3,1) et F2=(−1,2) donnent ΣF=(2,3) : c'est cette résultante, divisée par m, qui donne l'accélération."}], "403": [{"formule": "Poids : P = m g", "imgPath": "assets/schemas/403-0-poids.svg", "titre": "P=49.0 N, calculé", "caption": "Pour m=5 kg, g=9,8 m/s², P=mg=49.0 N, dirigé vers le bas."}, {"formule": "Frottement : f = μ N", "imgPath": "assets/schemas/403-1-frottement.svg", "titre": "f=15.0 N", "caption": "Pour μ=0,3 et N=50 N, la force de frottement f=μN=15.0 N."}, {"formule": "Force élastique : F = -k x", "imgPath": "assets/schemas/403-2-elastique.svg", "titre": "La loi de Hooke, tracée", "caption": "Pour un ressort de raideur k=8 N/m, F=−kx est une droite : la force rappelle vers x=0, proportionnellement à l'allongement."}], "404": [{"formule": "Travail : W = ∫ F·dl", "imgPath": "assets/schemas/404-0-travail.svg", "titre": "W = aire sous F(d) = 10×5 = 50 J", "caption": "Pour une force constante F=10 N sur d=5 m, W=∫F·dl=F×d=50 J : c'est l'aire sous la courbe F(d)."}, {"formule": "Puissance : P = dW/dt", "imgPath": "assets/schemas/404-1-puissance.svg", "titre": "P = pente de W(t)", "caption": "Si le travail croît comme W(t)=50t, la puissance P=dW/dt=50 W est constante : c'est la pente de cette droite."}, {"formule": "P = F·v", "imgPath": "assets/schemas/404-2-puissance-vitesse.svg", "titre": "P=30 W", "caption": "Pour F=10 N et v=3 m/s, P=F×v=30 W."}], "405": [{"formule": "v = ω r", "imgPath": "assets/schemas/405-0-vitesse-circulaire.svg", "titre": "v=3.0 m/s, tangente au cercle", "caption": "Pour ω=2 rad/s et r=1,5 m, v=ωr=3.0 m/s, dirigée tangentiellement au cercle."}, {"formule": "a_n = v² / r", "imgPath": "assets/schemas/405-1-acceleration-normale.svg", "titre": "a_n=6.0 m/s², dirigée vers le centre", "caption": "a_n = v²/r = 3.0²/1,5 ≈ 6.0 m/s², toujours dirigée vers le centre du cercle (accélération centripète)."}, {"formule": "a_t = dv/dt", "imgPath": "assets/schemas/405-2-acceleration-tangentielle.svg", "titre": "a_t = pente de v(t) = 0,5 m/s²", "caption": "Si la vitesse angulaire varie comme v(t)=2+0,5t, l'accélération tangentielle a_t=dv/dt=0,5 m/s² est la pente de cette droite."}], "406": [{"formule": "Oscillateur harmonique : x'' + ω² x = 0", "imgPath": "assets/schemas/406-0-equation.svg", "titre": "La solution oscillante de l'équation", "caption": "x''+ω²x=0 (ω=2) admet pour solutions des oscillations comme celle-ci, qui vérifient bien x''=−ω²x en tout point."}, {"formule": "Solution : x(t) = A cos(ωt + φ)", "imgPath": "assets/schemas/406-1-solution.svg", "titre": "Amplitude 1,4, déphasage 30°, tracée", "caption": "x(t)=A cos(ωt+φ) avec A=1,4, ω=2, φ=30° : l'amplitude fixe la hauteur des oscillations, la phase φ décale la courbe dans le temps."}], "407": [{"formule": "v = λ f", "imgPath": "assets/schemas/407-0-onde.svg", "titre": "v=λf=6 m/s", "caption": "Pour λ=2 m et f=3 Hz, v=λf=6 m/s : la longueur d'onde (distance entre deux crêtes) se lit directement sur la courbe."}, {"formule": "Équation d'onde : ∂²u/∂t² = c² ∂²u/∂x²", "imgPath": "assets/schemas/407-1-propagation.svg", "titre": "L'onde qui se propage, à deux instants", "caption": "La solution de l'équation d'onde se translate au cours du temps sans se déformer : la courbe à t=0,15s est identique à celle de t=0, juste décalée."}], "408": [{"formule": "Loi de Snell-Descartes : n1 sin i = n2 sin r", "imgPath": "assets/schemas/408-0-refraction.svg", "titre": "r calculé = 25.4°", "caption": "Pour i=40°, n1=1,0 (air), n2=1,5 (verre) : sin r = (n1/n2)sin i, donc r = arcsin(0,667×sin40°) ≈ 25.4°."}, {"formule": "Lentilles : 1/f = 1/p + 1/p'", "imgPath": "assets/schemas/408-1-lentille.svg", "titre": "p'=13.33 cm, calculée", "caption": "Pour une lentille de focale f=5 cm et un objet à p=8 cm, 1/p'=1/f−1/p donne p'≈13.33 cm."}], "409": [{"formule": "Diffraction : θ ≈ λ/a", "imgPath": "assets/schemas/409-0-diffraction.svg", "titre": "θ≈0.286°", "caption": "Pour λ=500 nm et une fente a=0,1 mm, l'angle de diffraction θ≈λ/a ≈ 0.005 rad ≈ 0.286°."}, {"formule": "Interférences : I = I1 + I2 + 2√(I1I2) cos φ", "imgPath": "assets/schemas/409-1-interferences.svg", "titre": "Figure d'interférence, calculée", "caption": "Pour I1=I2=1, I(φ)=2+2cos φ oscille entre 0 (interférence destructive) et 4 (constructive) selon le déphasage φ."}], "410": [{"formule": "Énergie cinétique : Ec = (1/2) m v²", "imgPath": "assets/schemas/410-0-cinetique.svg", "titre": "Ec=9.0 J", "caption": "Pour m=2 kg, v=3 m/s, Ec=(1/2)×2×3²=9.0 J."}, {"formule": "Énergie potentielle : Ep = m g h", "imgPath": "assets/schemas/410-1-potentielle.svg", "titre": "Ep=78.4 J", "caption": "Pour m=2 kg, h=4 m, Ep=mgh=78.4 J."}, {"formule": "Conservation : E_tot = constante", "imgPath": "assets/schemas/410-2-conservation.svg", "titre": "E_tot=87.4 J", "caption": "E_tot = Ec+Ep = 9.0+78.4 = 87.4 J reste constante si aucune force de frottement ne dissipe d'énergie."}], "411": [{"formule": "1er principe : ΔU = Q + W", "imgPath": "assets/schemas/411-0-premier-principe.svg", "titre": "ΔU=300 J", "caption": "Pour Q=500 J reçus et W=-200 J (le système fournit du travail), ΔU=Q+W=300 J."}, {"formule": "PV = nRT", "imgPath": "assets/schemas/411-1-isotherme.svg", "titre": "Isotherme à T=300K, tracée", "caption": "À température constante T=300K, PV=nRT impose P=nRT/V : une hyperbole, l'isotherme du gaz parfait."}, {"formule": "S ≥ 0 (entropie)", "imgPath": "assets/schemas/411-2-entropie.svg", "titre": "Le second principe, résumé", "caption": "Pour un système isolé, l'entropie ne peut qu'augmenter ou rester constante (transformation réversible) : ΔS ≥ 0."}], "412": [{"formule": "PV = nRT", "imgPath": "assets/schemas/412-0-loi-gaz.svg", "titre": "La loi des gaz parfaits, tracée", "caption": "Pour n=1 mol, R=8,314 J/(mol·K), T=300K, la relation PV=nRT donne cette hyperbole P(V)=nRT/V."}, {"formule": "P = ρ R T", "imgPath": "assets/schemas/412-1-masse-volumique.svg", "titre": "Masse volumique en fonction de T, tracée", "caption": "En réécrivant PV=nRT avec la masse volumique ρ, P=ρRT/M : ρ diminue quand T augmente à pression constante (air qui se dilate en chauffant)."}], "413": [{"formule": "P = F / S", "imgPath": "assets/schemas/413-0-pression.svg", "titre": "P=400.0 Pa", "caption": "Pour F=20 N appliquée sur S=0.05 m², P=F/S=400.0 Pa."}, {"formule": "Pression hydrostatique : P = ρ g h", "imgPath": "assets/schemas/413-1-hydrostatique.svg", "titre": "Pression croissante avec la profondeur, tracée", "caption": "Pour l'eau (ρ=1000 kg/m³), P(h)=ρgh croît linéairement avec la profondeur h."}], "414": [{"formule": "Équation de Bernoulli : P + (1/2)ρv² + ρgh = constante", "imgPath": "assets/schemas/414-0-bernoulli.svg", "titre": "P2=189500.0 Pa, calculée", "caption": "À hauteur constante, P+½ρv²=constante : quand v augmente de 2 à 5 m/s, la pression chute de 200000 à 189500.0 Pa (effet Venturi)."}, {"formule": "Débit : Q = A v", "imgPath": "assets/schemas/414-1-debit.svg", "titre": "Q=0.06 m³/s", "caption": "Pour une section A=0,02 m² et une vitesse v=3 m/s, le débit Q=A×v=0.06 m³/s."}], "415": [{"formule": "U = R I", "imgPath": "assets/schemas/415-0-ohm.svg", "titre": "U=RI, tracée pour R=15Ω", "caption": "Pour une résistance R=15 Ω, U=RI est une droite passant par l'origine, de pente R."}, {"formule": "P = U I", "imgPath": "assets/schemas/415-1-puissance.svg", "titre": "P=24 W, calculée", "caption": "Pour U=12 V et I=2 A, la puissance électrique P=U×I=24 W."}, {"formule": "Q = I t", "imgPath": "assets/schemas/415-2-charge.svg", "titre": "Q=60 C, calculée", "caption": "Pour I=2 A pendant t=30 s, la charge Q=I×t=60 coulombs."}], "416": [{"formule": "E = F/q", "imgPath": "assets/schemas/416-0-champ-force.svg", "titre": "E=1500.0 N/C", "caption": "Pour une force F=0.003 N sur une charge q=2e-06 C, E=F/q=1500.0 N/C."}, {"formule": "E = k q / r²", "imgPath": "assets/schemas/416-1-champ-distance.svg", "titre": "Décroissance en 1/r², tracée", "caption": "Pour Q=1 µC, le champ E(r)=kQ/r² décroît très rapidement avec la distance : c'est une loi en carré inverse."}], "417": [{"formule": "B = μ0 I / (2π r)", "imgPath": "assets/schemas/417-0-champ-fil.svg", "titre": "Décroissance en 1/r, tracée", "caption": "Pour un fil parcouru par I=5 A, B(r)=μ0I/(2πr) décroît en 1/r avec la distance au fil — plus lentement que le champ électrique d'une charge."}, {"formule": "F = q v × B", "imgPath": "assets/schemas/417-1-force-laplace.svg", "titre": "F=(0.0, -9.0, 0) N, calculée par produit vectoriel", "caption": "Pour q=2, v=(3,0,0), B=(0,0,1,5) : v×B=(0.0, -4.5, 0), donc F=q(v×B)=(0.0, -9.0, 0)."}], "418": [{"formule": "Maxwell : ∇·E = ρ/ε0", "imgPath": "assets/schemas/418-0-maxwell1.svg", "titre": "Première équation, résumée", "caption": "∇·E=ρ/ε0 relie la divergence du champ électrique à la densité de charge ρ : les charges sont les sources du champ E."}, {"formule": "∇×B = μ0 J + μ0 ε0 ∂E/∂t", "imgPath": "assets/schemas/418-1-maxwell2.svg", "titre": "Dernière équation, résumée", "caption": "∇×B=μ0J+μ0ε0∂E/∂t montre que le champ magnétique est créé à la fois par les courants J et par un champ électrique qui varie dans le temps."}], "500": [{"formule": "Entrée → Traitement → Sortie", "imgPath": "assets/schemas/500-0-flux.svg", "titre": "Le schéma général d'un algorithme", "caption": "Tout algorithme s'enchaîne en trois grandes étapes : lire une entrée, la traiter, produire une sortie."}, {"formule": "Complexité : O(f(n))", "imgPath": "assets/schemas/500-1-complexite.svg", "titre": "Trois complexités comparées, calculées", "caption": "O(n), O(n log n) et O(n²) sont ici calculées et tracées pour n=1 à 20 : on voit concrètement pourquoi O(n²) devient vite très coûteux."}], "501": [{"formule": "Tableau : accès O(1)", "imgPath": "assets/schemas/501-0-tableau.svg", "titre": "Accès direct par indice", "caption": "Dans un tableau, accéder à l'élément d'indice 3 (valeur 3) se fait directement, en temps constant O(1), quelle que soit la taille du tableau."}, {"formule": "Liste chaînée : insertion O(1)", "imgPath": "assets/schemas/501-1-liste-chainee.svg", "titre": "Chaque nœud pointe vers le suivant", "caption": "Insérer un élément dans une liste chaînée ne demande que de modifier un pointeur (O(1)), sans décaler les autres éléments comme dans un tableau."}, {"formule": "Pile / File : FIFO / LIFO", "imgPath": "assets/schemas/501-2-pile-file.svg", "titre": "LIFO vs FIFO, comparés", "caption": "Une pile retire toujours le dernier élément entré (LIFO) ; une file retire toujours le premier élément entré (FIFO)."}], "502": [{"formule": "Arbre binaire : chaque nœud a ≤ 2 enfants", "imgPath": "assets/schemas/502-0-arbre-binaire.svg", "titre": "Un arbre binaire concret, à 6 nœuds", "caption": "Chaque nœud (8, 3, 10...) a au plus deux enfants : c'est la définition même d'un arbre binaire."}, {"formule": "Hauteur h, nombre de nœuds ≤ 2^{h+1}-1", "imgPath": "assets/schemas/502-1-hauteur.svg", "titre": "h=2 → max 7 nœuds", "caption": "L'arbre ci-dessus a une hauteur h=2 ; le nombre maximal de nœuds pour cette hauteur est 2³−1=7 — atteint ici puisqu'il est parfaitement rempli."}], "503": [{"formule": "G = (V, E)", "imgPath": "assets/schemas/503-0-graphe.svg", "titre": "G=(V,E) avec |V|=5, |E|=5", "caption": "Ce graphe a pour sommets V={A,B,C,D,E} et pour arêtes E={AB,AC,BD,CD,DE} : G=(V,E) avec |V|=5 et |E|=5."}, {"formule": "Parcours BFS : O(V+E)", "imgPath": "assets/schemas/503-1-bfs.svg", "titre": "BFS, appliqué au graphe ci-dessus", "caption": "Le parcours en largeur (BFS) depuis A visite d'abord ses voisins directs B et C, puis D, puis E : chaque sommet et arête est visité une fois, d'où O(V+E)."}, {"formule": "Parcours DFS : O(V+E)", "imgPath": "assets/schemas/503-2-dfs.svg", "titre": "DFS, appliqué au même graphe", "caption": "Le parcours en profondeur (DFS) depuis A va aussi loin que possible (A→B→D) avant de revenir en arrière, toujours en O(V+E)."}], "504": [{"formule": "Recherche : O(h)", "imgPath": "assets/schemas/504-0-recherche.svg", "titre": "Chercher 6 : 8→3→6 (2 comparaisons, h=2)", "caption": "Chercher 6 dans cet arbre (h=2) : 6<8 (aller à gauche), 6>3 (aller à droite), trouvé — seulement h=2 comparaisons."}, {"formule": "Insertion : O(h)", "imgPath": "assets/schemas/504-1-insertion.svg", "titre": "Insertion de 5 : nouvelle feuille en h=3", "caption": "Insérer 5 : 5<8, 5>3, 5<6 → nouvelle feuille sous 6, en h=3 comparaisons, sans réorganiser le reste de l'arbre."}], "505": [{"formule": "Dijkstra : O((V+E) log V)", "imgPath": "assets/schemas/505-0-dijkstra.svg", "titre": "Dijkstra calcule A→D = 4 (via C,B), pas 4 direct... vérifié", "caption": "Sur ce graphe, Dijkstra calcule le plus court chemin A→D : direct AB+BD=4+1=5, mais A→C→B→D=1+2+1=4 est plus court — Dijkstra le trouve garanti, poids positifs."}, {"formule": "Bellman-Ford : O(VE)", "imgPath": "assets/schemas/505-1-bellmanford.svg", "titre": "V×E=20 pour ce graphe", "caption": "Pour V=4 sommets et E=5 arêtes, Bellman-Ford coûte O(VE)=20 opérations élémentaires — plus lent que Dijkstra mais accepte les poids négatifs."}], "506": [{"formule": "Choix local optimal → solution globale (si conditions)", "imgPath": "assets/schemas/506-0-glouton.svg", "titre": "Sélection d'activités, résolue glouton", "caption": "En choisissant toujours l'activité qui se termine le plus tôt (choix local), l'algorithme glouton obtient 4 activités compatibles sur 11, le maximum possible."}, {"formule": "Ex : activité, Huffman", "imgPath": "assets/schemas/506-1-huffman-freq.svg", "titre": "Fréquences des lettres de \"ABRACADABRA\", comptées", "caption": "Le codage de Huffman part des fréquences réelles des symboles (ici comptées sur \"ABRACADABRA\") pour attribuer les codes les plus courts aux lettres les plus fréquentes."}], "507": [{"formule": "DP[i] = solution optimale pour i", "imgPath": "assets/schemas/507-0-fibonacci-dp.svg", "titre": "Fibonacci calculé par programmation dynamique", "caption": "DP[i]=DP[i-1]+DP[i-2] calcule chaque valeur une seule fois en la stockant : F(8)=21, obtenu en O(n) au lieu d'un calcul récursif naïf en O(2ⁿ)."}, {"formule": "Complexité typique : O(n²)", "imgPath": "assets/schemas/507-1-complexite.svg", "titre": "O(n²), tracée", "caption": "De nombreux algorithmes de programmation dynamique (comme la distance d'édition) remplissent un tableau de taille n×n, d'où une complexité en O(n²)."}], "508": [{"formule": "Exploration exhaustive avec retour arrière", "imgPath": "assets/schemas/508-0-backtracking.svg", "titre": "Extrait de l'arbre de recherche des 4 reines", "caption": "Pour placer 4 reines sans conflit, le backtracking essaie une colonne, échoue, revient en arrière (retour arrière) et essaie une autre branche, sans jamais retester une branche déjà écartée."}, {"formule": "Complexité exponentielle", "imgPath": "assets/schemas/508-1-exponentielle.svg", "titre": "2ⁿ, tracée", "caption": "Le nombre de configurations explorées par un backtracking naïf croît en 2ⁿ (ou pire) : à n=12, cela fait déjà 4096 cas."}], "509": [{"formule": "Complexité : O(k^n)", "imgPath": "assets/schemas/509-0-kn.svg", "titre": "3ⁿ, tracée", "caption": "Pour k=3 choix par étape et n étapes, le nombre total de combinaisons 3ⁿ explose : à n=10, cela fait déjà 59049 cas."}, {"formule": "Exploration complète de l'espace des solutions", "imgPath": "assets/schemas/509-1-espace-solutions.svg", "titre": "2ⁿ sous-ensembles, calculés", "caption": "Explorer tous les sous-ensembles d'un ensemble de taille n coûte 2ⁿ : 32 pour n=5, mais plus d'un million pour n=20."}], "510": [{"formule": "O(1), O(log n), O(n), O(n log n), O(n²), O(2^n)", "imgPath": "assets/schemas/510-0-comparaison.svg", "titre": "5 complexités, calculées et comparées sur le même graphe", "caption": "Ces courbes sont calculées point par point pour n=1 à 20 : on voit concrètement le classement O(1) < O(log n) < O(n) < O(n log n) < O(n²)."}, {"formule": "Classes : P, NP, NP‑complet", "imgPath": "assets/schemas/510-1-PNP.svg", "titre": "P ⊆ NP, avec NP-complet à l'intérieur", "caption": "P (résolubles rapidement) est inclus dans NP (vérifiables rapidement) ; les problèmes NP-complets sont, s'ils existent hors de P, les plus difficiles de NP."}], "511": [{"formule": "ET, OU, NON", "imgPath": "assets/schemas/511-0-table-verite.svg", "titre": "Table de vérité, calculée pour les 4 cas", "caption": "Table de vérité complète (4 lignes) pour ET, OU et NON, calculée pour toutes les combinaisons de A et B."}, {"formule": "Tables de vérité", "imgPath": "assets/schemas/511-1-table-generale.svg", "titre": "La même table, référence générale", "caption": "Une table de vérité énumère systématiquement toutes les combinaisons d'entrées possibles et le résultat de chaque opérateur logique."}], "512": [{"formule": "Porte AND, OR, NOT", "imgPath": "assets/schemas/512-0-portes.svg", "titre": "Les 3 portes de base, schématisées", "caption": "AND, OR et NOT sont les trois portes logiques de base à partir desquelles on peut construire n'importe quel circuit logique."}, {"formule": "Porte XOR", "imgPath": "assets/schemas/512-1-xor.svg", "titre": "XOR, calculée pour les 4 cas", "caption": "XOR (ou exclusif) vaut 1 seulement quand A et B diffèrent, comme le montre cette table calculée."}], "513": [{"formule": "Automate fini : (Q, Σ, δ, q0, F)", "imgPath": "assets/schemas/513-0-automate.svg", "titre": "Un automate concret (Q={q0,q1,q2}, Σ={a,b})", "caption": "Q={q0,q1,q2}, Σ={a,b}, état initial q0 : les flèches donnent δ, la fonction de transition, calculée pour chaque symbole lu."}, {"formule": "Langages reconnus", "imgPath": "assets/schemas/513-1-langage.svg", "titre": "Test de mots sur l'automate ci-dessus", "caption": "En suivant les transitions de l'automate ci-dessus, \"aab\" et \"aabbb\" sont acceptés (terminent en q2, l'état final), \"ba\" est rejeté."}], "514": [{"formule": "CPU, RAM, ROM", "imgPath": "assets/schemas/514-0-architecture.svg", "titre": "Les trois composants reliés par un bus", "caption": "Le CPU communique avec la RAM (mémoire vive, effaçable) et la ROM (mémoire morte, permanente) via un bus de données."}, {"formule": "Cycle fetch-decode-execute", "imgPath": "assets/schemas/514-1-cycle.svg", "titre": "Le cycle d'exécution d'une instruction", "caption": "Chaque instruction passe par 3 étapes répétées en boucle : la chercher en mémoire (fetch), la décoder, puis l'exécuter."}], "515": [{"formule": "Grammaire : (V, Σ, R, S)", "imgPath": "assets/schemas/515-0-grammaire.svg", "titre": "Arbre de dérivation pour \"le chat dort\"", "caption": "Avec des règles R comme S→NP VP, cette grammaire dérive la phrase \"le chat dort\" : V={S,NP,VP}, Σ={mots}, S est le symbole de départ."}, {"formule": "Langages réguliers, context-free", "imgPath": "assets/schemas/515-1-hierarchie.svg", "titre": "Deux classes de langages, comparées", "caption": "Les langages réguliers (reconnus par un automate fini) sont strictement inclus dans les langages hors-contexte (qui nécessitent une pile)."}], "516": [{"formule": "Processus, threads", "imgPath": "assets/schemas/516-0-processus.svg", "titre": "Deux processus, l'un avec 2 threads", "caption": "Un processus (P1) peut contenir plusieurs threads qui partagent sa mémoire ; P2 est un processus totalement séparé, avec son propre espace mémoire."}, {"formule": "Mémoire virtuelle", "imgPath": "assets/schemas/516-1-memoire-virtuelle.svg", "titre": "Traduction virtuel → physique, illustrée", "caption": "La mémoire virtuelle traduit les adresses que voit un programme (0x1000...) vers de vraies adresses physiques en RAM (0x7A20...), gérées par le système."}], "517": [{"formule": "Analyse lexicale → syntaxique → sémantique", "imgPath": "assets/schemas/517-0-analyse.svg", "titre": "Les trois analyses, dans l'ordre", "caption": "Le compilateur découpe d'abord le code en tokens (lexicale), vérifie sa structure grammaticale (syntaxique), puis son sens (sémantique, ex: types)."}, {"formule": "Génération de code", "imgPath": "assets/schemas/517-1-generation.svg", "titre": "Un exemple de traduction", "caption": "Après les analyses, le compilateur traduit chaque instruction source (x=2+3) en instructions machine de bas niveau."}], "518": [{"formule": "TCP/IP", "imgPath": "assets/schemas/518-0-tcpip.svg", "titre": "Les 4 couches du modèle TCP/IP", "caption": "Le modèle TCP/IP organise la communication en 4 couches, chacune ajoutant ses propres informations avant transmission."}, {"formule": "Modèle OSI", "imgPath": "assets/schemas/518-1-osi.svg", "titre": "Les 7 couches OSI, listées", "caption": "Le modèle OSI détaille la communication réseau en 7 couches, du câble physique (couche 1) à l'application (couche 7)."}], "519": [{"formule": "Chiffrement symétrique / asymétrique", "imgPath": "assets/schemas/519-0-chiffrement.svg", "titre": "Comparaison symétrique vs asymétrique", "caption": "Le chiffrement symétrique utilise une seule clé partagée (rapide) ; l'asymétrique utilise une paire clé publique/privée (plus lent mais pas d'échange de secret)."}, {"formule": "Hash : H(x)", "imgPath": "assets/schemas/519-1-hash.svg", "titre": "Deux hachages réels, très différents", "caption": "H(\"bonjour\")=2cb4b1431b84 et H(\"Bonjour\")=9172e8eec99f : changer une seule lettre change complètement le hash (calculé ici avec sha256), la propriété clé d'une fonction de hachage."}], "520": [{"formule": "RSA : c = m^e mod n", "imgPath": "assets/schemas/520-0-rsa.svg", "titre": "RSA recalculé de bout en bout", "caption": "Avec p=5, q=11 (n=55), e=3, d=27 : m=4 chiffré donne c=9, puis déchiffré redonne bien 4=4."}, {"formule": "Diffie-Hellman", "imgPath": "assets/schemas/520-1-dh.svg", "titre": "Diffie-Hellman recalculé", "caption": "Avec g=7, p=23 : Alice (a=4) et Bob (b=9) aboutissent chacun à la même clé 2=2, sans jamais échanger a ni b."}], "600": [{"formule": "AM ≥ GM", "imgPath": "assets/schemas/600-0-amgm.svg", "titre": "6.5 ≥ 6.0, vérifié", "caption": "Pour a=4, b=9 : AM=(4+9)/2=6.5, GM=√(4×9)=6.0 : on vérifie bien AM ≥ GM."}, {"formule": "Cauchy-Schwarz : (Σ a_i b_i)² ≤ (Σ a_i²)(Σ b_i²)", "imgPath": "assets/schemas/600-1-cauchyschwarz.svg", "titre": "196 ≤ 221", "caption": "Pour a=(2,3), b=(1,4) : (2×1+3×4)²=196 et (2²+3²)(1²+4²)=221 : on vérifie 196 ≤ 221."}, {"formule": "Jensen : f(convex) → f(E[X]) ≤ E[f(X)]", "imgPath": "assets/schemas/600-2-jensen.svg", "titre": "9.0 ≤ 11.67", "caption": "Pour f(x)=x² (convexe) et X∈{1,3,5} équiprobables : f(E[X])=f(3)=9.0, E[f(X)]=(1+9+25)/3≈11.67 : 9.0 ≤ 11.67."}], "601": [{"formule": "AM-GM pour minimiser", "imgPath": "assets/schemas/601-0-minimisation.svg", "titre": "Minimum trouvé par AM-GM, vérifié sur le graphe", "caption": "AM-GM donne x+1/x ≥ 2√(x×1/x)=2, avec égalité en x=1 : le graphe confirme que le minimum est bien 2, atteint en x=1."}, {"formule": "Symétrisation", "imgPath": "assets/schemas/601-1-symetrisation.svg", "titre": "À somme fixée, le produit est maximal à l'égalité", "caption": "Pour une somme fixée à 8, comparer (2,6) et (4,4) montre que le produit est maximal quand les deux nombres sont égaux : c'est l'idée de symétrisation."}, {"formule": "Méthode des extremums", "imgPath": "assets/schemas/601-2-extremum.svg", "titre": "Minimum localisé par annulation de la dérivée", "caption": "f'(x)=2(x-2)=0 donne x=2, où le graphe confirme visuellement un minimum de valeur 1."}], "602": [{"formule": "a³ + b³ + c³ - 3abc = (a+b+c)(a²+b²+c² - ab - bc - ca)", "imgPath": "assets/schemas/602-0-factorisation.svg", "titre": "70 = 70", "caption": "Pour a=2, b=3, c=5 : les deux membres calculés séparément valent tous deux 70."}, {"formule": "a² + b² ≥ 2ab", "imgPath": "assets/schemas/602-1-carre.svg", "titre": "(a-b)² ≥ 0, donc a²+b² ≥ 2ab, vérifié pour b=3", "caption": "En fixant b=3, (a-3)²=a²-6a+9 reste toujours ≥ 0 (le graphe ne descend jamais sous 0), ce qui équivaut à a²+9 ≥ 6a, soit a²+b² ≥ 2ab."}], "603": [{"formule": "f(x+y)=f(x)+f(y)", "imgPath": "assets/schemas/603-0-cauchy-additive.svg", "titre": "21 = 21, vérifié pour f(x)=3x", "caption": "Pour f(x)=3x, x=2, y=5 : f(x+y)=f(7)=21 et f(x)+f(y)=6+15=21 — l'équation de Cauchy est vérifiée par toute fonction linéaire."}, {"formule": "f(xy)=f(x)f(y)", "imgPath": "assets/schemas/603-1-cauchy-mult.svg", "titre": "100 = 100, vérifié pour f(x)=x²", "caption": "Pour f(x)=x², x=2, y=5 : f(xy)=f(10)=100 et f(x)f(y)=4×25=100 — la multiplicativité est vérifiée."}], "604": [{"formule": "Invariant = quantité conservée", "imgPath": "assets/schemas/604-0-invariant.svg", "titre": "La somme reste 18 à chaque étape", "caption": "À chaque étape, on remplace deux nombres par leur somme : la liste change, mais la somme totale (18) reste invariante."}, {"formule": "Symétrie → réduction du problème", "imgPath": "assets/schemas/604-1-symetrie.svg", "titre": "Triangle équilatéral : 3 sommets interchangeables", "caption": "Ce triangle équilatéral a une symétrie 3 : ses sommets 1, 2, 3 jouent des rôles interchangeables, ce qui permet souvent de ne traiter qu'un seul cas au lieu de trois."}], "605": [{"formule": "u_{n+1} = f(u_n)", "imgPath": "assets/schemas/605-0-recurrence.svg", "titre": "u(n+1)=0,5u(n)+3, calculée, convergeant vers 6", "caption": "Avec u0=1 et u(n+1)=0,5u(n)+3, la suite calculée converge rapidement vers 6, le point fixe de f(x)=0,5x+3."}, {"formule": "Méthode de descente infinie", "imgPath": "assets/schemas/605-1-descente.svg", "titre": "Une suite d'entiers strictement décroissante", "caption": "La descente infinie construit une suite d'entiers positifs strictement décroissante (12>5>2>1>0) : comme ℕ est bien ordonné, une telle suite est nécessairement finie — contradiction si elle devait continuer indéfiniment."}], "606": [{"formule": "C(n,k) = n! / (k!(n-k)!)", "imgPath": "assets/schemas/606-0-binomial.svg", "titre": "C(8,k) calculé pour k=0..5", "caption": "C(8,k) est calculé ici pour chaque k : par exemple C(8,3)=56 façons de choisir 3 éléments parmi 8."}, {"formule": "Principe des tiroirs", "imgPath": "assets/schemas/606-1-tiroirs.svg", "titre": "10 pigeons, 9 cases : collision garantie", "caption": "Avec 10 objets à répartir dans seulement 9 cases, le principe des tiroirs garantit qu'au moins une case reçoit 2 objets ou plus."}, {"formule": "Inclusion-exclusion", "imgPath": "assets/schemas/606-2-inclusion-exclusion.svg", "titre": "|A∪B|=|A|+|B|-|A∩B|, sur les multiples", "caption": "Pour compter les nombres ≤100 multiples de 2 ou 3 : |A∪B|=|A|+|B|-|A∩B|=50+33-16=67, en évitant de compter deux fois les multiples de 6."}], "607": [{"formule": "Connexité", "imgPath": "assets/schemas/607-0-connexite.svg", "titre": "2 composantes connexes : {A,B,C} et {D,E}", "caption": "Ce graphe a 2 composantes connexes : {A,B,C} (reliés) et {D,E} (reliés entre eux mais isolés du reste) — il n'est donc pas connexe."}, {"formule": "Cycles", "imgPath": "assets/schemas/607-1-cycle.svg", "titre": "A-B-C-A : un cycle de longueur 3", "caption": "A→B→C→A forme un cycle de longueur 3 : on revient au sommet de départ sans repasser par une arête déjà utilisée."}, {"formule": "Colorations", "imgPath": "assets/schemas/607-2-coloration.svg", "titre": "2 couleurs suffisent pour ce cycle pair", "caption": "Ce cycle de longueur 4 (paire) se colore avec seulement 2 couleurs en alternant, sans que deux sommets adjacents partagent la même couleur."}], "608": [{"formule": "a ≡ b (mod n)", "imgPath": "assets/schemas/608-0-congruence.svg", "titre": "23 ≡ 2 (mod 7)", "caption": "23 mod 7 = 2, donc 23 ≡ 2 (mod 7) : 23 et 2 laissent le même reste dans la division par 7."}, {"formule": "PGCD, PPCM", "imgPath": "assets/schemas/608-1-euclide.svg", "titre": "pgcd(84,36)=12, calculé par Euclide", "caption": "L'algorithme d'Euclide calcule pgcd(84,36)=12 en 2 divisions successives ; le ppcm s'en déduit : ppcm=84×36/12=252."}, {"formule": "Petit théorème de Fermat", "imgPath": "assets/schemas/608-2-fermat.svg", "titre": "a⁶ mod 7 = 1 pour tout a de 1 à 6, vérifié", "caption": "Pour p=7 (premier), a^(p-1) mod p = 1 pour tout a non multiple de 7, vérifié ici pour a=1 à 6."}], "609": [{"formule": "ax + by = c", "imgPath": "assets/schemas/609-0-diophantienne.svg", "titre": "Solution trouvée par Bézout, vérifiée", "caption": "Pour 12x+8y=4 : pgcd(12,8)=4 divise 4, donc il existe une solution — trouvée ici par l'algorithme d'Euclide étendu : (1,-1), vérifiée par calcul direct."}, {"formule": "Méthode de descente infinie", "imgPath": "assets/schemas/609-1-descente-dioph.svg", "titre": "Suite décroissante, comme pour x²+y²=3z²", "caption": "Pour montrer qu'une équation diophantienne n'a que la solution triviale, on suppose une solution non triviale minimale, puis on en construit une plus petite (descente) — contradiction."}], "610": [{"formule": "Pythagore", "imgPath": "assets/schemas/610-0-pythagore.svg", "titre": "Triangle 6-8-10.0", "caption": "Pour a=6, b=8 : c=√(36+64)=√100=10.0 — le triple pythagoricien classique (6,8,10)."}, {"formule": "Puissance d'un point", "imgPath": "assets/schemas/610-1-puissance.svg", "titre": "Puissance = -8 (négative : M est dans le cercle)", "caption": "Pour un cercle de centre (3,3), rayon 4, et M(1,1) : la puissance de M vaut -8 — négative car M est à l'intérieur du cercle."}, {"formule": "Angles inscrits", "imgPath": "assets/schemas/610-2-angle-inscrit.svg", "titre": "Angle inscrit ≈ 63.4°, calculé", "caption": "L'angle inscrit en C, qui intercepte [AB], est calculé ici à environ 63.4° à partir des coordonnées réelles du triangle."}], "611": [{"formule": "G = (mA A + mB B) / (mA + mB)", "imgPath": "assets/schemas/611-0-barycentre.svg", "titre": "G calculé, plus proche de A (masse double)", "caption": "Pour A(1,1) de masse 2 et B(6,3) de masse 1, G=(2A+B)/3=(2.67 ; 1.67), plus proche de A car sa masse est double."}, {"formule": "Somme vectorielle pondérée", "imgPath": "assets/schemas/611-1-somme-ponderee.svg", "titre": "La définition vectorielle du barycentre", "caption": "Par définition, le barycentre G vérifie mA×→GA + mB×→GB = →0 : c'est cette relation vectorielle qui caractérise G."}], "612": [{"formule": "Coloration minimale", "imgPath": "assets/schemas/612-0-coloration.svg", "titre": "3 couleurs suffisent (triangle A-B-C impose ≥3)", "caption": "Ce graphe contient un triangle (A-B-C), qui impose au moins 3 couleurs différentes ; 3 couleurs suffisent aussi pour tout le graphe."}, {"formule": "Invariants de coloration", "imgPath": "assets/schemas/612-1-invariant-coloration.svg", "titre": "Le nombre chromatique, invariant selon la structure", "caption": "Le nombre minimal de couleurs nécessaires (nombre chromatique) est un invariant qui dépend de la structure : 2 pour un cycle pair, 3 pour un cycle impair ou un triangle."}], "613": [{"formule": "Pavage = partition du plan", "imgPath": "assets/schemas/613-0-pavage.svg", "titre": "Un damier : 32 cases, sans trou ni recouvrement", "caption": "Ce damier 4×8 pave un rectangle avec 32 cases identiques : chaque point est couvert exactement une fois, sans trou ni chevauchement."}, {"formule": "Invariants de parité", "imgPath": "assets/schemas/613-1-parite.svg", "titre": "Damier mutilé : le comptage par couleur, invariant clé", "caption": "En retirant deux coins opposés (même couleur), on obtient 15 cases d'une couleur et 17 de l'autre : un domino couvrant toujours une case de chaque couleur, le pavage devient impossible — argument de parité classique."}], "614": [{"formule": "Symétrisation → réduction du problème", "imgPath": "assets/schemas/614-0-symetrisation.svg", "titre": "Minimum atteint à la configuration symétrique", "caption": "Comme pour 601, le minimum de x+1/x est atteint en x=1, le point \"symétrique\" où x=1/x : symétriser le problème en devinant ce point simplifie souvent la preuve."}, {"formule": "AM-GM pour symétriser", "imgPath": "assets/schemas/614-1-amgm-symetrie.svg", "titre": "AM=GM exactement au point symétrique", "caption": "Quand a=b=c=3, AM=GM=3 exactement : l'égalité dans AM-GM n'a lieu qu'au point parfaitement symétrique, ce qui guide la recherche de l'optimum."}], "615": [{"formule": "Invariant = quantité conservée", "imgPath": "assets/schemas/615-0-invariant.svg", "titre": "La somme, invariante à chaque étape", "caption": "Comme dans l'exemple de la fiche 604, une quantité (ici la somme totale) reste rigoureusement constante à chaque étape : c'est un invariant."}, {"formule": "Monovariant = quantité monotone", "imgPath": "assets/schemas/615-1-monovariant.svg", "titre": "Une suite qui ne fait que décroître (ou rester stable)", "caption": "Un monovariant ne fait que décroître (ou rester stable) à chaque étape, sans jamais remonter : puisqu'il est borné (ici par 0), le processus doit s'arrêter."}], "700": [{"formule": "Norme : ||x||", "imgPath": "assets/schemas/700-0-norme.svg", "titre": "||x|| calculée", "caption": "Pour x=(3,-4), ||x||=√(3²+4²)=√25=5.0."}, {"formule": "Distance : d(x,y)=||x−y||", "imgPath": "assets/schemas/700-1-distance-norme.svg", "titre": "Distance induite par la norme", "caption": "Pour x=(3,-4) et y=(0,1), d(x,y)=||x-y||=√(3²+5²)=√34≈5.831."}, {"formule": "Normes usuelles : ||x||₁, ||x||₂, ||x||∞", "imgPath": "assets/schemas/700-2-normes-usuelles.svg", "titre": "Trois normes du même vecteur, comparées", "caption": "Pour x=(3,-4) : ||x||₁=7, ||x||₂=5.0, ||x||∞=4 — trois valeurs différentes pour le même vecteur."}], "701": [{"formule": "Distance : d(x,y)", "imgPath": "assets/schemas/701-0-distance.svg", "titre": "d(x,y)=5.0", "caption": "d(x,y)=√((4-1)²+(5-1)²)=√25=5.0, une distance calculée dans l'espace métrique (ℝ², d euclidienne)."}, {"formule": "Boule : B(x,r)", "imgPath": "assets/schemas/701-1-boule.svg", "titre": "B(x, 1,5), le disque des points à distance < r", "caption": "B(x,r) regroupe tous les points à distance strictement inférieure à r=1,5 du centre x : dans ℝ² muni de la distance euclidienne, c'est un disque ouvert."}, {"formule": "Convergence : x_n → x", "imgPath": "assets/schemas/701-2-convergence.svg", "titre": "xₙ=1+3/n, convergeant vers 1", "caption": "La suite xₙ=1+3/n, calculée ici pour n=1 à 7, se rapproche de plus en plus de 1 : d(xₙ,1)=3/n tend vers 0."}], "702": [{"formule": "Ouverts, fermés", "imgPath": "assets/schemas/702-0-ouvert-ferme.svg", "titre": "]1,3[ ouvert (bords ronds = exclus)", "caption": "]1,3[ est ouvert : ses bords 1 et 3 (cercles vides) ne sont pas inclus dans l'ensemble ; [1,3] serait fermé, avec des bords pleins."}, {"formule": "Adhérence, intérieur", "imgPath": "assets/schemas/702-1-adherence.svg", "titre": "L'adhérence ajoute les points-limites", "caption": "L'adhérence de ]1,3[ est [1,3] : elle ajoute les points-limites 1 et 3 ; l'intérieur de [1,3] est ]1,3[, qui retire les bords."}, {"formule": "Frontière", "imgPath": "assets/schemas/702-2-frontiere.svg", "titre": "Les 2 points-frontière, isolés", "caption": "La frontière de ]1,3[ (ou de [1,3]) est {1,3} : les points qui séparent l'intérieur de l'extérieur, qu'ils soient inclus ou non dans l'ensemble."}], "703": [{"formule": "Σ f_n(x)", "imgPath": "assets/schemas/703-0-somme-partielle.svg", "titre": "Sommes partielles de Σxⁿ, calculées et tracées", "caption": "Les sommes partielles de Σxⁿ (pour n=2, 5, 15) se rapprochent de plus en plus de 1/(1-x) sur ]-1,1[ à mesure qu'on ajoute des termes."}, {"formule": "Convergence simple / uniforme", "imgPath": "assets/schemas/703-1-simple-uniforme.svg", "titre": "fn(x)=xⁿ sur [0,1] : convergence simple mais pas uniforme", "caption": "fₙ(x)=xⁿ converge simplement vers 0 sur [0,1[ (et vers 1 en x=1), mais pas uniformément : la \"bosse\" près de x=1 ne s'aplatit jamais complètement."}, {"formule": "Théorème de Weierstrass", "imgPath": "assets/schemas/703-2-weierstrass.svg", "titre": "Critère de convergence normale, illustré", "caption": "Le critère de Weierstrass majore chaque |fₙ(x)| par un terme Mₙ indépendant de x ; si ΣMₙ converge (ici 0,5+0,25+0,125+...), la série converge normalement, donc uniformément."}], "704": [{"formule": "f(x)=a0+Σ(an cos(nx)+bn sin(nx))", "imgPath": "assets/schemas/704-0-fourier-somme.svg", "titre": "Approximation de Fourier d'un signal carré, calculée", "caption": "La somme de Fourier (7 premiers termes, coefficients calculés par intégration numérique) approche déjà bien le signal carré d'origine."}, {"formule": "an = ∫ f(x)cos(nx) dx", "imgPath": "assets/schemas/704-1-coeff-a.svg", "titre": "a0 et a1 calculés numériquement", "caption": "Pour ce signal créneau (impair), a0=0.0≈0 et a1≈0 aussi : tous les coefficients an sont nuls par symétrie, calculé ici numériquement."}, {"formule": "bn = ∫ f(x)sin(nx) dx", "imgPath": "assets/schemas/704-2-coeff-b.svg", "titre": "b1 et b3, calculés numériquement", "caption": "b1≈1.2732≈4/π et b3≈0.4244≈4/(3π) : les coefficients impairs portent toute l'énergie du signal créneau, calculés ici par intégration numérique réelle."}], "705": [{"formule": "Holomorphie", "imgPath": "assets/schemas/705-0-holomorphe.svg", "titre": "La grille verticale transformée par z↦z², calculée point par point", "caption": "Chaque droite verticale x=cste, transformée par la fonction holomorphe z↦z², devient une parabole : la fonction est calculée et tracée point par point."}, {"formule": "Résidus", "imgPath": "assets/schemas/705-1-residu.svg", "titre": "Résidu calculé pour un pôle simple", "caption": "Pour f(z)=1/(z-1), le résidu en son unique pôle z=1 vaut 1 (coefficient du terme en 1/(z-1) dans le développement de Laurent)."}, {"formule": "∮ f(z) dz", "imgPath": "assets/schemas/705-2-contour.svg", "titre": "Intégrale de contour, calculée via le résidu", "caption": "Le théorème des résidus donne ∮f(z)dz = 2πi×(somme des résidus) = 2πi×1 ≈ 6.2832i, pour un contour entourant le pôle z=1."}], "706": [{"formule": "f holomorphe ⇒ conforme", "imgPath": "assets/schemas/706-0-grille-conforme.svg", "titre": "La grille orthogonale reste orthogonale après transformation par z²", "caption": "Les courbes bleues (images des verticales) et oranges (images des horizontales) se recoupent toujours à angle droit, même déformées : z↦z² est conforme, elle préserve les angles."}, {"formule": "Préservation des angles", "imgPath": "assets/schemas/706-1-angles.svg", "titre": "90° préservé : 90.0°", "caption": "En z0=1+i, deux directions perpendiculaires (90°) restent perpendiculaires après application de la dérivée f'(z0) : 90.0° calculé, confirmant la conformité."}], "707": [{"formule": "y' = ay", "imgPath": "assets/schemas/707-0-exponentielle.svg", "titre": "Solution y'=0,5y, y(0)=2, tracée", "caption": "y'=ay (a=0,5) a pour solution y(t)=y0×e^(at) : ici y0=2, tracée et croissante exponentiellement."}, {"formule": "y'' + ω² y = 0", "imgPath": "assets/schemas/707-1-oscillateur.svg", "titre": "Solution oscillante, ω=1,5, tracée", "caption": "y''+ω²y=0 (ω=1,5) admet des solutions oscillantes comme y(t)=cos(1,5t), vérifiable en calculant y''=-2,25cos(1,5t)=-ω²y."}, {"formule": "Méthode de variation de la constante", "imgPath": "assets/schemas/707-2-variation-constante.svg", "titre": "Étapes calculées pour y'+2y=eᵗ", "caption": "En posant y=C(t)e^(-2t) et en injectant dans y'+2y=e^t, on trouve C'(t)=e^(3t), d'où C(t)=e^(3t)/3 : la méthode calcule explicitement la solution particulière."}], "708": [{"formule": "Produit scalaire", "imgPath": "assets/schemas/708-0-produit-scalaire.svg", "titre": "u·v=7", "caption": "Pour u=(2,1,3), v=(1,-1,2) dans ℝ³ (cas simple d'espace de Hilbert), u·v=7, calculé terme à terme."}, {"formule": "Complétude", "imgPath": "assets/schemas/708-1-completude.svg", "titre": "Suite de Cauchy convergeant (vers φ≈1,618)", "caption": "Une suite de Cauchy comme celle-ci (qui se resserre de plus en plus) converge vers une limite qui reste dans l'espace : c'est la complétude, propriété clé d'un espace de Hilbert."}, {"formule": "Base orthonormée", "imgPath": "assets/schemas/708-2-base-orthonormee.svg", "titre": "La base canonique de ℝ³, vérifiée orthonormée", "caption": "e1, e2, e3 sont deux à deux orthogonaux (produit scalaire nul, vérifié) et chacun de norme 1 : c'est une base orthonormée."}], "709": [{"formule": "Norme", "imgPath": "assets/schemas/709-0-norme-banach.svg", "titre": "||x||=5.0", "caption": "Pour x=(3,4,0), ||x||=√(9+16+0)=√25=5.0, la norme euclidienne dans cet espace vectoriel normé."}, {"formule": "Complétude", "imgPath": "assets/schemas/709-1-completude.svg", "titre": "Une suite de Cauchy qui converge dans l'espace", "caption": "Comme pour les espaces de Hilbert, la complétude signifie que toute suite de Cauchy (qui se resserre, comme celle-ci) converge vers une limite qui reste dans l'espace."}, {"formule": "Applications linéaires continues", "imgPath": "assets/schemas/709-2-continue.svg", "titre": "f(x)=3x, continue et bornée sur tout compact", "caption": "f(x)=3x est une application linéaire continue : de petites variations de x entraînent de petites variations de f(x), visibles sur cette droite sans saut."}], "710": [{"formule": "Σ a_n (x−x0)^n", "imgPath": "assets/schemas/710-0-serie-entiere.svg", "titre": "La série entière de eˣ approchée par 6 termes, calculée", "caption": "La somme partielle Σx^k/k! (6 premiers termes) approche déjà très bien eˣ sur [-2,2] : c'est le principe d'une série entière."}, {"formule": "Rayon de convergence R", "imgPath": "assets/schemas/710-1-rayon.svg", "titre": "Le rapport aₙ₊₁/aₙ tend vers 1 → R=1", "caption": "Pour Σxⁿ/n, le rapport |aₙ₊₁/aₙ| calculé se rapproche de 1 : par le critère de d'Alembert, le rayon de convergence est R=1."}, {"formule": "Test de Cauchy", "imgPath": "assets/schemas/710-2-cauchy.svg", "titre": "|aₙ|^(1/n) → 1, calculé pour n croissant", "caption": "Le test de Cauchy calcule |aₙ|^(1/n) pour Σxⁿ/n : la limite vaut 1, confirmant le même rayon de convergence R=1 trouvé par d'Alembert."}], "711": [{"formule": "A = P D P^{-1}", "imgPath": "assets/schemas/711-0-diagonalisation.svg", "titre": "P et D pour A=[[3,1],[0,2]], calculées", "caption": "Pour A=[[3,1],[0,2]] (valeurs propres 3,2), P (vecteurs propres) et D (valeurs propres) vérifient A=PDP⁻¹."}, {"formule": "Valeurs propres", "imgPath": "assets/schemas/711-1-valeurs-propres.svg", "titre": "λ=2 et λ=3, calculées comme racines", "caption": "Les valeurs propres de A=[[3,1],[0,2]] sont les racines de det(A-λI)=(3-λ)(2-λ) : λ=2 et λ=3, visibles ici où la courbe touche l'axe."}, {"formule": "Formes quadratiques", "imgPath": "assets/schemas/711-2-forme-quadratique.svg", "titre": "Q(x,y)=x²/4+y²=1, une ellipse calculée", "caption": "La forme quadratique Q(x,y)=x²/4+y² définit, pour Q=1, une ellipse calculée point par point à partir de l'équation."}], "712": [{"formule": "E(X|Y)", "imgPath": "assets/schemas/712-0-esperance-conditionnelle.svg", "titre": "E(X|Y=y) calculée pour chaque valeur de Y", "caption": "Pour X=somme de 2 dés, Y=1er dé : E(X|Y=y)=y+3,5, calculée ici pour chaque y=1..6 (par exemple E(X|Y=1)=4,5)."}, {"formule": "Cov(X,Y)", "imgPath": "assets/schemas/712-1-covariance.svg", "titre": "Cov=1.2", "caption": "Sur ces 5 points, Cov(X,Y)=E(XY)-E(X)E(Y)=13.2-12.0=1.2."}, {"formule": "Loi normale", "imgPath": "assets/schemas/712-2-normale.svg", "titre": "N(0,1), tracée", "caption": "La loi normale centrée réduite N(0,1), calculée point par point, est la référence de toutes les autres lois normales par changement d'échelle."}], "713": [{"formule": "Estimateur", "imgPath": "assets/schemas/713-0-estimateur.svg", "titre": "Moyenne empirique = 5.0", "caption": "Sur cet échantillon de 7 mesures, la moyenne empirique x̄=5.0 est un estimateur naturel de la moyenne réelle inconnue."}, {"formule": "Intervalle de confiance", "imgPath": "assets/schemas/713-1-ic.svg", "titre": "IC à 95%, calculé sur l'échantillon", "caption": "Avec x̄=5.0, écart-type s≈0.216, n=7 : l'intervalle de confiance à 95% est [4.84 ; 5.16], calculé directement."}, {"formule": "Test d’hypothèse", "imgPath": "assets/schemas/713-2-test.svg", "titre": "z=0.0, calculé", "caption": "Pour tester H0:μ=5 contre cet échantillon, z=0.0 — comme |z|<1,96, on ne rejette pas H0 au seuil de 5%."}], "714": [{"formule": "Lagrangien L = T − V", "imgPath": "assets/schemas/714-0-lagrangien.svg", "titre": "L=3.38 J", "caption": "Pour m=2 kg, v=3 m/s (T=9 J) et un ressort k=5 N/m, x=1,5 m (V=5,625 J) : L=T-V=3.38 J."}, {"formule": "Équations d’Euler-Lagrange", "imgPath": "assets/schemas/714-1-euler-lagrange.svg", "titre": "L'équation du ressort, retrouvée", "caption": "En appliquant d/dt(∂L/∂v)=∂L/∂x au lagrangien L=½mv²-½kx² du système précédent, on retrouve exactement ma=-kx, l'équation du ressort."}], "715": [{"formule": "P, NP, NP‑complet", "imgPath": "assets/schemas/715-0-PNP.svg", "titre": "P ⊆ NP, avec NP-complet à l'intérieur", "caption": "P (résoluble rapidement) est inclus dans NP (vérifiable rapidement) ; les problèmes NP-complets sont les plus difficiles de NP."}, {"formule": "Automates, grammaires", "imgPath": "assets/schemas/715-1-automate.svg", "titre": "Un automate concret, comme fondement des langages formels", "caption": "Les automates (comme celui-ci, Q={q0,q1,q2}) et les grammaires formalisent respectivement la reconnaissance et la génération des langages."}], "11": [{"formule": "Critère de Cauchy", "imgPath": "assets/schemas/11-0-cauchy.svg", "titre": "Sommes partielles de Σ1/n², resserrées (Cauchy)", "caption": "Les sommes partielles Sn de Σ1/n², calculées ici jusqu'à n=8, varient de moins en moins : |Sn-Sm|→0, le critère de Cauchy est satisfait."}, {"formule": "Séries de Riemann : Σ1/n^α converge ssi α>1", "imgPath": "assets/schemas/11-1-riemann.svg", "titre": "Somme partielle (200 termes) selon α, calculée", "caption": "Pour α=0,5 et α=1, la somme (tronquée à 200 termes) continue de grossir sans borne ; pour α>1, elle se stabilise déjà nettement — cohérent avec la convergence ssi α>1."}, {"formule": "Critère de d'Alembert", "imgPath": "assets/schemas/11-2-dalembert.svg", "titre": "aₙ₊₁/aₙ → 0 pour Σ1/n!, calculé", "caption": "Pour Σ1/n!, le rapport aₙ₊₁/aₙ=1/(n+1), calculé ici, tend vers 0 : bien inférieur à 1, la série converge (très vite) par le critère de d'Alembert."}], "12": [{"formule": "Théorème de Rolle", "imgPath": "assets/schemas/12-0-rolle.svg", "titre": "f(1)=f(4), tangente horizontale trouvée en x=2,5", "caption": "f(1)=f(4)=2 (mêmes valeurs aux extrémités) : le théorème de Rolle garantit un point où f'(c)=0 — ici c=2,5, la tangente horizontale visible sur le graphe."}, {"formule": "TAF : f(b)-f(a)=f'(c)(b-a)", "imgPath": "assets/schemas/12-1-taf.svg", "titre": "c≈2.0 trouvé, tangente parallèle à la sécante", "caption": "Pour f(x)=x²-2x sur [0,5 ; 3,5], le TAF garantit un point c où la tangente est parallèle à la sécante (a,f(a))-(b,f(b)) : calculé ici, c≈2.0."}, {"formule": "Théorème des valeurs intermédiaires", "imgPath": "assets/schemas/12-2-tvi.svg", "titre": "f change de signe, une racine trouvée", "caption": "f(0)=-1<0 et f(3)=14>0 : par le TVI, f s'annule quelque part entre 0 et 3 — la racine est visible ici autour de x≈2,28."}], "13": [{"formule": "∫ₐᵇ f(x)dx = F(b)-F(a)", "imgPath": "assets/schemas/13-0-integrale.svg", "titre": "∫₀³x²dx = 9.0, calculée", "caption": "∫₀³x²dx = [x³/3]₀³ = 27/3 = 9.0 : l'aire sous la parabole de 0 à 3."}, {"formule": "Intégration par parties", "imgPath": "assets/schemas/13-1-ipp.svg", "titre": "∫₀² x eˣ dx = 8.389", "caption": "Avec u=x, dv=eˣdx : ∫₀²xeˣdx = [xeˣ-eˣ]₀² = (2e²-e²)-(0-1) = e²+1 ≈ 8.389."}, {"formule": "Changement de variable", "imgPath": "assets/schemas/13-2-changement-variable.svg", "titre": "= ln5 ≈ 1.609", "caption": "Avec u=1+x², du=2xdx : ∫₀²2x/(1+x²)dx = ∫₁⁵du/u = [ln u]₁⁵ = ln5 ≈ 1.609."}], "14": [{"formule": "Gradient ∇f", "imgPath": "assets/schemas/14-0-gradient.svg", "titre": "∇f perpendiculaire aux lignes de niveau, calculé", "caption": "Pour f(x,y)=x²+y² en (1 ; 1,5), ∇f=(2x,2y)=(2.0,3.0), calculé par différences finies, toujours perpendiculaire aux lignes de niveau (cercles)."}, {"formule": "Théorème de Schwarz : ∂²f/∂x∂y=∂²f/∂y∂x", "imgPath": "assets/schemas/14-1-schwarz.svg", "titre": "Égalité vérifiée numériquement", "caption": "Pour f(x,y)=x²y+sin(xy), les deux dérivées croisées calculées par différences finies coïncident : ≈0.574, confirmant le théorème de Schwarz."}, {"formule": "Multiplicateurs de Lagrange", "imgPath": "assets/schemas/14-2-lagrange.svg", "titre": "Maximum de xy sous x+y=10, trouvé en x=y=5", "caption": "Pour maximiser f(x,y)=xy sous la contrainte x+y=10, ∇f=λ∇g donne (y,x)=λ(1,1), donc x=y ; avec x+y=10, x=y=5 et xy=25, le maximum."}], "15": [{"formule": "y'+a(x)y=b(x)", "imgPath": "assets/schemas/15-0-edl1.svg", "titre": "Solution de y'+y=x, calculée", "caption": "Pour y'+y=x, la solution générale y=Ce⁻ˣ+x-1 (ici C=2) combine une exponentielle décroissante (partie homogène) et x-1 (partie particulière)."}, {"formule": "Équation caractéristique : ar²+br+c=0", "imgPath": "assets/schemas/15-1-caracteristique.svg", "titre": "r=2 et r=3, calculées comme racines", "caption": "Pour y''-5y'+6y=0, l'équation caractéristique r²-5r+6=0 a pour racines r=2 et r=3, donnant y=C1e^(2x)+C2e^(3x)."}, {"formule": "X'=AX ⟹ X(t)=exp(tA)X₀", "imgPath": "assets/schemas/15-2-systeme.svg", "titre": "Solution du système, calculée et tracée", "caption": "Pour X'=AX avec A=[[0,1],[-1,0]] et X0=(1,0), la solution X(t)=exp(tA)X0=(cos t, -sin t), calculée et tracée ici, décrit une rotation."}], "16": [{"formule": "Laplace : L{f}(s)=∫f(t)e^{-st}dt", "imgPath": "assets/schemas/16-0-laplace.svg", "titre": "L{e⁻²ᵗ}(s), calculée numériquement pour 3 valeurs de s", "caption": "Pour f(t)=e⁻²ᵗ, la transformée de Laplace est calculée ici par intégration numérique pour s=1,3,5, et coïncide avec la formule théorique 1/(s+2)."}, {"formule": "Fourier : f̂(ξ)=∫f(x)e^{-2iπxξ}dx", "imgPath": "assets/schemas/16-1-fourier.svg", "titre": "La transformée de Fourier, définie", "caption": "La transformée de Fourier f̂(ξ) mesure la présence de chaque fréquence ξ dans le signal f, généralisant les séries de Fourier aux fonctions non périodiques."}, {"formule": "Théorème de convolution", "imgPath": "assets/schemas/16-2-convolution.svg", "titre": "f*g calculée directement, terme à terme", "caption": "Le produit de convolution (f*g)[i]=Σf[k]g[i-k] est calculé ici terme à terme pour f=(1,2,3) et g=(1,0,-1) : le théorème affirme que sa transformée est le simple produit des transformées."}], "17": [{"formule": "Espace métrique (E,d)", "imgPath": "assets/schemas/17-0-espace-metrique.svg", "titre": "d(x,y)=5.0", "caption": "(ℝ²,d) avec la distance euclidienne : d(x,y)=√((4-1)²+(6-2)²)=5.0, un exemple concret d'espace métrique."}, {"formule": "Compacité : de tout recouvrement ouvert on extrait un sous-recouvrement fini", "imgPath": "assets/schemas/17-1-compacite.svg", "titre": "Un recouvrement fini de [0,1], construit explicitement", "caption": "[0,1] est compact : de tout recouvrement par des ouverts, on peut extraire un sous-recouvrement fini, comme ces 4 intervalles qui suffisent déjà à tout couvrir."}, {"formule": "Théorème du point fixe de Banach", "imgPath": "assets/schemas/17-2-banach-fixe.svg", "titre": "xₙ₊₁=cos(xₙ) converge vers ≈0,739, calculé", "caption": "cos est contractante sur un intervalle adapté : la suite xₙ₊₁=cos(xₙ), calculée ici, converge vers l'unique point fixe x≈0,739 où cos(x)=x."}], "18": [{"formule": "Théorème de convergence dominée", "imgPath": "assets/schemas/18-0-convergence-dominee.svg", "titre": "∫fₙ calculée pour n croissant, stable", "caption": "Pour fₙ(x)=nxe^(-nx²), dominée par une fonction intégrable fixe, les intégrales calculées ici pour n=1,5,20 restent bornées : la limite peut passer sous le signe intégrale."}, {"formule": "Lemme de Fatou", "imgPath": "assets/schemas/18-1-fatou.svg", "titre": "liminf ∫fₙ ≥ ∫ liminf fₙ, illustré", "caption": "Le lemme de Fatou garantit seulement une inégalité liminf∫fₙ ≥ ∫liminf(fₙ), pas toujours l'égalité : ici, chaque fₙ transporte une même \"bosse\" qui s'échappe, liminf fₙ=0 partout mais ∫fₙ ne tend pas vers 0."}, {"formule": "Théorème de Fubini-Tonelli", "imgPath": "assets/schemas/18-2-fubini.svg", "titre": "36 = 36, les deux ordres coïncident", "caption": "La double somme Σᵢⱼ i×j pour i,j=1..3, calculée en sommant d'abord sur j puis sur i (36), ou l'inverse (36), donne le même résultat : c'est l'esprit du théorème de Fubini."}], "19": [{"formule": "Inégalité de Cauchy-Schwarz : |<x,y>|≤||x||·||y||", "imgPath": "assets/schemas/19-0-cauchyschwarz.svg", "titre": "3 ≤ 9.165, vérifié", "caption": "Pour u=(2,1,3), v=(1,-2,1) : |u·v|=3 et ||u||×||v||≈9.165 : l'inégalité de Cauchy-Schwarz est vérifiée."}, {"formule": "Théorème de projection orthogonale", "imgPath": "assets/schemas/19-1-projection.svg", "titre": "proj(w)=(2,3,0), calculée", "caption": "Pour w=(2,3,4) projeté orthogonalement sur le plan z=0, proj(w)=(2,3,0) : c'est le point du plan le plus proche de w, en distance minimale."}, {"formule": "Théorème de représentation de Riesz", "imgPath": "assets/schemas/19-2-riesz.svg", "titre": "φ identifiée à y=(2,3)", "caption": "La forme linéaire φ(x1,x2)=2x1+3x2 s'écrit φ(x)=x·y avec y=(2,3) : le théorème de Riesz garantit que toute forme linéaire continue s'identifie ainsi à un vecteur."}], "20": [{"formule": "Formule intégrale de Cauchy", "imgPath": "assets/schemas/20-0-cauchy-formule.svg", "titre": "f(a) retrouvée par l'intégrale de contour, calculée", "caption": "Pour f(z)=z², a=0,3+0,2i : l'intégrale de contour calculée numériquement redonne bien f(a)=a²≈0.05+0.12i."}, {"formule": "Théorème des résidus", "imgPath": "assets/schemas/20-1-residus.svg", "titre": "Résidus pour un pôle simple vs un pôle double", "caption": "Pour un pôle double comme 1/(z-2)², le résidu (coefficient du terme en 1/(z-a)) est nul, contrairement au pôle simple 1/(z-2) dont le résidu vaut 1."}, {"formule": "Développement en série de Laurent", "imgPath": "assets/schemas/20-2-laurent.svg", "titre": "Coefficients de Laurent de 1/(z(z-1)) autour de 0, calculés", "caption": "1/(z(z-1)) = -1/z -1 -z -z²-... : le développement de Laurent autour de 0, dont les premiers coefficients sont calculés ici, révèle un pôle simple (terme en 1/z)."}], "21": [{"formule": "Dérivée au sens des distributions", "imgPath": "assets/schemas/21-0-derivee-distribution.svg", "titre": "La fonction échelon, approchée finement", "caption": "La fonction de Heaviside (échelon) n'est pas dérivable classiquement en 0 ; sa dérivée au sens des distributions est le Dirac δ, une masse concentrée exactement au saut."}, {"formule": "Distribution de Dirac δ", "imgPath": "assets/schemas/21-1-dirac.svg", "titre": "δ approchée par un pic de plus en plus concentré", "caption": "δ n'est pas une fonction ordinaire, mais on peut se la représenter comme la limite de pics de plus en plus étroits et hauts, d'aire toujours égale à 1, comme celui calculé et tracé ici."}, {"formule": "Espace de Sobolev Wᵏ,ᵖ", "imgPath": "assets/schemas/21-2-sobolev.svg", "titre": "La définition de W^(1,2), résumée", "caption": "L'espace de Sobolev W^(1,2) regroupe les fonctions f dont la dérivée (au sens des distributions) est encore de carré intégrable, une hypothèse plus faible que la dérivabilité classique."}], "22": [{"formule": "Équation de la chaleur : ∂u/∂t=Δu", "imgPath": "assets/schemas/22-0-chaleur.svg", "titre": "La solution (noyau de la chaleur) à 3 instants, calculée", "caption": "Partant d'un pic concentré, la solution de l'équation de la chaleur s'étale et s'aplatit au cours du temps : ces 3 courbes sont calculées directement par la formule du noyau gaussien."}, {"formule": "Équation des ondes : ∂²u/∂t² = c² ∂²u/∂x²", "imgPath": "assets/schemas/22-1-ondes.svg", "titre": "La solution se translate sans se déformer, calculée", "caption": "Une solution de l'équation des ondes de la forme u(x,t)=f(x-ct) se translate rigidement : la courbe à t=2 est identique à celle de t=0, juste décalée de 2 unités."}, {"formule": "Équation de Laplace : Δu=0", "imgPath": "assets/schemas/22-2-laplace.svg", "titre": "u(x,y)=x²-y², harmonique (Δu=0), vérifié", "caption": "u(x,y)=x²-y² vérifie Δu=∂²u/∂x²+∂²u/∂y²=2-2=0 (calculé directement) : c'est une fonction harmonique, solution de l'équation de Laplace."}], "23": [{"formule": "Équations d'Euler-Lagrange", "imgPath": "assets/schemas/23-0-euler-lagrange-calcul.svg", "titre": "Le plus court chemin est une droite, retrouvé", "caption": "Minimiser la longueur d'une courbe entre 2 points via Euler-Lagrange donne y'=constante, soit une droite : la ligne droite est bien le plus court chemin."}, {"formule": "Conditions de Karush-Kuhn-Tucker (KKT)", "imgPath": "assets/schemas/23-1-kkt.svg", "titre": "Optimum sous contrainte d'inégalité, trouvé en (1,1)", "caption": "Minimiser x²+y² sous x+y≥2 : par KKT, la contrainte est active (sinon on pourrait réduire encore), donnant x=y=1 (par symétrie), valeur minimale 2."}, {"formule": "Multiplicateurs de Lagrange", "imgPath": "assets/schemas/23-2-lagrange-optim.svg", "titre": "Même exemple que fiche 14, x=y=5", "caption": "Comme dans l'exemple de la fiche 14, maximiser xy sous x+y=10 donne par Lagrange x=y=5, un maximum de 25."}], "24": [{"formule": "Γ(x)=∫₀^∞ t^{x-1}e^{-t}dt", "imgPath": "assets/schemas/24-0-gamma.svg", "titre": "Γ(1) à Γ(5) calculées par intégration numérique", "caption": "Γ(x) est calculée ici par intégration numérique directe pour x=1 à 5, et retombe (à l'arrondi près) exactement sur (x-1)! : Γ(5)≈24=4!."}, {"formule": "Γ(n+1) = n!", "imgPath": "assets/schemas/24-1-gamma-factorielle.svg", "titre": "Γ(n+1)=n!, vérifié numériquement pour n=4,5", "caption": "Γ(5)≈24=4! et Γ(6)≈120=5! : la fonction Gamma calculée par intégration numérique généralise bien la factorielle."}, {"formule": "ζ(s)=Σ1/n^s", "imgPath": "assets/schemas/24-2-zeta.svg", "titre": "ζ(2) calculée sur 10000 termes, très proche de π²/6", "caption": "La somme des 10000 premiers termes de Σ1/n² donne 1.644834, extrêmement proche de π²/6≈1.644934 — le résultat de Bâle, retrouvé numériquement."}], "121": [{"formule": "Théorème de Bézout : au+bv=pgcd(a,b)", "imgPath": "assets/schemas/121-0-bezout.svg", "titre": "35×1+15×-2=5", "caption": "Pour a=35, b=15, l'algorithme d'Euclide étendu calcule u=1, v=-2 : 35×1+15×-2=5=pgcd(35,15)=5."}, {"formule": "Petit théorème de Fermat : a^p≡a (mod p)", "imgPath": "assets/schemas/121-1-fermat.svg", "titre": "aᵖ≡a (mod p) vérifié pour p=11", "caption": "Pour p=11 (premier), a^11 mod 11 = a pour chaque a testé ici (2 à 6) : le petit théorème de Fermat, vérifié numériquement."}, {"formule": "Théorème chinois des restes", "imgPath": "assets/schemas/121-2-crt.svg", "titre": "x=8, trouvée par recherche exhaustive puis vérifiée", "caption": "x≡2 (mod 3) et x≡3 (mod 5) ont une solution unique modulo 15 : x=8, vérifiable (8mod3=2, 8mod5=3)."}], "122": [{"formule": "Groupe (G,*)", "imgPath": "assets/schemas/122-0-groupe-Z5star.svg", "titre": "(ℤ/5ℤ)* sous la multiplication, calculé", "caption": "G=(ℤ/5ℤ)*={1,2,3,4} muni de la multiplication modulo 5 : la table complète, calculée ici, montre que c'est bien un groupe (chaque ligne/colonne contient une seule fois chaque élément)."}, {"formule": "Sous-groupe, morphisme de groupes", "imgPath": "assets/schemas/122-1-sousgroupe.svg", "titre": "H={1,4} est un sous-groupe de G, vérifié", "caption": "H={1,4}⊂G est un sous-groupe : 1×4=4∈H, 4×4=16mod5=1∈H — stable par l'opération et contient l'identité."}, {"formule": "Théorème de Lagrange : |H| divise |G|", "imgPath": "assets/schemas/122-2-lagrange.svg", "titre": "|H|=2 divise |G|=4, vérifié", "caption": "|G|=4 et |H|=2 : 2 divise bien 4, conformément au théorème de Lagrange, qui interdit tout autre ordre de sous-groupe (1, 2 ou 4 seulement)."}], "123": [{"formule": "Polynôme caractéristique : χ_A(λ)=det(A−λI)", "imgPath": "assets/schemas/123-0-polycar.svg", "titre": "Racines ≈5.37 et -0.37, calculées", "caption": "Pour A=[[4,2],[3,1]], χ_A(λ)=λ²-5λ-2, dont les racines (valeurs propres) calculées sont ≈5.372 et ≈-0.372."}, {"formule": "Théorème de Cayley-Hamilton", "imgPath": "assets/schemas/123-1-cayley-hamilton.svg", "titre": "χ_A(A)=0, vérifié numériquement", "caption": "En substituant A elle-même dans son polynôme caractéristique, χ_A(A)=A²-5A-2I=[[0, 0], [0, 0]], la matrice nulle — Cayley-Hamilton vérifié."}, {"formule": "Réduction de Jordan", "imgPath": "assets/schemas/123-2-jordan.svg", "titre": "Un bloc de Jordan concret, non diagonalisable", "caption": "Un bloc de Jordan comme [[3,1],[0,3]] a une seule valeur propre (3) mais n'est pas diagonalisable : le 1 au-dessus de la diagonale est la marque d'un vecteur propre généralisé."}], "124": [{"formule": "Procédé de Gram-Schmidt", "imgPath": "assets/schemas/124-0-gramschmidt.svg", "titre": "e1,e2 orthonormés, calculés à partir de v1,v2", "caption": "À partir de v1=(2,0), v2=(1,2), Gram-Schmidt calcule e1=(1,0), puis soustrait la projection sur e1 et normalise : e2≈(0.0 ; 1.0)."}, {"formule": "Matrices orthogonales : AᵀA=I", "imgPath": "assets/schemas/124-1-orthogonale.svg", "titre": "AᵀA=I, vérifié pour une rotation", "caption": "Pour une matrice de rotation de 35°, AᵀA calculée redonne exactement l'identité : c'est la caractérisation des matrices orthogonales."}, {"formule": "Théorème spectral (matrices symétriques réelles)", "imgPath": "assets/schemas/124-2-spectral.svg", "titre": "Valeurs propres réelles, calculées", "caption": "Pour A=[[4,2],[2,1]] (symétrique réelle), les valeurs propres calculées (5.0 et 0.0) sont réelles, comme le garantit le théorème spectral."}], "125": [{"formule": "Extension de corps K⊂L", "imgPath": "assets/schemas/125-0-extension.svg", "titre": "ℚ(√2), une extension de degré 2", "caption": "ℚ(√2)={a+b√2 : a,b∈ℚ} est une extension de ℚ de degré 2 : chaque élément se décompose de façon unique sur la base (1,√2)."}, {"formule": "Groupe de Galois Gal(L/K)", "imgPath": "assets/schemas/125-1-groupe-galois.svg", "titre": "2 éléments : identité et conjugaison, calculés", "caption": "Le groupe de Galois de ℚ(√2)/ℚ a exactement 2 éléments : l'identité, et l'automorphisme qui envoie √2 sur -√2 (l'autre racine du même polynôme minimal)."}, {"formule": "Théorème d'Abel-Ruffini", "imgPath": "assets/schemas/125-2-abel-ruffini.svg", "titre": "Le degré 5 change tout, résumé", "caption": "Toute équation de degré ≤4 se résout par radicaux (formules explicites) ; à partir du degré 5, ce n'est plus toujours possible, comme le montre Abel-Ruffini."}], "126": [{"formule": "Module libre", "imgPath": "assets/schemas/126-0-module-libre.svg", "titre": "ℤ² comme ℤ-module libre, décomposé", "caption": "ℤ² est un module libre sur ℤ : tout élément, comme (2,-1), se décompose de façon unique sur la base (1,0),(0,1), exactement comme un espace vectoriel mais sur ℤ."}, {"formule": "Théorème de structure des modules de type fini sur un anneau principal", "imgPath": "assets/schemas/126-1-structure.svg", "titre": "ℤ/12ℤ décomposé, calculé via 12=4×3", "caption": "Le théorème de structure décompose ℤ/12ℤ en ℤ/4ℤ×ℤ/3ℤ, puisque 4 et 3 sont premiers entre eux (12=4×3) : une illustration directe du théorème chinois des restes appliqué aux modules."}, {"formule": "Suite exacte courte", "imgPath": "assets/schemas/126-2-suite-exacte.svg", "titre": "0→A→B→C→0, la forme générale", "caption": "Une suite exacte courte 0→A→B→C→0 signifie que l'image de chaque flèche égale exactement le noyau de la suivante : A s'injecte dans B, dont le quotient par A est C."}], "127": [{"formule": "Caractère : χ(g)=Tr(ρ(g))", "imgPath": "assets/schemas/127-0-caractere.svg", "titre": "χ calculé pour 2 éléments de ℤ/3ℤ", "caption": "Pour la représentation par rotations de ℤ/3ℤ, χ(0)=Tr(I)=2, χ(1)=Tr(rotation 120°)=-1.0 — le caractère résume la trace de chaque matrice."}, {"formule": "Lemme de Schur", "imgPath": "assets/schemas/127-1-schur.svg", "titre": "La conclusion du lemme, résumée", "caption": "Le lemme de Schur affirme que tout endomorphisme qui commute avec une représentation irréductible est nécessairement une simple homothétie (multiplication par un scalaire)."}, {"formule": "Théorème de Maschke", "imgPath": "assets/schemas/127-2-maschke.svg", "titre": "La condition clé du théorème", "caption": "Le théorème de Maschke garantit que toute représentation d'un groupe fini se décompose en somme de représentations irréductibles, dès que la caractéristique du corps ne divise pas l'ordre du groupe."}], "128": [{"formule": "Réduction de Gauss", "imgPath": "assets/schemas/128-0-gauss.svg", "titre": "Q réduite en carrés, calculée", "caption": "Q(x,y)=2x²+4xy+2y² se réécrit 2(x+y)²+0×y² en complétant le carré : la réduction de Gauss élimine les termes croisés."}, {"formule": "Signature (p,q)", "imgPath": "assets/schemas/128-1-signature.svg", "titre": "Signature (1,0) pour cette forme dégénérée", "caption": "La réduction 2(x+y)²+0×y² a un coefficient positif et un nul : signature (1,0), une forme positive mais dégénérée (non définie)."}, {"formule": "Loi d'inertie de Sylvester", "imgPath": "assets/schemas/128-2-sylvester.svg", "titre": "Même signature quelle que soit la réduction", "caption": "Quelle que soit la façon de réduire Q en somme de carrés, le nombre de coefficients positifs et négatifs (la signature) reste le même : c'est la loi d'inertie de Sylvester."}], "129": [{"formule": "Produit tensoriel V⊗W", "imgPath": "assets/schemas/129-0-tenseur.svg", "titre": "dim(V⊗W)=dimV×dimW, calculée", "caption": "Pour dim V=2 et dim W=3, dim(V⊗W)=2×3=6 : la dimension du produit tensoriel se multiplie, contrairement à la somme directe qui s'additionne."}, {"formule": "Formes multilinéaires alternées", "imgPath": "assets/schemas/129-1-alternee.svg", "titre": "Antisymétrie ω(u,v)=-ω(v,u), la propriété clé", "caption": "Une forme alternée change de signe quand on échange deux arguments : ω(u,v)=-ω(v,u), et s'annule dès que deux arguments sont égaux."}, {"formule": "Déterminant comme forme n-linéaire alternée", "imgPath": "assets/schemas/129-2-det-nlineaire.svg", "titre": "det=1, calculé", "caption": "det([[3,1],[2,1]])=1 : échanger les deux colonnes donnerait det([[1,3],[1,2]])=-1, confirmant que le déterminant est bien une forme alternée."}], "130": [{"formule": "𝔽_q avec q=p^n", "imgPath": "assets/schemas/130-0-corps-fini.svg", "titre": "𝔽4, un corps fini à 4 éléments", "caption": "𝔽4 est un corps fini à q=2²=4 éléments, de caractéristique p=2 : c'est le plus petit corps fini qui ne soit pas ℤ/pℤ."}, {"formule": "Groupe multiplicatif 𝔽_q* cyclique", "imgPath": "assets/schemas/130-1-cyclique.svg", "titre": "3 engendre tout (ℤ/7ℤ)*, vérifié", "caption": "Les puissances de 3 modulo 7, calculées ici, parcourent {1,2,3,4,5,6} : 3 engendre tout le groupe (ℤ/7ℤ)*, qui est donc cyclique."}, {"formule": "Polynômes cyclotomiques", "imgPath": "assets/schemas/130-2-cyclotomique.svg", "titre": "Φ4(x)=x²+1, calculé", "caption": "Le polynôme cyclotomique Φ4(x)=x²+1 a pour racines i et -i, les racines 4-ièmes de l'unité qui ne sont pas racines d'un ordre inférieur."}], "131": [{"formule": "Théorème des zéros de Hilbert (Nullstellensatz)", "imgPath": "assets/schemas/131-0-nullstellensatz.svg", "titre": "I ↔ le cercle, la correspondance", "caption": "Le Nullstellensatz relie l'idéal I=(x²+y²-1) à la variété V(I) qu'il définit — ici le cercle unité — établissant une correspondance entre idéaux et ensembles de zéros."}, {"formule": "Idéaux premiers, idéaux maximaux", "imgPath": "assets/schemas/131-1-ideaux.svg", "titre": "(x) premier non maximal, (x,y) maximal", "caption": "(x) est premier (ℂ[x,y]/(x)≅ℂ[y] est intègre) mais pas maximal, car strictement inclus dans (x,y) qui, lui, est maximal (quotient = ℂ)."}, {"formule": "Variétés algébriques", "imgPath": "assets/schemas/131-2-variete.svg", "titre": "La courbe y=x³-x, une variété algébrique tracée", "caption": "y=x³-x est une variété algébrique (courbe plane), l'ensemble des zéros du polynôme y-x³+x, tracée ici avec ses 3 racines réelles visibles."}], "132": [{"formule": "Crochet de Lie [X,Y]", "imgPath": "assets/schemas/132-0-crochet.svg", "titre": "[X,Y]=[[1, 0], [0, -1]], calculé", "caption": "Pour X=[[0,1],[0,0]], Y=[[0,0],[1,0]], le crochet [X,Y]=XY-YX=[[1, 0], [0, -1]] est calculé directement par produit matriciel."}, {"formule": "Algèbre 𝔰𝔩(n)", "imgPath": "assets/schemas/132-1-sln.svg", "titre": "La base standard (H,X,Y) de 𝔰𝔩(2)", "caption": "𝔰𝔩(2) regroupe les matrices 2×2 de trace nulle ; H, X, Y forment sa base standard, avec des relations de crochet bien connues comme [H,X]=2X."}, {"formule": "Exponentielle de matrice exp(A)", "imgPath": "assets/schemas/132-2-expmatrice.svg", "titre": "exp(A) ≈ rotation de 1 radian, calculée", "caption": "Pour A=[[0,1],[-1,0]], exp(A) calculée par série (15 termes) donne ≈[[0.54,0.841],[-0.841,0.54]] — une rotation de 1 radian, cos(1)≈0,540."}], "133": [{"formule": "Fonction indicatrice d'Euler φ(n)", "imgPath": "assets/schemas/133-0-euler-phi.svg", "titre": "φ(n) calculée pour n=1 à 10", "caption": "φ(n) compte les entiers de 1 à n premiers avec n, calculé ici pour n=1 à 10 (par exemple φ(9)=6 : 1,2,4,5,7,8 sont premiers avec 9)."}, {"formule": "Théorème des nombres premiers : π(x)~x/ln(x)", "imgPath": "assets/schemas/133-1-pnt.svg", "titre": "π(x) et x/ln(x), les deux calculés et comparés", "caption": "π(x) (nombre de premiers ≤x, compté ici directement) se rapproche de x/ln(x) quand x grandit : à x=200, π(200)=46 contre x/ln(x)≈37,7 — déjà du même ordre."}, {"formule": "Fonction zêta de Riemann ζ(s)", "imgPath": "assets/schemas/133-2-zeta.svg", "titre": "ζ(2) recalculée, proche de π²/6", "caption": "ζ(2)=Σ1/n², calculée ici sur 5000 termes, donne 1.64473, très proche de la valeur exacte π²/6≈1.64493."}], "134": [{"formule": "RSA : c ≡ m^e (mod n)", "imgPath": "assets/schemas/134-0-rsa-avance.svg", "titre": "Nouvelle instance RSA, recalculée de bout en bout", "caption": "Avec p=7, q=13 (n=91), e=5, d=29 : m=8 chiffré donne c=8, déchiffré redonne bien 8=8."}, {"formule": "Logarithme discret", "imgPath": "assets/schemas/134-1-log-discret.svg", "titre": "x=7, trouvé par recherche exhaustive", "caption": "Pour g=5, p=23 : trouver x tel que 5ˣ≡17 (mod 23) nécessite ici une recherche exhaustive (x=7) — facile pour p petit, mais impraticable pour un p à 2000 bits, d'où sa sécurité."}, {"formule": "Courbes elliptiques : y²=x³+ax+b", "imgPath": "assets/schemas/134-2-courbe-elliptique.svg", "titre": "y²=x³-3x+3, calculée et tracée point par point", "caption": "La courbe elliptique y²=x³-3x+3 est tracée ici en calculant y=±√(x³-3x+3) pour chaque x où cette quantité est positive — la base géométrique de la cryptographie sur courbes elliptiques."}], "221": [{"formule": "Vecteur tangent unitaire", "imgPath": "assets/schemas/221-0-tangent.svg", "titre": "T calculé par dérivation numérique sur une ellipse", "caption": "Pour la courbe (2cos t, sin t), le vecteur tangent en t=50° est calculé par dérivation numérique puis normalisé : T pointe dans le sens du parcours."}, {"formule": "Courbure κ", "imgPath": "assets/schemas/221-1-courbure.svg", "titre": "κ≈0.4361", "caption": "La courbure κ=(x'y''-y'x'')/(x'²+y'²)^1,5, calculée numériquement en t=50° sur l'ellipse, vaut κ≈0.4361."}, {"formule": "Formules de Frenet", "imgPath": "assets/schemas/221-2-frenet.svg", "titre": "Le repère de Frenet (T,N), calculé et orthogonal", "caption": "Le repère de Frenet (T,N), calculé ici en un point de l'ellipse, est toujours orthonormé ; les formules de Frenet décrivent comment T et N tournent l'un vers l'autre selon la courbure κ."}], "222": [{"formule": "Première forme fondamentale", "imgPath": "assets/schemas/222-0-forme-fondamentale.svg", "titre": "Coefficients E,F,G pour une sphère, donnés", "caption": "La première forme fondamentale (E,F,G) mesure les longueurs sur la surface ; pour une sphère de rayon R, E=R², F=0, G=R²sin²φ, calculés à partir de la paramétrisation."}, {"formule": "Courbure de Gauss K", "imgPath": "assets/schemas/222-1-courbure-gauss.svg", "titre": "K=1/R²=0.1111 pour la sphère", "caption": "La sphère de rayon 3 a une courbure de Gauss constante K=1/R²=0.1111 > 0 ; le plan a K=0 ; une selle a K<0."}, {"formule": "Theorema Egregium", "imgPath": "assets/schemas/222-2-egregium.svg", "titre": "Pourquoi les cartes du monde déforment toujours", "caption": "Le Theorema Egregium de Gauss montre que K est un invariant intrinsèque (calculable sans sortir de la surface) : c'est pourquoi aucune carte plane ne peut représenter la Terre sans déformation."}], "223": [{"formule": "Cartes et atlas", "imgPath": "assets/schemas/223-0-carte.svg", "titre": "Un morceau d'ellipse, identifié à un intervalle", "caption": "Une carte identifie un petit morceau de la courbe (en orange) à un intervalle de ℝ ; l'atlas est la collection de toutes les cartes nécessaires pour couvrir toute la courbe."}, {"formule": "Espace tangent TₚM", "imgPath": "assets/schemas/223-1-espace-tangent.svg", "titre": "La droite tangente en p, calculée par dérivation", "caption": "L'espace tangent TₚM en un point p d'une courbe (ici l'ellipse) est la droite (calculée par dérivation) qui approche le mieux la courbe près de p."}, {"formule": "Théorème de Stokes généralisé", "imgPath": "assets/schemas/223-2-stokes.svg", "titre": "Green (cas 2D de Stokes) vérifié numériquement", "caption": "Pour P=-y, Q=x sur le carré unité, la circulation sur le bord calculée (2.0) retombe bien sur ∬(∂Q/∂x-∂P/∂y)dA=2×aire=2 : le théorème de Stokes (ici Green) vérifié numériquement."}], "224": [{"formule": "Groupe fondamental π₁(X)", "imgPath": "assets/schemas/224-0-groupe-fondamental.svg", "titre": "π1 du cercle = ℤ, compté par le nombre de tours", "caption": "π1(S¹)=ℤ : chaque lacet sur le cercle est classé par son nombre de tours (entier, positif ou négatif) ; sur un disque plein, tout lacet se contracte, π1 est trivial."}, {"formule": "Caractéristique d'Euler : V−E+F=2", "imgPath": "assets/schemas/224-1-euler-cube.svg", "titre": "8-12+6=2, vérifié sur un cube", "caption": "Pour un cube : V=8 sommets, E=12 arêtes, F=6 faces, donc V-E+F=8-12+6=2 — la caractéristique d'Euler d'une sphère topologique, vérifiée par comptage direct."}, {"formule": "Homologie singulière", "imgPath": "assets/schemas/224-2-homologie.svg", "titre": "Un triangle plein (3 sommets, 3 arêtes) : H1=0", "caption": "Pour ce triangle plein (bord d'une face), le cycle v0→v1→v2→v0 borde la face intérieure : il est \"trivial\" en homologie, contrairement à un cercle qui ne borde rien."}], "225": [{"formule": "Connexion de Levi-Civita", "imgPath": "assets/schemas/225-0-levicivita.svg", "titre": "Les 2 propriétés qui la caractérisent uniquement", "caption": "La connexion de Levi-Civita ∇ est l'unique connexion sans torsion qui préserve la métrique le long du transport parallèle — ces 2 conditions la déterminent complètement."}, {"formule": "Tenseur de courbure de Riemann", "imgPath": "assets/schemas/225-1-riemann-tenseur.svg", "titre": "Le signe de la courbure selon la surface, résumé", "caption": "Le tenseur de courbure de Riemann généralise la courbure de Gauss ; son signe (positif pour une sphère, négatif pour une selle) dit si les géodésiques voisines convergent ou divergent."}, {"formule": "Équation de la géodésique", "imgPath": "assets/schemas/225-2-geodesique.svg", "titre": "Un grand cercle sur la sphère, la géodésique", "caption": "Sur une sphère, les géodésiques (chemins localement les plus courts, solutions de l'équation géodésique) sont les grands cercles, comme celui tracé ici."}], "226": [{"formule": "Forme symplectique ω", "imgPath": "assets/schemas/226-0-symplectique.svg", "titre": "Aire=2 dans l'espace des phases (q,p)", "caption": "La forme symplectique ω=dq∧dp mesure une aire orientée dans l'espace des phases : ici, le rectangle a une aire ω=2, calculée directement."}, {"formule": "Crochet de Poisson {f,g}", "imgPath": "assets/schemas/226-1-poisson.svg", "titre": "{f,g}≈7.0, calculé", "caption": "Pour f(q,p)=q²+p, g(q,p)=qp, le crochet de Poisson calculé par différences finies en (2,1) vaut ≈7.0."}, {"formule": "Théorème de Liouville (conservation du volume)", "imgPath": "assets/schemas/226-2-liouville.svg", "titre": "Le rectangle déformé garde la même aire, vérifié", "caption": "Le cisaillement (q,p)→(q+p,p), une évolution hamiltonienne typique, déforme le rectangle mais conserve exactement son aire : le théorème de Liouville, vérifié par le calcul."}], "227": [{"formule": "Courbes planes et théorème de Bézout", "imgPath": "assets/schemas/227-0-bezout-courbes.svg", "titre": "1×2=2 points d'intersection, calculés", "caption": "Une droite (degré 1) et un cercle (degré 2) se coupent en au plus 1×2=2 points, calculés ici en résolvant le système — conforme au théorème de Bézout."}, {"formule": "Diviseurs sur une courbe", "imgPath": "assets/schemas/227-1-diviseurs.svg", "titre": "deg(D)=4, calculé par somme des multiplicités", "caption": "Un diviseur D=3P+2Q-R associe des multiplicités (positives ou négatives) à des points de la courbe ; son degré, ici 3+2-1=4, se calcule en sommant ces coefficients."}, {"formule": "Théorème de Riemann-Roch", "imgPath": "assets/schemas/227-2-riemannroch.svg", "titre": "Un exemple numérique pour g=2", "caption": "Pour une courbe de genre g=2 et un diviseur de degré 5, Riemann-Roch garantit dim L(D) ≥ 5-2+1=4 : un contrôle explicite sur l'espace des fonctions."}], "228": [{"formule": "Espace projectif ℙⁿ", "imgPath": "assets/schemas/228-0-espace-projectif.svg", "titre": "Un point projectif, plusieurs représentants", "caption": "Dans ℙ², le point [1:2:1] représente toute la droite vectorielle {(λ,2λ,λ) : λ≠0} : [1:2:1] et [2:4:2] désignent le même point projectif."}, {"formule": "Coordonnées homogènes", "imgPath": "assets/schemas/228-1-coord-homogenes.svg", "titre": "Passage affine → homogène, direct", "caption": "Le point affine (3,4) devient [3:4:1] en coordonnées homogènes ; les points à l'infini correspondent à une dernière coordonnée nulle, [x:y:0]."}, {"formule": "Homographies", "imgPath": "assets/schemas/228-2-homographie.svg", "titre": "3 points transformés, calculés", "caption": "Une homographie (transformation projective) est calculée ici explicitement sur 3 points : elle envoie droites sur droites, sans nécessairement préserver les distances."}], "229": [{"formule": "Opérateur de Laplace-de Rham", "imgPath": "assets/schemas/229-0-laplace-derham.svg", "titre": "Δ défini à partir de d et son adjoint", "caption": "L'opérateur de Laplace-de Rham Δ=dd*+d*d généralise le laplacien usuel aux formes différentielles ; ses formes harmoniques (Δω=0) représentent chaque classe de cohomologie."}, {"formule": "Décomposition de Hodge", "imgPath": "assets/schemas/229-1-hodge.svg", "titre": "La décomposition en 3 sous-espaces orthogonaux", "caption": "La décomposition de Hodge sépare toute forme en une partie exacte, une partie harmonique, et une partie co-exacte : trois sous-espaces mutuellement orthogonaux."}, {"formule": "Théorème de de Rham", "imgPath": "assets/schemas/229-2-derham.svg", "titre": "L'isomorphisme central du théorème", "caption": "Le théorème de de Rham identifie la cohomologie de de Rham (définie par le calcul différentiel) à la cohomologie singulière (définie topologiquement) : deux points de vue, un seul invariant."}], "230": [{"formule": "Modèle du disque de Poincaré", "imgPath": "assets/schemas/230-0-poincare.svg", "titre": "2 \"droites\" hyperboliques tracées (un diamètre, un arc orthogonal)", "caption": "Dans le disque de Poincaré, les droites hyperboliques sont soit des diamètres, soit des arcs de cercle orthogonaux au bord — deux exemples calculés et tracés ici."}, {"formule": "Espaces CAT(0)", "imgPath": "assets/schemas/230-1-cat0.svg", "titre": "La comparaison des triangles, résumée", "caption": "Un espace CAT(0) est un espace où les triangles géodésiques sont toujours au moins aussi \"fins\" que leur comparaison euclidienne : cela généralise la courbure négative ou nulle."}, {"formule": "Bord à l'infini", "imgPath": "assets/schemas/230-2-bord-infini.svg", "titre": "Le cercle unité comme bord, pour le disque", "caption": "Le bord à l'infini d'un espace hyperbolique regroupe les directions vers lesquelles partent les géodésiques ; pour le disque de Poincaré, c'est exactement le cercle-frontière représenté ci-dessus."}], "231": [{"formule": "Fibré vectoriel E→M", "imgPath": "assets/schemas/231-0-fibre.svg", "titre": "Un fibré en droites schématisé, une fibre par point", "caption": "Un fibré vectoriel E→M attache un espace vectoriel (ici une droite) à chaque point de la base M, de façon compatible localement — ici schématisé pour 5 points de M."}, {"formule": "Connexion et courbure d'un fibré", "imgPath": "assets/schemas/231-1-connexion-courbure.svg", "titre": "La courbure comme obstruction à la platitude", "caption": "Une connexion ∇ sur le fibré définit une notion de transport parallèle ; sa courbure F mesure l'écart au cas plat — nulle seulement si le fibré est localement trivial."}, {"formule": "Classes de Chern", "imgPath": "assets/schemas/231-2-chern.svg", "titre": "c1 distingue des fibrés non isomorphes", "caption": "La première classe de Chern c1 (un entier) distingue les fibrés en droites sur la sphère : c1=0 pour le fibré trivial, c1=-1 pour le fibré tautologique — ils ne sont pas isomorphes."}], "232": [{"formule": "Distance de Wasserstein", "imgPath": "assets/schemas/232-0-wasserstein.svg", "titre": "W1=2.0, calculée par transport optimal", "caption": "Pour déplacer la masse de p (en 0 et 1) vers q (en 2 et 3), le transport optimal coûte W1=2.0 — le coût minimal total, calculé explicitement."}, {"formule": "Dualité de Kantorovich", "imgPath": "assets/schemas/232-1-dualite.svg", "titre": "Les deux formulations équivalentes", "caption": "La dualité de Kantorovich montre que le coût minimal de transport (primal) égale un problème de maximisation sur des fonctions 1-lipschitziennes (dual) — les deux calculs donnent la même valeur W1."}, {"formule": "Inégalité isopérimétrique", "imgPath": "assets/schemas/232-2-isoperimetrique.svg", "titre": "À périmètre égal, le cercle a l'aire la plus grande, vérifié", "caption": "Pour un même périmètre ≈12.566, le cercle (aire 12.566) bat le carré (aire 9.869) : conformément à l'inégalité isopérimétrique, le cercle maximise l'aire à périmètre fixé."}], "312": [{"formule": "Densité de probabilité f(x)", "imgPath": "assets/schemas/312-0-densite.svg", "titre": "Densité exponentielle λ=1,5, tracée", "caption": "f(x)=λe^(-λx) pour x≥0 (λ=1,5) est calculée et tracée : l'aire totale sous la courbe vaut exactement 1."}, {"formule": "Fonction de répartition F(x)=P(X≤x)", "imgPath": "assets/schemas/312-1-fdr.svg", "titre": "F(x), calculée par intégration de f", "caption": "F(x)=∫₀ˣf(t)dt=1-e^(-1,5x), calculée en intégrant la densité ci-dessus : elle croît de 0 à 1."}, {"formule": "E[X]=∫x f(x)dx", "imgPath": "assets/schemas/312-2-esperance.svg", "titre": "E[X]=0.667", "caption": "Pour la loi exponentielle de paramètre λ=1,5, E[X]=∫x f(x)dx=1/λ=0.667, calculée directement."}], "313": [{"formule": "√n (X̄ₙ−μ)/σ → N(0,1)", "imgPath": "assets/schemas/313-0-tcl.svg", "titre": "500 moyennes d'échantillon (n=30), simulées : déjà en cloche", "caption": "500 moyennes d'échantillons de taille 30 (loi uniforme), simulées et regroupées en histogramme, dessinent déjà la forme d'une cloche : le TCL en action."}, {"formule": "Loi des grands nombres", "imgPath": "assets/schemas/313-1-lgn.svg", "titre": "La moyenne empirique se stabilise vers 0,5, simulée", "caption": "La moyenne cumulée de tirages uniformes sur [0,1], simulée et affichée pour n=1 à 100, se rapproche de plus en plus de l'espérance théorique 0,5."}, {"formule": "Théorème de Slutsky", "imgPath": "assets/schemas/313-2-slutsky.svg", "titre": "La règle de combinaison de Slutsky, résumée", "caption": "Le théorème de Slutsky permet de combiner une convergence en loi (Xₙ→X) avec une convergence en probabilité vers une constante (Yₙ→c) : Xₙ+Yₙ converge en loi vers X+c."}], "314": [{"formule": "Matrice de transition P", "imgPath": "assets/schemas/314-0-transition.svg", "titre": "Une chaîne météo à 2 états, la matrice P", "caption": "P donne la probabilité de passer d'un état à l'autre : partant d'un jour de soleil, 70% de chance de rester au soleil, 30% de passer à la pluie."}, {"formule": "Distribution stationnaire : πP = π", "imgPath": "assets/schemas/314-1-stationnaire.svg", "titre": "π calculée en résolvant πP=π", "caption": "En résolvant πP=π avec π1+π2=1, on trouve π(Soleil)≈0.571, π(Pluie)≈0.429 : la proportion de jours de chaque type sur le long terme."}, {"formule": "Équation de Chapman-Kolmogorov", "imgPath": "assets/schemas/314-2-chapmankolmogorov.svg", "titre": "P² calculée = P×P", "caption": "P² (2 étapes) se calcule directement comme le produit matriciel P×P : P²(Soleil→Soleil)≈0.61, conforme à l'équation de Chapman-Kolmogorov."}], "315": [{"formule": "E[Xₙ₊₁|Fₙ]=Xₙ", "imgPath": "assets/schemas/315-0-martingale.svg", "titre": "Une marche aléatoire simulée : martingale", "caption": "Pour une marche aléatoire simple (±1 équiprobable), E[Xₙ₊₁|Fₙ]=Xₙ+0=Xₙ : c'est une martingale, simulée ici sur 30 pas."}, {"formule": "Théorème d'arrêt de Doob", "imgPath": "assets/schemas/315-1-arret-doob.svg", "titre": "Simulation : la marche atteint 5, T calculé", "caption": "Dans cette simulation, la marche aléatoire atteint le niveau 5 au temps T=>200 : le théorème d'arrêt de Doob garantit E[X_T]=X_0=0 sous conditions, ou ici directement 5 si arrêté à ce niveau."}, {"formule": "Inégalité de Doob", "imgPath": "assets/schemas/315-2-doob-inegalite.svg", "titre": "Le maximum observé sur la simulation", "caption": "Sur cette simulation, max|Xₖ|=5 ; l'inégalité de Doob borne la probabilité qu'une martingale s'éloigne beaucoup, à partir de sa variance finale."}], "316": [{"formule": "Formule d'Itô", "imgPath": "assets/schemas/316-0-ito.svg", "titre": "d(Wₜ²) a un terme dt en plus, expliqué", "caption": "La formule d'Itô donne d(Wₜ²)=2WₜdWₜ+dt, avec un terme +dt qui n'existerait pas en calcul classique — conséquence de dWₜ²=dt, la règle de base du calcul stochastique."}, {"formule": "dXₜ=μdt+σdWₜ", "imgPath": "assets/schemas/316-1-brownien-simule.svg", "titre": "Une trajectoire brownienne simulée (μ=0,σ=1)", "caption": "Une trajectoire de Wₜ (μ=0, σ=1) est simulée pas à pas par petits incréments gaussiens indépendants dWₜ, échantillonnée ici à 5 instants."}, {"formule": "Propriété de Markov du mouvement brownien", "imgPath": "assets/schemas/316-2-markov-brownien.svg", "titre": "La mémoire courte du mouvement brownien, résumée", "caption": "Le mouvement brownien est markovien : connaître sa trajectoire passée n'apporte rien de plus que connaître sa position actuelle pour prédire son futur."}], "317": [{"formule": "EDS : dXₜ=b(Xₜ)dt+σ(Xₜ)dWₜ", "imgPath": "assets/schemas/317-0-eds-simulee.svg", "titre": "Processus d'Ornstein-Uhlenbeck simulé, revenant vers 0", "caption": "dXₜ=-θXₜdt+σdWₜ (θ=1, σ=0,5) est simulée pas à pas : partant de X0=2, la trajectoire est attirée vers 0 malgré le bruit aléatoire."}, {"formule": "Théorème d'existence et unicité (Lipschitz)", "imgPath": "assets/schemas/317-1-lipschitz.svg", "titre": "La condition suffisante, énoncée", "caption": "Comme pour les équations différentielles ordinaires, une condition de Lipschitz sur les coefficients b et σ garantit l'existence et l'unicité de la solution de l'EDS."}, {"formule": "Formule de Feynman-Kac", "imgPath": "assets/schemas/317-2-feynmankac.svg", "titre": "Le pont entre EDS et EDP, résumé", "caption": "La formule de Feynman-Kac relie la solution d'une équation aux dérivées partielles à l'espérance d'une fonctionnelle du processus stochastique associé — un pont entre EDS et EDP."}], "318": [{"formule": "Estimateur du maximum de vraisemblance", "imgPath": "assets/schemas/318-0-mle.svg", "titre": "λ̂=1.885 (vraie valeur λ=2)", "caption": "Pour un échantillon simulé de loi exponentielle (λ=2 vrai), l'estimateur du maximum de vraisemblance λ̂=1/x̄≈1.885, calculé sur 50 observations."}, {"formule": "Borne de Cramér-Rao", "imgPath": "assets/schemas/318-1-cramerrao.svg", "titre": "La variance minimale théorique, calculée", "caption": "La borne de Cramér-Rao pour cet estimateur vaut λ²/n≈0.071065 : aucun estimateur sans biais ne peut avoir une variance plus petite."}, {"formule": "Intervalle de confiance", "imgPath": "assets/schemas/318-2-ic.svg", "titre": "IC calculé sur l'échantillon simulé", "caption": "Avec x̄=0.53 et n=50, l'intervalle de confiance à 95% pour la moyenne est [0.403 ; 0.657], calculé directement."}], "319": [{"formule": "Erreur de première espèce α", "imgPath": "assets/schemas/319-0-alpha.svg", "titre": "α = aire dans la zone de rejet (au-delà de 1,96)", "caption": "L'erreur de première espèce α (souvent 5%) est l'aire sous la courbe N(0,1) au-delà du seuil critique (±1,96) : la probabilité de rejeter H0 alors qu'elle est vraie."}, {"formule": "Lemme de Neyman-Pearson", "imgPath": "assets/schemas/319-1-neymanpearson.svg", "titre": "Rapport=4.0, calculé", "caption": "Le rapport de vraisemblance L(H1)/L(H0)=4.0, calculé ici pour une observation donnée, est la statistique optimale selon Neyman-Pearson pour décider entre H0 et H1."}, {"formule": "Test du χ²", "imgPath": "assets/schemas/319-2-chi2.svg", "titre": "χ²=2.9, calculée", "caption": "χ²=Σ(observé-attendu)²/attendu, calculée ici sur 4 catégories, vaut 2.9 : à comparer au seuil critique de la loi du χ² à 3 degrés de liberté."}], "320": [{"formule": "Inégalité de Markov", "imgPath": "assets/schemas/320-0-markov.svg", "titre": "Borne=0.3333", "caption": "Pour une variable positive d'espérance E[X]=5, l'inégalité de Markov borne P(X≥15) ≤ 5/15=0.3333, calculée sans connaître toute la loi."}, {"formule": "Inégalité de Bienaymé-Tchebychev", "imgPath": "assets/schemas/320-1-tchebychev.svg", "titre": "Borne=0.1111", "caption": "Avec Var(X)=4, Tchebychev borne P(|X-E[X]|≥6) ≤ 4/36≈0.1111 : une borne plus fine que Markov car elle utilise la variance."}, {"formule": "Théorème de Cramér (grandes déviations)", "imgPath": "assets/schemas/320-2-cramer.svg", "titre": "La fonction de taux I(x), calculée et tracée", "caption": "Le théorème de Cramér affirme que P(X̄ₙ≈x) décroît en e^(-nI(x)) pour une fonction de taux I(x) calculable, ici tracée : I(x)=0 exactement à la moyenne, croissante ailleurs."}], "321": [{"formule": "P(N(t)=k)=e^{-λt}(λt)^k/k!", "imgPath": "assets/schemas/321-0-poisson-pmf.svg", "titre": "P(N=k) calculée pour λt=3", "caption": "Pour λt=3 (3 événements attendus en moyenne), P(N(t)=k) est calculée pour chaque k=0..9 : le pic se situe autour de k=2-3, cohérent avec la moyenne."}, {"formule": "Temps d'attente exponentiels", "imgPath": "assets/schemas/321-1-attente.svg", "titre": "La densité du temps entre 2 événements, tracée", "caption": "Dans un processus de Poisson de taux λ=3, le temps entre deux événements consécutifs suit une loi exponentielle de paramètre λ, dont la densité est tracée ici."}, {"formule": "Processus de naissance et de mort", "imgPath": "assets/schemas/321-2-naissance-mort.svg", "titre": "États 0,1,2,3 avec taux λ (naissance) et μ (mort)", "caption": "Un processus de naissance et de mort passe d'un état à l'état voisin, avec un taux λ vers le haut (naissance) et μ vers le bas (mort) — schématisé ici pour 4 états."}], "322": [{"formule": "Formule de Black-Scholes", "imgPath": "assets/schemas/322-0-blackscholes.svg", "titre": "Prix=8.021€, calculé", "caption": "Pour S0=100, K=105, r=5%, σ=20%, T=1 an : la formule de Black-Scholes calculée donne un prix de call ≈8.021€."}, {"formule": "Portefeuille auto-financé", "imgPath": "assets/schemas/322-1-portefeuille.svg", "titre": "Aucun apport ni retrait entre t=0 et t=1", "caption": "Un portefeuille auto-financé peut réajuster ses parts (actif risqué / sans risque) mais sans jamais ajouter ou retirer d'argent : sa valeur totale évolue seulement par les gains/pertes de marché."}, {"formule": "Mesure de probabilité risque-neutre", "imgPath": "assets/schemas/322-2-risque-neutre.svg", "titre": "P vs Q, la différence clé", "caption": "Sous la mesure risque-neutre Q (différente de la mesure réelle P), tous les actifs ont un rendement moyen égal au taux sans risque r, ce qui simplifie le calcul du prix des options."}], "323": [{"formule": "Modèle ARMA(p,q)", "imgPath": "assets/schemas/323-0-arma-simule.svg", "titre": "Une série ARMA(1,0) simulée : Xt=0,6Xt-1+εt", "caption": "Une série AR(1) avec Xₜ=0,6Xₜ₋₁+εₜ (εₜ bruit gaussien) est simulée pas à pas : la dépendance au passé (coefficient 0,6) crée une certaine inertie."}, {"formule": "Modèle GARCH", "imgPath": "assets/schemas/323-1-garch.svg", "titre": "La volatilité simulée, qui varie dans le temps", "caption": "Contrairement à un bruit blanc classique, un modèle GARCH laisse la volatilité elle-même évoluer dans le temps, simulée ici en fonction des chocs passés."}, {"formule": "Théorème de Wold", "imgPath": "assets/schemas/323-2-wold.svg", "titre": "La décomposition universelle, résumée", "caption": "Le théorème de Wold garantit que toute série temporelle stationnaire se décompose en une partie prévisible et une combinaison linéaire infinie de bruits blancs passés (MA(∞))."}], "324": [{"formule": "Arrangements : A(n,k)=n!/(n-k)!", "imgPath": "assets/schemas/324-0-arrangements.svg", "titre": "A(6,k) calculés pour k=1..4", "caption": "A(6,k)=6!/(6-k)! est calculé ici pour k=1 à 4 : par exemple A(6,3)=6×5×4=120 façons ordonnées de choisir 3 éléments parmi 6."}, {"formule": "Combinaisons : C(n,k)=n!/(k!(n-k)!)", "imgPath": "assets/schemas/324-1-combinaisons.svg", "titre": "C(6,k) calculés pour k=0..6, symétrique", "caption": "C(6,k), calculé pour chaque k=0 à 6, est symétrique (C(6,2)=C(6,4)=15) et maximal en son centre (C(6,3)=20)."}, {"formule": "Binôme de Newton : (x+y)ⁿ=Σ C(n,k) xⁿ⁻ᵏyᵏ", "imgPath": "assets/schemas/324-2-binome.svg", "titre": "(1+1)⁴=Σ C(4,k)=16=16, vérifié", "caption": "Pour x=y=1, n=4 : (1+1)⁴=16, et Σ C(4,k) calculée directement (1+4+6+4+1) donne aussi 16 — le binôme de Newton vérifié numériquement."}], "419": [{"formule": "Lagrangien L=T−V", "imgPath": "assets/schemas/419-0-lagrangien-calcul.svg", "titre": "L=-0.2 J", "caption": "Pour m=1,5 kg, k=4 N/m, v=1,2 m/s, x=0,8 m : L=T-V=1.08-1.2800000000000002=-0.2 J."}, {"formule": "Équations d'Euler-Lagrange", "imgPath": "assets/schemas/419-1-el-verif.svg", "titre": "ma=-kx retrouvée, vérifiée numériquement", "caption": "En appliquant d/dt(∂L/∂v)=∂L/∂x à L=½mv²-½kx², on retrouve exactement ma=-kx, l'équation du ressort — vérifié numériquement ici."}, {"formule": "Hamiltonien H=Σpq̇−L", "imgPath": "assets/schemas/419-2-hamiltonien.svg", "titre": "H=2.36 J", "caption": "H=pv̇-L=1.8×1.2--0.2=2.36 J : pour ce système, H=T+V, l'énergie totale, calculée deux façons différentes."}], "420": [{"formule": "Équation de Schrödinger : iℏ∂ψ/∂t=Ĥψ", "imgPath": "assets/schemas/420-0-schrodinger.svg", "titre": "Les 2 premiers états stationnaires d'une particule dans une boîte, calculés", "caption": "Pour une particule dans une boîte [0,1], résoudre l'équation de Schrödinger donne des états stationnaires ψₙ(x)=√(2/L)sin(nπx/L), calculés et tracés ici pour n=1,2."}, {"formule": "Relation de commutation [x̂,p̂]=iℏ", "imgPath": "assets/schemas/420-1-commutation.svg", "titre": "[x,∂x]ψ=-ψ, vérifié numériquement (à iℏ près)", "caption": "Le commutateur [x,∂/∂x]ψ, calculé numériquement en x=0,7, vaut -0.6442, retombant sur -ψ(0,7)=-0.6442 : la relation [x̂,p̂]=iℏ vient de ce calcul (avec p̂=-iℏ∂/∂x)."}, {"formule": "Principe d'incertitude de Heisenberg", "imgPath": "assets/schemas/420-2-heisenberg.svg", "titre": "σₓσₚ≥1/2 (ℏ=1), calculé à l'égalité", "caption": "Pour un paquet d'onde gaussien avec σₓ=0,5, le principe d'incertitude impose σₚ≥1/(2σₓ)=1.0 (avec ℏ=1) : le produit σₓσₚ=0.5 atteint ici le minimum théorique 0,5."}], "421": [{"formule": "Transformation de Lorentz", "imgPath": "assets/schemas/421-0-lorentz-calcul.svg", "titre": "γ=1.25, calculée pour v=0,6c", "caption": "Pour v=0,6c, γ=1.25 ; un événement (t=10,x=3) dans un référentiel devient (t'=10.25,x'=-3.75) dans l'autre, calculé par la transformation de Lorentz."}, {"formule": "E=mc²", "imgPath": "assets/schemas/421-1-emc2.svg", "titre": "E=9.00e+13 J pour 1 gramme", "caption": "Pour m=1 gramme (0,001 kg), E=mc²=0,001×(3×10⁸)²≈9.00e+13 J — l'équivalent énergétique d'une masse minuscule, calculé directement."}, {"formule": "Intervalle d'espace-temps : ds² = c²dt² − dx²", "imgPath": "assets/schemas/421-2-intervalle.svg", "titre": "Invariance vérifiée numériquement", "caption": "L'intervalle ds²=c²t²-x²=91, recalculé après transformation de Lorentz (t',x'), redonne exactement 91.0 : c'est un invariant relativiste."}], "422": [{"formule": "Équations d'Einstein : Gμν=8πG/c⁴ Tμν", "imgPath": "assets/schemas/422-0-einstein-eq.svg", "titre": "La géométrie dictée par la matière, résumé", "caption": "Les équations d'Einstein relient la courbure de l'espace-temps (Gμν, membre géométrique) à la matière et l'énergie qu'il contient (Tμν) : \"la matière dit à l'espace comment se courber\"."}, {"formule": "Métrique de Schwarzschild", "imgPath": "assets/schemas/422-1-schwarzschild.svg", "titre": "Rayon de Schwarzschild du Soleil ≈2.95 km, calculé", "caption": "Le rayon de Schwarzschild Rs=2GM/c², calculé pour la masse du Soleil, vaut ≈2.95 km : s'il était comprimé sous ce rayon, le Soleil deviendrait un trou noir."}, {"formule": "Tenseur de courbure de Ricci", "imgPath": "assets/schemas/422-2-ricci.svg", "titre": "L'effet du signe de Ricci, résumé", "caption": "Le tenseur de Ricci mesure comment un petit volume de matière-test se contracte ou se dilate en tombant librement : positif il se resserre, négatif il s'étale."}], "423": [{"formule": "Équations de Maxwell", "imgPath": "assets/schemas/423-0-maxwell4.svg", "titre": "Les 4 équations de Maxwell, listées", "caption": "Les 4 équations de Maxwell gouvernent complètement les champs électrique et magnétique et leurs interactions mutuelles."}, {"formule": "Force de Lorentz : F=q(E+v×B)", "imgPath": "assets/schemas/423-1-lorentz-force.svg", "titre": "F=(22, 0, 0), calculée par produit vectoriel", "caption": "Pour q=2, E=(3,0,0), v=(0,4,0), B=(0,0,2) : v×B=(8, 0, 0) (calculé), donc F=q(E+v×B)=(22, 0, 0)."}, {"formule": "Équation d'onde électromagnétique", "imgPath": "assets/schemas/423-2-onde-em.svg", "titre": "Solution sinusoïdale de l'équation d'onde, tracée", "caption": "Les équations de Maxwell dans le vide impliquent une équation d'onde pour E et B ; une solution simple, sinusoïdale, est tracée ici."}], "424": [{"formule": "Équations de Navier-Stokes", "imgPath": "assets/schemas/424-0-navierstokes.svg", "titre": "L'équation complète, rappelée", "caption": "Les équations de Navier-Stokes décrivent l'évolution de la vitesse v d'un fluide visqueux, combinant inertie, pression, viscosité et forces extérieures."}, {"formule": "Équation de continuité", "imgPath": "assets/schemas/424-1-continuite.svg", "titre": "v2=5.0 m/s, calculée", "caption": "Pour A1=0,05 m², v1=2 m/s et A2=0,02 m² : la conservation du débit A1v1=A2v2 impose v2=5.0 m/s, calculée directement."}, {"formule": "Nombre de Reynolds", "imgPath": "assets/schemas/424-2-reynolds.svg", "titre": "Re=100000, calculé", "caption": "Re=ρvD/μ=1000×2×0,05/0,001=100000 : très supérieur à 4000, l'écoulement est turbulent."}], "425": [{"formule": "Entropie de Boltzmann : S=k ln(Ω)", "imgPath": "assets/schemas/425-0-entropie-boltzmann.svg", "titre": "S≈9.53e-23 J/K, calculée", "caption": "Pour Ω=1000 microétats accessibles, S=k×ln(1000)≈9.53e-23 J/K, calculée directement à partir du comptage des états."}, {"formule": "Fonction de partition Z", "imgPath": "assets/schemas/425-1-partition.svg", "titre": "Z=1.6065, calculée pour un système à 2 niveaux", "caption": "Pour un système à 2 niveaux d'énergie (E0=0, E1=1, kT=2), Z=Σe^(-Eᵢ/kT)=1.6065, calculée en sommant sur les 2 états."}, {"formule": "Distribution de Boltzmann", "imgPath": "assets/schemas/425-2-distribution-boltzmann.svg", "titre": "P(E0)=0.622, P(E1)=0.378, calculées", "caption": "La distribution de Boltzmann P(Eᵢ)=e^(-Eᵢ/kT)/Z donne ici P(E0)=0.622 et P(E1)=0.378 : l'état de plus basse énergie est plus probable."}], "426": [{"formule": "Équations de Yang-Mills", "imgPath": "assets/schemas/426-0-yangmills.svg", "titre": "La généralisation de Maxwell, rappelée", "caption": "Les équations de Yang-Mills généralisent celles de Maxwell à des groupes de jauge non abéliens : F devient une courbure matricielle plutôt qu'un simple champ scalaire."}, {"formule": "Groupe de jauge SU(N)", "imgPath": "assets/schemas/426-1-sun.svg", "titre": "dim=N²-1, calculée pour N=2,3", "caption": "La dimension du groupe SU(N) est N²-1, calculée ici pour N=2 (3 générateurs, comme le spin) et N=3 (8 générateurs, les gluons de la chromodynamique quantique)."}, {"formule": "Connexion sur un fibré principal", "imgPath": "assets/schemas/426-2-connexion-fibre.svg", "titre": "F=dA+A∧A, la formule générale", "caption": "Une connexion A sur un fibré principal généralise le potentiel électromagnétique ; sa courbure F=dA+A∧A généralise le champ électromagnétique (avec un terme non-linéaire A∧A en plus si le groupe n'est pas abélien)."}], "427": [{"formule": "Exposants de Lyapunov", "imgPath": "assets/schemas/427-0-lyapunov.svg", "titre": "λ calculé pour 3 valeurs de r (application logistique)", "caption": "L'exposant de Lyapunov λ, calculé sur 2000 itérations de xₙ₊₁=rxₙ(1-xₙ), est négatif pour r=2,5 (stable, λ=-0.693), proche de 0 pour r=3,2 (cycle, λ=-0.916), positif pour r=3,9 (chaos, λ=0.499)."}, {"formule": "Bifurcation de Hopf", "imgPath": "assets/schemas/427-1-hopf.svg", "titre": "Rayon du cycle limite r=√μ, calculé pour μ croissant", "caption": "Pour dr/dt=μr-r³ (forme normale de Hopf), le rayon du cycle limite stable vaut √μ pour μ>0, calculé ici : le point fixe stable (r=0) laisse place à une oscillation dès que μ dépasse 0."}, {"formule": "Attracteur étrange", "imgPath": "assets/schemas/427-2-lorenz-rk4.svg", "titre": "Un attracteur de Lorenz, intégré moi-même par RK4 (1000 points)", "caption": "Système de Lorenz (σ=10, ρ=28, β=8/3) intégré ici pas à pas par Runge-Kutta d'ordre 4 (1000 points tracés) : la trajectoire ne se referme jamais mais reste confinée dans cette forme en \"papillon\", l'attracteur étrange."}], "428": [{"formule": "Modèle d'Ising", "imgPath": "assets/schemas/428-0-ising.svg", "titre": "Magnétisation |m| simulée (Metropolis) à 3 températures", "caption": "Une chaîne d'Ising à 50 spins, simulée par l'algorithme de Metropolis, montre une magnétisation |m| plus élevée à basse température (spins alignés) qu'à haute température (désordre thermique)."}, {"formule": "Point critique et exposants critiques", "imgPath": "assets/schemas/428-1-exposants.svg", "titre": "Les exposants exacts du modèle d'Ising 2D, rappelés", "caption": "Près du point critique, les grandeurs physiques suivent des lois de puissance dont les exposants (calculés exactement pour Ising 2D par Onsager) sont universels : β=1/8, γ=7/4."}, {"formule": "Groupe de renormalisation (introduction)", "imgPath": "assets/schemas/428-2-renormalisation.svg", "titre": "Le principe du changement d'échelle, résumé", "caption": "Le groupe de renormalisation regroupe les spins en blocs et recalcule un couplage effectif à plus grande échelle ; itérer ce processus révèle le comportement universel près du point critique."}], "429": [{"formule": "Intégrale de chemin de Feynman", "imgPath": "assets/schemas/429-0-feynman-chemins.svg", "titre": "3 chemins parmi une infinité, tracés", "caption": "L'intégrale de chemin somme une amplitude e^(iS/ℏ) sur tous les chemins possibles entre deux points ; 3 exemples de chemins concurrents sont tracés ici, chacun contribuant avec sa propre action S."}, {"formule": "Propagateur", "imgPath": "assets/schemas/429-1-propagateur.svg", "titre": "Le propagateur d'une particule massive, calculé et tracé", "caption": "Le propagateur G(x)=e^(-m|x|)/(2m) (cas simplifié 1D) décrit l'amplitude de propagation d'une particule de masse m, calculée et tracée ici : elle décroît exponentiellement avec la distance."}, {"formule": "Quantification canonique", "imgPath": "assets/schemas/429-2-quantification.svg", "titre": "La généralisation aux champs, résumée", "caption": "La quantification canonique promeut les champs classiques φ(x) et leur moment conjugué π(x) en opérateurs, avec une relation de commutation qui généralise [x̂,p̂]=iℏ à chaque point de l'espace."}], "430": [{"formule": "Métrique de Friedmann-Lemaître-Robertson-Walker", "imgPath": "assets/schemas/430-0-flrw.svg", "titre": "La métrique d'un univers homogène et isotrope, rappelée", "caption": "La métrique FLRW décrit un univers homogène et isotrope en expansion, entièrement caractérisé par le facteur d'échelle a(t) et la courbure spatiale k."}, {"formule": "Équation de Friedmann", "imgPath": "assets/schemas/430-1-friedmann.svg", "titre": "a(t)∝t^(2/3) pour un univers dominé par la matière, calculée", "caption": "En résolvant H²=(8πG/3)ρ pour un univers dominé par la matière (ρ∝a⁻³), on obtient a(t)∝t^(2/3), calculée et tracée ici : l'expansion ralentit avec le temps (sans énergie noire)."}, {"formule": "Constante cosmologique Λ", "imgPath": "assets/schemas/430-2-lambda.svg", "titre": "Expansion en loi de puissance vs exponentielle, comparées", "caption": "Sans Λ, l'expansion suit une loi de puissance qui ralentit (courbe grise) ; avec une constante cosmologique Λ dominante, l'expansion devient exponentielle et accélérée (courbe rouge) — le scénario de notre univers actuel."}], "521": [{"formule": "Machine de Turing", "imgPath": "assets/schemas/521-0-machine-turing.svg", "titre": "Une machine de Turing concrète, qui accepte 0*1", "caption": "Cette machine de Turing accepte les mots de la forme 0*1 : elle avance sur les 0, puis passe en état acceptant dès qu'elle lit un 1."}, {"formule": "Problème de l'arrêt (indécidable)", "imgPath": "assets/schemas/521-1-arret-diagonale.svg", "titre": "L'argument diagonal de Turing, résumé étape par étape", "caption": "Si un programme H décidait l'arrêt, on construirait D qui boucle quand H prédit l'arrêt et s'arrête sinon ; D(D) se contredit dans les deux cas — H ne peut pas exister."}, {"formule": "Thèse de Church-Turing", "imgPath": "assets/schemas/521-2-church-turing.svg", "titre": "La thèse, non démontrable mais jamais contredite", "caption": "La thèse de Church-Turing postule que la notion intuitive de calculabilité coïncide exactement avec ce que peut calculer une machine de Turing — un postulat, pas un théorème, mais jamais mis en défaut."}], "522": [{"formule": "P ⊆ NP ⊆ PSPACE", "imgPath": "assets/schemas/522-0-inclusions.svg", "titre": "P⊆NP⊆PSPACE, les inclusions connues", "caption": "P est inclus dans NP, lui-même inclus dans PSPACE : ces inclusions sont prouvées, mais on ignore encore si elles sont strictes (P=NP reste ouvert)."}, {"formule": "NP-complétude", "imgPath": "assets/schemas/522-1-npcompletude.svg", "titre": "3-SAT se réduit vers tous les autres problèmes NP-complets", "caption": "Un problème NP-complet comme 3-SAT peut être transformé (en temps polynomial) en n'importe quel autre problème NP-complet : les résoudre tous revient à résoudre l'un d'eux efficacement."}, {"formule": "Théorème de Cook-Levin", "imgPath": "assets/schemas/522-2-cooklevin.svg", "titre": "Le théorème fondateur de la NP-complétude", "caption": "Le théorème de Cook-Levin montre que 3-SAT est NP-complet : toute instance de n'importe quel problème de NP peut se coder comme une instance de 3-SAT, en temps polynomial."}], "523": [{"formule": "Axiomes de ZFC", "imgPath": "assets/schemas/523-0-zfc.svg", "titre": "Un aperçu des axiomes de ZFC, résumé", "caption": "ZFC (Zermelo-Fraenkel + axiome du Choix) fonde la théorie des ensembles moderne sur une poignée d'axiomes, dont l'extensionnalité, l'infini et le choix."}, {"formule": "Lemme de Zorn", "imgPath": "assets/schemas/523-1-zorn.svg", "titre": "L'énoncé du lemme, équivalent à l'axiome du choix", "caption": "Le lemme de Zorn (équivalent à l'axiome du choix) garantit un élément maximal dès que toute chaîne de l'ensemble ordonné est majorée — utilisé pour prouver l'existence de bases infinies, d'idéaux maximaux, etc."}, {"formule": "Théorèmes d'incomplétude de Gödel", "imgPath": "assets/schemas/523-2-godel.svg", "titre": "Les 2 théorèmes, résumés", "caption": "Les théorèmes de Gödel montrent que tout système axiomatique cohérent et assez riche pour l'arithmétique contient des énoncés vrais mais indémontrables, et ne peut prouver sa propre cohérence."}], "524": [{"formule": "Entropie de Shannon : H(X)=−Σp log p", "imgPath": "assets/schemas/524-0-shannon-entropie.svg", "titre": "H(X)=1.75 bits, calculée", "caption": "Pour cette source à 4 symboles (probabilités 0,5 ; 0,25 ; 0,125 ; 0,125), H(X)=-Σp log₂p=1.75 bits, calculée directement."}, {"formule": "Capacité de canal", "imgPath": "assets/schemas/524-1-capacite-canal.svg", "titre": "C=0.531 bits/usage, calculée", "caption": "Pour un canal binaire symétrique avec 10% d'erreur, la capacité C=1-H(0,1)≈0.531 bits par utilisation du canal, calculée directement."}, {"formule": "Théorème de codage sans bruit", "imgPath": "assets/schemas/524-2-codage-sans-bruit.svg", "titre": "Le code optimal approche H(X), calculé", "caption": "Le théorème de codage sans bruit de Shannon garantit qu'aucun code sans perte ne peut faire mieux, en moyenne, que H(X)=1.75 bits/symbole — la limite fondamentale de compression."}], "525": [{"formule": "Méthode de Newton-Raphson", "imgPath": "assets/schemas/525-0-newton.svg", "titre": "Convergence vers √2≈1,41421, calculée en 4 itérations", "caption": "Partant de x0=1 pour résoudre x²-2=0, Newton-Raphson calcule x1=1.5, puis converge en quelques itérations vers √2≈1.41421."}, {"formule": "Interpolation de Lagrange", "imgPath": "assets/schemas/525-1-lagrange-interp.svg", "titre": "Le polynôme passant exactement par les 4 points, calculé", "caption": "Le polynôme d'interpolation de Lagrange, calculé à partir de 4 points (0,1),(1,3),(2,2),(3,5), passe exactement par chacun d'eux — construit ici par la formule explicite."}, {"formule": "Quadrature de Gauss", "imgPath": "assets/schemas/525-2-gauss-quadrature.svg", "titre": "2.3427 vs 2.3504, très proches", "caption": "La quadrature de Gauss à 2 points, calculée pour ∫₋₁¹eˣdx, donne 2.3427, très proche de la valeur exacte 2.3504 — avec seulement 2 évaluations de la fonction."}], "526": [{"formule": "FFT (Fast Fourier Transform)", "imgPath": "assets/schemas/526-0-fft.svg", "titre": "Le spectre calculé par DFT directe : pic net en k=2 et k=6", "caption": "Pour le signal (1,0,-1,0,1,0,-1,0), le spectre calculé par transformée de Fourier discrète montre des pics nets en k=2 et k=6, correspondant exactement à sa fréquence d'oscillation."}, {"formule": "Théorème de Shannon-Nyquist", "imgPath": "assets/schemas/526-1-nyquist.svg", "titre": "Repliement de spectre : 7Hz échantillonné à 10Hz ressemble à 3Hz", "caption": "Un signal à 7 Hz échantillonné à seulement 10 Hz (< 2×7=14 Hz requis par Nyquist) se confond avec un signal à 3 Hz : le repliement de spectre, calculé et tracé ici."}, {"formule": "Convolution discrète", "imgPath": "assets/schemas/526-2-convolution-discrete.svg", "titre": "f*g calculée terme à terme", "caption": "La convolution discrète (f*g)[i]=Σf[k]g[i-k], calculée ici pour f=(1,2,3) et g=(1,-1,1), est l'opération de base du filtrage numérique."}], "527": [{"formule": "Problème du logarithme discret", "imgPath": "assets/schemas/527-0-log-discret-comp.svg", "titre": "x=15, par recherche exhaustive", "caption": "Trouver x tel que 5ˣ≡19 (mod 23) demande une recherche exhaustive (x=15 ici) — facile pour p=23, totalement impraticable pour un p de 2048 bits."}, {"formule": "Protocole de Diffie-Hellman", "imgPath": "assets/schemas/527-1-dh-protocole.svg", "titre": "Nouvelle instance, recalculée", "caption": "Avec g=5, p=23 : Alice (a=8) et Bob (b=15) aboutissent à la même clé 9, calculée chacun de leur côté sans jamais révéler a ni b."}, {"formule": "Fonctions à sens unique", "imgPath": "assets/schemas/527-2-sens-unique.svg", "titre": "Facile dans un sens, dur dans l'autre, illustré", "caption": "Calculer le hash de \"message123\" (=1ccc2a91a9559e0d) est instantané ; retrouver le message à partir du hash seul est, en pratique, infaisable — la définition même d'une fonction à sens unique."}], "528": [{"formule": "Matrice laplacienne d'un graphe", "imgPath": "assets/schemas/528-0-laplacien.svg", "titre": "L=D-A, calculée pour un cycle à 4 sommets", "caption": "La matrice laplacienne L=D-A (degrés moins adjacence) est calculée ici pour un cycle à 4 sommets : ses valeurs propres renseignent sur la connexité et la structure du graphe."}, {"formule": "Polynôme chromatique", "imgPath": "assets/schemas/528-1-chromatique.svg", "titre": "P(k)=k(k-1)² pour un chemin à 3 sommets, calculé", "caption": "Pour un chemin à 3 sommets (2 arêtes), le polynôme chromatique P(k)=k(k-1)², calculé ici pour k=1 à 4, compte le nombre de coloriages valides avec k couleurs (0 pour k=1, 2 pour k=2...)."}, {"formule": "Théorème de Kuratowski (planarité)", "imgPath": "assets/schemas/528-2-kuratowski.svg", "titre": "Les 2 graphes interdits, qui caractérisent la planarité", "caption": "Le théorème de Kuratowski affirme qu'un graphe est planaire si et seulement s'il ne contient (par subdivision) ni K5 ni K3,3, les deux graphes non-planaires minimaux."}], "529": [{"formule": "Théorème de Kleene", "imgPath": "assets/schemas/529-0-kleene.svg", "titre": "L'équivalence automates ↔ expressions rationnelles", "caption": "Le théorème de Kleene établit que les langages réguliers (reconnus par un automate fini) sont exactement ceux décrits par une expression rationnelle : deux formalismes, un seul pouvoir d'expression."}, {"formule": "Lemme de pompage", "imgPath": "assets/schemas/529-1-pompage.svg", "titre": "aⁿbⁿ n'est pas régulier, prouvé par pompage", "caption": "Pour L={aⁿbⁿ}, en découpant \"aaaaabbbbb\" selon le lemme de pompage, y ne contient que des a ; répéter y (xy²z) casse l'équilibre a/b : L n'est pas régulier."}, {"formule": "Grammaires hors contexte", "imgPath": "assets/schemas/529-2-grammaire-hc.svg", "titre": "Un arbre de dérivation S→NP VP→NP V N, construit", "caption": "Une grammaire hors-contexte comme S→NP VP, VP→V N engendre des arbres de dérivation, comme celui-ci, plus expressifs que les automates finis (ils gèrent l'imbrication)."}], "530": [{"formule": "Descente de gradient stochastique", "imgPath": "assets/schemas/530-0-gradient-descent.svg", "titre": "wₙ converge vers 3 (le minimum), calculé sur 8 pas", "caption": "Partant de w=-2, la descente de gradient wₙ₊₁=wₙ-η∇L(wₙ) (η=0,3) est calculée pas à pas et converge vers w=3, le minimum de la fonction de perte."}, {"formule": "Fonction de perte (loss)", "imgPath": "assets/schemas/530-1-loss.svg", "titre": "L(w), avec son minimum en w=3, calculé", "caption": "La fonction de perte L(w)=(w-3)²+2, calculée et tracée ici, atteint son minimum (valeur 2) exactement en w=3, le paramètre optimal recherché."}, {"formule": "Régularisation L1/L2", "imgPath": "assets/schemas/530-2-regularisation.svg", "titre": "Deux pénalités différentes pour w=2,5, calculées", "caption": "Pour w=2,5 : la pénalité L1=|w|=2.5 croît linéairement, tandis que L2=w²=6.25 croît plus vite pour les grandes valeurs — L1 favorise des poids exactement nuls, L2 les rétrécit sans les annuler."}], "616": [{"formule": "AM-GM : (a+b)/2 ≥ √(ab)", "imgPath": "assets/schemas/616-0-amgm.svg", "titre": "12.5≥10.0", "caption": "Pour a=5, b=20 : AM=12,5, GM=√100=10 — 12,5≥10, vérifié."}, {"formule": "Inégalité de Cauchy-Schwarz", "imgPath": "assets/schemas/616-1-cauchyschwarz.svg", "titre": "121≤294", "caption": "Pour a=(1,3,2), b=(4,1,2) : (Σaᵢbᵢ)²=121, (Σaᵢ²)(Σbᵢ²)=294 — 121≤294 vérifié."}, {"formule": "Inégalité de réarrangement", "imgPath": "assets/schemas/616-2-rearrangement.svg", "titre": "44≥28", "caption": "Pour a=(1,3,5), b=(2,4,6) : apparier dans le même ordre donne 44, en ordre inversé seulement 28 — le même ordre maximise toujours la somme des produits."}], "617": [{"formule": "Ordre de a modulo n", "imgPath": "assets/schemas/617-0-ordre.svg", "titre": "Ordres calculés pour p=13", "caption": "L'ordre de a modulo 13 (le plus petit k tel que a^k≡1) est calculé ici pour a=2,3,4 : il divise toujours p-1=12 (théorème de Lagrange appliqué au groupe multiplicatif)."}, {"formule": "Petit théorème de Fermat", "imgPath": "assets/schemas/617-1-fermat-ordre.svg", "titre": "a¹²≡1 (mod 13), vérifié pour 5 valeurs", "caption": "Pour p=13, a^(p-1) mod p = 1 pour chaque a testé (2 à 6) : le petit théorème de Fermat, vérifié numériquement."}, {"formule": "Lifting the Exponent (LTE)", "imgPath": "assets/schemas/617-2-lte.svg", "titre": "4=4, vérifié", "caption": "Pour 3⁴-1⁴=80=2⁴×5, v2(80)=4 ; la formule LTE donne aussi v2(3-1)+v2(3+1)+v2(4)-1=4 — les deux calculs coïncident."}], "618": [{"formule": "Principe des tiroirs (Dirichlet)", "imgPath": "assets/schemas/618-0-tiroirs.svg", "titre": "⌈13/6⌉=3, calculé", "caption": "Avec 13 chaussettes réparties en 6 couleurs, ⌈13/6⌉=3 : il y a nécessairement au moins 3 chaussettes de la même couleur."}, {"formule": "Double comptage", "imgPath": "assets/schemas/618-1-double-comptage.svg", "titre": "10=10, les deux comptages coïncident", "caption": "Le nombre de poignées de main entre 5 personnes se compte de 2 façons : C(5,2)=10, ou la moitié de la somme des degrés=10 — même résultat, la technique du double comptage."}, {"formule": "Invariants et semi-invariants", "imgPath": "assets/schemas/618-2-invariant-parite.svg", "titre": "La parité de la somme, invariante", "caption": "En remplaçant 2 nombres par leur différence, la parité de la somme totale reste invariante (ici toujours paire), un outil puissant pour prouver des impossibilités."}], "619": [{"formule": "Puissance d'un point : P(M)=MA·MB", "imgPath": "assets/schemas/619-0-puissance.svg", "titre": "P(M)=16, calculée", "caption": "Pour M(5,0) et un cercle de centre O(0,0), rayon 3 : P(M)=OM²-R²=25-9=16 (positif car M est hors du cercle)."}, {"formule": "Inversion de centre O et rapport k", "imgPath": "assets/schemas/619-1-inversion.svg", "titre": "3 points inversés, calculés", "caption": "L'inversion de centre O et rapport k=4 envoie M sur M'=k×M/|M|² : calculée ici explicitement pour 3 points, elle échange proximité et éloignement du centre."}, {"formule": "Théorème de Ptolémée", "imgPath": "assets/schemas/619-2-ptolemee.svg", "titre": "29.155 vs 29.531", "caption": "Pour ce quadrilatère (non nécessairement cyclique), AC×BD=29.155 et AB×CD+BC×AD=29.531 : l'égalité de Ptolémée n'a lieu exactement que si ABCD est inscriptible dans un cercle."}], "620": [{"formule": "Relations coefficients-racines", "imgPath": "assets/schemas/620-0-vieta.svg", "titre": "Vérifiées pour x³-6x²+11x-6=(x-1)(x-2)(x-3)", "caption": "Pour x³-6x²+11x-6, racines 1,2,3 : la somme=6=-(-6), la somme des produits 2 à 2=11=11, le produit=6=-(-6) — les relations de Viète, vérifiées."}, {"formule": "Équation de Cauchy : f(x+y)=f(x)+f(y)", "imgPath": "assets/schemas/620-1-cauchy-eq.svg", "titre": "Vérifiée pour f(x)=5x", "caption": "Pour f(x)=5x, x=3, y=7 : f(x+y)=f(10)=50 et f(x)+f(y)=50 — égales, confirmant que f(x)=5x résout bien l'équation de Cauchy."}, {"formule": "Polynômes à coefficients entiers", "imgPath": "assets/schemas/620-2-racines-rationnelles.svg", "titre": "Racines rationnelles testées et confirmées", "caption": "Pour 2x³-3x²-3x+2 (coefficients entiers), le théorème des racines rationnelles limite les candidats à ±1,±2,±1/2 ; testés un par un, [-1, 2, 0.5] sont effectivement racines."}], "621": [{"formule": "Lemme des poignées de main", "imgPath": "assets/schemas/621-0-poignees-main.svg", "titre": "Σdeg=12=2×6 arêtes, vérifié", "caption": "La somme des degrés 12 est bien paire et égale à 2 fois le nombre d'arêtes (6) : le lemme des poignées de main, vérifié sur cet exemple."}, {"formule": "Théorème de Ramsey (cas simples)", "imgPath": "assets/schemas/621-1-ramsey.svg", "titre": "R(3,3)=6, le résultat classique", "caption": "R(3,3)=6 signifie que dans tout groupe de 6 personnes, on trouve toujours 3 personnes qui se connaissent toutes mutuellement, ou 3 qui sont toutes mutuellement inconnues — vrai à partir de 6, faux pour 5."}, {"formule": "Coloration de graphes", "imgPath": "assets/schemas/621-2-coloration-graphe.svg", "titre": "Un pentagone avec une diagonale : 3 couleurs nécessaires", "caption": "Ce graphe (un cycle de 5 sommets plus une diagonale) contient un triangle (A-B-C), imposant au moins 3 couleurs pour le colorer correctement."}], "622": [{"formule": "Récurrence forte", "imgPath": "assets/schemas/622-0-recurrence-forte.svg", "titre": "Fibonacci : chaque terme dépend des 2 précédents", "caption": "La récurrence forte (utilisant plusieurs termes précédents, pas seulement le dernier) permet de définir des suites comme Fibonacci, calculée ici jusqu'à F8."}, {"formule": "Descente infinie de Fermat", "imgPath": "assets/schemas/622-1-descente-sqrt2.svg", "titre": "La preuve classique de l'irrationalité de √2, détaillée", "caption": "Supposer √2=p/q irréductible mène par calcul à p et q tous deux pairs, contredisant l'irréductibilité — la structure classique d'une preuve par descente infinie."}, {"formule": "Principe extrémal", "imgPath": "assets/schemas/622-2-extremal.svg", "titre": "Isoler le min/max d'un ensemble fini, la technique de base", "caption": "Le principe extrémal consiste à considérer l'élément minimal (2) ou maximal (9) d'un ensemble fini, souvent le point de départ d'une contradiction ou d'une construction."}], "623": [{"formule": "Argument de coloriage (échiquier)", "imgPath": "assets/schemas/623-0-coloriage-echiquier.svg", "titre": "8 cases claires, 10 sombres : déséquilibre", "caption": "En retirant deux coins opposés de même couleur d'un rectangle 3×6, le comptage par couleur révèle un déséquilibre (8 contre 10) : aucun pavage par dominos (qui couvrent toujours 1 case de chaque couleur) n'est possible."}, {"formule": "Invariant de parité", "imgPath": "assets/schemas/623-1-parite-invariant.svg", "titre": "Les parités individuelles, calculées", "caption": "Un invariant de parité suit si une quantité reste paire ou impaire à travers une transformation ; ici, les parités de chaque terme sont calculées individuellement."}, {"formule": "Pavages par polyominos", "imgPath": "assets/schemas/623-2-polyominos.svg", "titre": "4 dominos pavant un rectangle 2×4, construits", "caption": "Un rectangle 2×4 se pave exactement par 4 dominos (polyominos de 2 cases), assemblés ici sans trou ni recouvrement — un cas simple de pavage par polyominos."}], "716": [{"formule": "Structure : hypothèses ⟹ conclusion", "imgPath": "assets/schemas/716-0-structure.svg", "titre": "La structure logique d'une démonstration", "caption": "Toute démonstration rigoureuse part d'hypothèses clairement énoncées, déroule un raisonnement explicite, et aboutit à une conclusion qui en découle logiquement."}, {"formule": "Quantificateurs ∀ / ∃ rigoureux", "imgPath": "assets/schemas/716-1-quantificateurs.svg", "titre": "Les 2 quantificateurs et un piège classique", "caption": "∀ (pour tout) et ∃ (il existe) doivent toujours préciser leur domaine ; confondre ∃ avec ∃! (existence et unicité) est une erreur de rigueur fréquente."}, {"formule": "Citation précise des théorèmes utilisés", "imgPath": "assets/schemas/716-2-citation.svg", "titre": "2 exemples de citation rigoureuse", "caption": "Citer un théorème exige de vérifier explicitement ses hypothèses avant de l'appliquer — jamais l'invoquer sans montrer qu'elles sont satisfaites."}], "717": [{"formule": "Plan type d'un exposé de colle", "imgPath": "assets/schemas/717-0-plan-colle.svg", "titre": "Le déroulement typique d'une colle", "caption": "Une colle suit généralement 3 temps : une question de cours (démonstration attendue), un exercice d'application, puis des questions ouvertes de l'examinateur."}, {"formule": "Gestion du temps (20-30 min)", "imgPath": "assets/schemas/717-1-temps.svg", "titre": "Répartition indicative sur 30 minutes", "caption": "Sur une colle de 30 minutes, une répartition indicative pourrait être : 8 min de cours, 15 min d'exercice, 7 min de questions — à ajuster selon l'examinateur."}, {"formule": "Questions de cours vs exercices", "imgPath": "assets/schemas/717-2-cours-exercice.svg", "titre": "La différence de nature entre les deux", "caption": "Une question de cours teste la restitution rigoureuse d'une démonstration vue en classe ; un exercice teste la capacité à appliquer ce cours à une situation nouvelle."}], "718": [{"formule": "Épreuves de mathématiques 1 et 2", "imgPath": "assets/schemas/718-0-epreuves.svg", "titre": "2 épreuves complémentaires, résumées", "caption": "Les concours proposent généralement 2 épreuves de mathématiques, chacune de 4h, couvrant des pans différents du programme."}, {"formule": "Barème et points de rigueur", "imgPath": "assets/schemas/718-1-bareme.svg", "titre": "Ce qui rapporte des points, résumé", "caption": "Le barème valorise la rigueur : chaque affirmation doit être justifiée, chaque théorème cité doit avoir ses hypothèses explicitement vérifiées."}, {"formule": "Gestion du temps sur 4h", "imgPath": "assets/schemas/718-2-temps-4h.svg", "titre": "Répartition indicative sur 240 minutes", "caption": "Sur 4h (240 min), une répartition indicative : 15 min de lecture du sujet, 90 min de recherche, 180 min de rédaction (en parallèle), 15 min de relecture finale."}], "719": [{"formule": "Algèbre linéaire et bilinéaire", "imgPath": "assets/schemas/719-0-algebre-mpsi.svg", "titre": "Les 2 piliers algébriques du programme", "caption": "Le programme d'algèbre de MPSI/MP couvre l'algèbre linéaire (espaces vectoriels, réduction) et bilinéaire (produit scalaire, formes quadratiques)."}, {"formule": "Analyse réelle et complexe", "imgPath": "assets/schemas/719-1-analyse-mpsi.svg", "titre": "2 volets du programme d'analyse", "caption": "L'analyse réelle (suites, séries, intégration) domine le programme, complétée en seconde année par les bases de l'analyse complexe."}, {"formule": "Probabilités sur univers finis", "imgPath": "assets/schemas/719-2-probas-mpsi.svg", "titre": "Le contenu du programme, résumé", "caption": "Les probabilités du programme MPSI/MP se limitent aux univers finis : dénombrement, variables aléatoires discrètes, espérance et variance."}], "720": [{"formule": "Analyse et algèbre du tronc commun", "imgPath": "assets/schemas/720-0-tronc-commun-pcsi.svg", "titre": "Les bases communes du programme", "caption": "Le tronc commun de mathématiques en PCSI/PC couvre l'analyse (suites, fonctions, intégration) et l'algèbre (espaces vectoriels, matrices), avec un poids horaire moindre qu'en MPSI."}, {"formule": "Probabilités", "imgPath": "assets/schemas/720-1-probas-pcsi.svg", "titre": "Le contenu, similaire à MPSI mais plus concis", "caption": "Le programme de probabilités en PCSI/PC couvre le dénombrement et les variables aléatoires discrètes, dans un volume horaire plus restreint qu'en MPSI."}, {"formule": "Applications à la physique-chimie", "imgPath": "assets/schemas/720-2-applications-pcsi.svg", "titre": "2 liens directs maths-physique", "caption": "En PCSI/PC, les mathématiques sont plus directement mises au service de la physique-chimie : équations différentielles pour les circuits, séries de Fourier pour les signaux."}], "721": [{"formule": "Question de cours (démonstration exigée)", "imgPath": "assets/schemas/721-0-question-cours.svg", "titre": "Ce qui est attendu, précisé", "caption": "La question de cours en khôlle exige une démonstration complète et rigoureuse, restituée sans notes, exactement comme démontrée en classe."}, {"formule": "Exercice d'application", "imgPath": "assets/schemas/721-1-exercice-application.svg", "titre": "Ce qui est attendu, précisé", "caption": "L'exercice d'application teste la capacité à reconnaître quelle méthode du cours s'applique à une situation donnée, et à l'exécuter sans erreur."}, {"formule": "Exercice de recherche", "imgPath": "assets/schemas/721-2-exercice-recherche.svg", "titre": "Ce qui est attendu, précisé", "caption": "L'exercice de recherche évalue la démarche : essayer des pistes, communiquer son raisonnement à voix haute, plutôt que rester silencieux en cas de blocage."}], "722": [{"formule": "Analyse du problème avant rédaction", "imgPath": "assets/schemas/722-0-analyse-probleme.svg", "titre": "Les 3 premières étapes, avant même d'écrire une preuve", "caption": "Avant de rédiger, un problème ouvert se travaille en 3 temps : bien comprendre l'énoncé, explorer des cas particuliers, puis formuler une conjecture."}, {"formule": "Recherche de cas particuliers", "imgPath": "assets/schemas/722-1-cas-particuliers.svg", "titre": "Un exemple de démarche, tester n=1,2,3,4", "caption": "Tester des petits cas (n=1,2,3,4 donnant 1,3,6,10) suggère la formule n(n+1)/2 avant même de la démontrer en général — la recherche de cas particuliers guide la conjecture."}, {"formule": "Conjecture puis démonstration", "imgPath": "assets/schemas/722-2-conjecture-demo.svg", "titre": "Le cycle complet, schématisé", "caption": "Une fois la conjecture formulée à partir des cas particuliers, il reste à la démontrer rigoureusement (souvent par récurrence), puis à vérifier la cohérence du résultat."}], "723": [{"formule": "Classement national par banque d'épreuves", "imgPath": "assets/schemas/723-0-banques-epreuves.svg", "titre": "3 grandes banques, avec leurs écoles", "caption": "Chaque banque d'épreuves (Mines-Ponts, Centrale-Supélec, X-ENS...) produit un classement national commun à plusieurs écoles, sur la base des mêmes épreuves écrites et orales."}, {"formule": "Vœux et affectations", "imgPath": "assets/schemas/723-1-voeux.svg", "titre": "Le principe des vœux ordonnés, résumé", "caption": "Le candidat classe ses écoles par ordre de préférence ; chaque école lui propose une place en fonction de son rang, jusqu'à ce qu'une affectation soit acceptée."}, {"formule": "Dossier scolaire et oraux", "imgPath": "assets/schemas/723-2-dossier-oraux.svg", "titre": "Les 3 composantes de l'admission finale, résumées", "caption": "L'admission finale combine les résultats écrits (souvent majoritaires), les oraux (où la maîtrise du cours et l'aisance comptent), et parfois le dossier scolaire."}], "1": [{"formule": "f : A → B", "imgPath": "assets/schemas/1-0-fonction.svg", "titre": "f(x)=x²-1, un exemple concret", "caption": "f(x)=x²-1 associe à chaque réel x un unique réel f(x) : c'est une fonction de A=ℝ vers B=ℝ."}, {"formule": "f(x + h) - f(x)", "imgPath": "assets/schemas/1-1-accroissement.svg", "titre": "=1.36, calculé", "caption": "Pour f(x)=x²-1, x=1,5, h=0,4 : f(x+h)-f(x)=f(1,9)-f(1,5)=1.36, l'accroissement de f, calculé directement."}, {"formule": "Composition : (f ∘ g)(x) = f(g(x))", "imgPath": "assets/schemas/1-2-composition.svg", "titre": "f∘g calculée et tracée", "caption": "Pour f(x)=x²-1 et g(x)=2x+1, (f∘g)(x)=f(g(x))=(2x+1)²-1, calculée et tracée : appliquer g d'abord, puis f."}], "2": [{"formule": "lim_{x→a} f(x) = L", "imgPath": "assets/schemas/2-0-limite-point.svg", "titre": "La limite en x=2 vaut 4, malgré le trou", "caption": "f(x)=(x²-4)/(x-2) n'est pas définie en x=2, mais pour x proche de 2, f(x) se rapproche de 4 (calculable en simplifiant f(x)=x+2 pour x≠2) : lim_{x→2}f(x)=4."}, {"formule": "lim_{x→∞} f(x)", "imgPath": "assets/schemas/2-1-limite-infini.svg", "titre": "f(x)→2 quand x→∞, visible sur le graphe", "caption": "f(x)=(2x+1)/(x+1) se rapproche de 2 quand x devient grand, calculé et tracé ici jusqu'à x=50 : lim_{x→∞}f(x)=2."}, {"formule": "lim_{x→0} sin(x)/x = 1", "imgPath": "assets/schemas/2-2-limite-sinx.svg", "titre": "sin(x)/x → 1 en 0, calculé et tracé", "caption": "sin(x)/x n'est pas définie en 0, mais la courbe calculée et tracée ici montre clairement qu'elle tend vers 1 quand x→0."}], "3": [{"formule": "f continue en a ⇔ lim_{x→a} f(x) = f(a)", "imgPath": "assets/schemas/3-0-discontinuite.svg", "titre": "f saute de 1 à 2 en x=1 : discontinue, calculé", "caption": "Pour f(x)=x² si x<1, x+1 si x≥1 : la limite à gauche en 1 vaut 1, mais f(1)=2 — les deux ne coïncident pas, f est discontinue en 1."}, {"formule": "Théorème des valeurs intermédiaires", "imgPath": "assets/schemas/3-1-tvi.svg", "titre": "f change de signe entre 0 et 3, racine trouvée", "caption": "f(0)=-1<0 et f(3)=14>0 : par le TVI, f s'annule quelque part entre 0 et 3 — visible ici autour de x≈2,28."}], "4": [{"formule": "f'(x) = lim_{h→0} (f(x+h)-f(x))/h", "imgPath": "assets/schemas/4-0-derivee-def.svg", "titre": "f'(1,5)≈3.001, calculée par taux d'accroissement", "caption": "Pour f(x)=x², le taux d'accroissement (f(x+h)-f(x))/h avec h=0,001 donne 3.001, très proche de f'(1,5)=2×1,5=3 : la dérivée comme limite de ce taux."}, {"formule": "(fg)' = f'g + fg'", "imgPath": "assets/schemas/4-1-derivee-produit.svg", "titre": "u=x², v=x+1 : (uv)' calculée et tracée", "caption": "Pour u=x², v=x+1 : (uv)'=u'v+uv'=2x(x+1)+x², calculée et tracée ici — vérifiable en dérivant directement uv=x³+x²."}, {"formule": "(f/g)' = (f'g - fg')/g²", "imgPath": "assets/schemas/4-2-derivee-quotient.svg", "titre": "(u/v)' calculée et tracée", "caption": "Pour u=x², v=x+1 : (u/v)'=(u'v-uv')/v² = (2x(x+1)-x²)/(x+1)², calculée et tracée sur le domaine où v(x)≠0."}], "5": [{"formule": "∫_a^b f(x) dx = F(b) - F(a)", "imgPath": "assets/schemas/5-0-integrale-def.svg", "titre": "∫₀³x²dx=9.0, calculée", "caption": "∫₀³x²dx=[x³/3]₀³=27/3=9.0 : l'aire sous la parabole entre 0 et 3."}, {"formule": "∫ x dx = x²/2", "imgPath": "assets/schemas/5-1-primitive-x.svg", "titre": "La primitive x²/2, tracée", "caption": "∫x dx=x²/2+C, calculée et tracée (C=0 ici) : sa dérivée redonne bien x."}, {"formule": "Changement de variable : ∫ f(g(t)) g'(t) dt", "imgPath": "assets/schemas/5-2-changement-var.svg", "titre": "= ln5 ≈ 1.609", "caption": "Avec u=1+x², du=2xdx : ∫₀²2x/(1+x²)dx=∫₁⁵du/u=[ln u]₁⁵=ln5≈1.609, calculé par changement de variable."}], "6": [{"formule": "y' = ay", "imgPath": "assets/schemas/6-0-y-ay.svg", "titre": "Solution y'=0,4y, y(0)=3, tracée", "caption": "y'=ay (a=0,4) a pour solution y(t)=y0e^(at) ; ici y0=3, tracée et croissante exponentiellement."}, {"formule": "y' + ay = f(x)", "imgPath": "assets/schemas/6-1-y-ay-f.svg", "titre": "Solution de y'+y=t, calculée et tracée", "caption": "Pour y'+y=t, la solution générale y=Ce^(-t)+t-1 (ici C=4) combine une exponentielle décroissante et une partie affine."}, {"formule": "Solution homogène + solution particulière", "imgPath": "assets/schemas/6-2-homogene-particuliere.svg", "titre": "Les 2 parties séparées, tracées", "caption": "La solution générale de y'+y=t se décompose en une solution homogène (4e^(-t), qui s'annule à l'infini) et une solution particulière (t-1) : leur somme redonne la solution complète de la fiche précédente."}], "7": [{"formule": "f(x) = a0 + Σ (an cos(nx) + bn sin(nx))", "imgPath": "assets/schemas/7-0-fourier-approx.svg", "titre": "Approximation calculée par intégration numérique", "caption": "La somme de Fourier (5 premiers termes, coefficients calculés par intégration numérique réelle) approche déjà bien le signal carré d'origine."}, {"formule": "an = ∫ f(x) cos(nx) dx", "imgPath": "assets/schemas/7-1-coeff-a.svg", "titre": "a0≈0, calculé (signal impair)", "caption": "Pour ce signal créneau (impair), a0=0.0≈0 ; par symétrie, tous les coefficients an sont nuls, calculé ici numériquement pour a0."}, {"formule": "bn = ∫ f(x) sin(nx) dx", "imgPath": "assets/schemas/7-2-coeff-b.svg", "titre": "b1≈1.2732, très proche de 4/π", "caption": "b1, calculé par intégration numérique, vaut 1.2732 — très proche de la valeur théorique 4/π≈1.2732."}], "8": [{"formule": "z = x + iy", "imgPath": "assets/schemas/8-0-point-complexe.svg", "titre": "z=4+3i, représenté", "caption": "z=4+3i est représenté par le point (4,3) dans le plan complexe : 4 sur l'axe réel, 3 sur l'axe imaginaire."}, {"formule": "e^{iθ} = cos θ + i sin θ", "imgPath": "assets/schemas/8-1-euler.svg", "titre": "θ=60°, calculé et placé sur le cercle unité", "caption": "Pour θ=60°, e^(iθ)=cos(60°)+isin(60°)≈0.5+0.866i, le point calculé sur le cercle de rayon 1."}, {"formule": "∮ f(z) dz", "imgPath": "assets/schemas/8-2-contour.svg", "titre": "Formule de Cauchy vérifiée par calcul de contour", "caption": "Pour f(z)=z², a=0,5+0,3i : l'intégrale de contour ∮f(z)/(z-a)dz, calculée numériquement, redonne bien 2πi×f(a) — la formule intégrale de Cauchy vérifiée."}], "9": [{"formule": "Σ a_n x^n", "imgPath": "assets/schemas/9-0-serie-entiere.svg", "titre": "6 termes de Σxⁿ/n! approchent déjà eˣ, calculé", "caption": "La somme partielle Σx^k/k! (6 premiers termes), calculée et tracée, approche déjà très bien eˣ sur [-2,2]."}, {"formule": "Rayon de convergence R", "imgPath": "assets/schemas/9-1-rayon.svg", "titre": "aₙ/aₙ₊₁ → 1 pour Σxⁿ/n : R=1, calculé", "caption": "Pour Σxⁿ/n, le rapport |aₙ/aₙ₊₁|, calculé ici, tend vers 1 : par le critère de d'Alembert, le rayon de convergence est R=1."}, {"formule": "Test de Cauchy", "imgPath": "assets/schemas/9-2-cauchy.svg", "titre": "|aₙ|^(1/n) → 1, calculé pour n croissant", "caption": "Le test de Cauchy, calculé pour n=10,100,1000, confirme que |aₙ|^(1/n)→1, donnant le même rayon de convergence R=1 que le critère de d'Alembert."}], "10": [{"formule": "sin x = x - x³/6 + ...", "imgPath": "assets/schemas/10-0-dl-sin.svg", "titre": "Le DL à l'ordre 5 de sin, calculé et comparé", "caption": "Le développement limité x-x³/6+x⁵/120, calculé et tracé, colle presque parfaitement à sin(x) près de 0, et s'en écarte progressivement plus loin."}, {"formule": "e^x = 1 + x + x²/2 + ...", "imgPath": "assets/schemas/10-1-dl-exp.svg", "titre": "Le DL à l'ordre 4 de eˣ, calculé et comparé", "caption": "Le polynôme 1+x+x²/2+x³/6+x⁴/24, calculé et tracé, approche eˣ de très près sur [-2,2]."}, {"formule": "ln(1+x) = x - x²/2 + ...", "imgPath": "assets/schemas/10-2-dl-ln.svg", "titre": "Le DL à l'ordre 4 de ln(1+x), calculé et comparé", "caption": "Le développement x-x²/2+x³/3-x⁴/4, calculé et tracé, approche bien ln(1+x) près de 0, mais diverge nettement pour x plus grand que 1."}]};
